(window.GIM_TS=window.GIM_TS||{})["Temurah.1"]={"from":24,"a":[["\u0003יש\u0004 הלכות הנוהגות \u0003בקרבנות\u0004 ה\u0003יחיד שאין\u0004 נוהגות \u0003בקרבנות הציבור. ויש\u0004 הלכות הנוהגות \u0003בקרבנות הציבור שאין\u0004 נוהגות \u0003בקרבנות היחיד.\u0004 ואלו הנוהגות בקרבן יחיד ואינן נוהגות בקרבן ציבור: \u0003שקרבנות היחיד עושין תמורה, ואין קרבנות הציבור עושין תמורה.\u0004","ועוד הבדל: ש\u0003קרבנות היחיד נוהגות בין\u0004 \u0003בזכרים בין בנקבות, ו\u0004אילו \u0003קרבנות הציבור אין נוהגין אלא בזכרים.\u0004 ועוד: ש\u0003קרבנות היחיד חייבין\u0004 הבעלים \u0003באחריותן,\u0004 שאם לא הובאו בזמנם הראוי, חייבים להביאם אחר כך, \u0003ובאחריות נסכיהם\u0004 (היין והמנחה הנלווים לקרבן) של הקרבנות. \u0003ו\u0004אילו ב\u0003קרבנות הציבור אין חייבין\u0004 לא \u0003באחריותן ולא באחריות נסכיהן, אבל חייבין באחריות נסכיהן מ\u0004אחר \u0003שקרב הזבח\u0004 בזמנו. שאם קרב הזבח בזמנו ולא באו עמו נסכיו — צריכים להביא את נסכיו, אף לאחר כמה ימים.","ומן הצד האחר, \u0003יש\u0004 הלכות הנוהגות \u0003בקרבנות הציבור מה שאין\u0004 כמותן \u0003בקרבנות יחיד.\u0004 ואלו הן: \u0003שקרבנות הציבור דוחין את\u0004 \u0003השבת,\u0004 שקרבים אף בשבת, \u0003ו\u0004כן דוחים \u0003את הטומאה,\u0004 שקרבים אף כשהכהנים טמאים בטומאת מת. \u0003ו\u0004אילו \u0003קרבנות\u0004 ה\u0003יחיד אינן דוחות לא את השבת ולא את הטומאה.\u0004","\u0003אמר\u0004 על כך \u0003ר' מאיר: והלא חביתי\u0004 (מנחה הנעשית במחבת) של \u0003כהן גדול\u0004 שאותה הוא מביא בכל יום, \u0003ופר של\u0004 כהן גדול שמביא ב\u0003יום הכפורים, קרבנות היחיד הן\u0004 — \u0003ו\u0004בכל זאת, הריהם \u0003דוחין את השבת ואת הטומאה! אלא\u0004 כך יש לומר את הכלל: כל קרבן (בין של ציבור, בין של יחיד) \u0003שזמנו קבוע\u0004 — דוחה את השבת ואת הטומאה. אבל קרבן שאין זמנו קבוע, בין של יחיד בין של ציבור — אינו דוחה את השבת ואת הטומאה.","שנינו במשנה כי \u0003קרבן יחיד עושה תמורה\u0004 ואין קרבן הציבור עושה תמורה. ושואלים: \u0003ו\u0004כי \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא\u0004 זה, שכל קרבן יחיד עושה תמורה? \u0003והרי\u0004 קרבנות החטאת והעולה הבאים מן ה\u0003עופות\u0004 (תורים ובני יונה) ש\u0003קרבן יחיד\u0004 הם — \u0003ואין עושה תמורה!\u0004 ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 כלל זה — הרי \u0003בבהמה\u0004 דווקא \u0003קתני\u0004 \u0005[שנינו].\u0006","ושואלים על כך: \u0003והרי ולד\u0004 הקדשים שהריהו קדוש ועולה למזבח כאמו. ש\u0003קרבן יחיד\u0004 הבא מן הבהמה \u0003הוא, ו\u0004בכל זאת דינו ש\u0003אין עושה תמורה!\u0004 ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר\u0004 כי \u0003הולד עושה תמורה.\u0004","ושואלים עוד: \u0003והרי תמורה עצמה,\u0004 ש\u0003קרבן יחיד היא\u0004 — \u0003ו\u0004הלכה היא ש\u0003אין תמורה עושה תמורה!\u0004 ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו]\u0006 במשנתנו כלל זה, שכל קרבנות היחיד עושים תמורה — הרי זה דווקא \u0003בעיקר זיבחא קתני\u0004 \u0005[בעיקר\u0006 ה\u0005זבח\u0006 הוא ש\u0005שנינו],\u0006 בקרבן המקורי, ולא בתמורה הבאה מכוחו.","ומציעים: \u0003השתא דאתית להכי\u0004 \u0005[עתה שבאת לכך],\u0006 להגדרה זו שבעיקר הזבח הוא ששנינו, אין צורך להעמיד את משנתנו דווקא כשיטת ר' יהודה, אלא \u0003אפילו\u0004 אם \u0003תימא רבנן\u0004 \u0005[תאמר\u0006 שהיא כשיטת \u0005חכמים]\u0006 הסוברים שאין הולד עושה תמורה, ואולם במשנה \u0003בעיקר זיבחא קתני\u0004 \u0005[בעיקר הזבח\u0006 בלבד \u0005שנינו],\u0006 ולא בולד הבא מכוחו.","עוד שנינו במשנתנו, ש\u0003קרבנות היחיד נוהגות בין בזכרים בין בנקבות,\u0004 ואילו קרבנות הציבור אינם נוהגים אלא בזכרים בלבד. ושואלים על כך: \u0003ו\u0004כי \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא\u0004 זה? \u0003והרי\u0004 קרבן \u0003עולה,\u0004 כאשר הוא \u0003קרבן יחיד\u0004 — \u0003ו\u0004ממין ה\u0003זכר\u0004 הוא \u0003אתיא\u0004 \u0005[בא],\u0006 וממין ה\u0003נקבה\u0004 הוא \u0003לא אתיא\u0004 \u0005[בא]!\u0006","ומשיבים: אף שקרבן עולה הבא מן הבהמה אינו אלא מן הזכרים, אבל \u0003האיכא\u0004 \u0005[הרי יש]\u0006 קרבן \u0003עולת העוף\u0004 שהוא בא בין מן הזכרים בין מן הנקבות, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדינו של קרבן העולה: מה שנאמר בתורה בקרבנות העולה, שיהיו בכלל \u0003תמות\u0004 (שלא יהיה בהם מום) \u0003וזכרות\u0004 (שיהיו זכרים) — לא נאמר אלא \u0003ב\u0004עולה הבאה מן ה\u0003בהמה, ואין\u0004 דין \u0003תמות וזכרות\u0004 נוהג \u0003בעופות,\u0004 ומשנתנו אם כן עוסקת בעולה זו.","ושואלים עוד: \u0003והרי\u0004 קרבן \u0003חטאת,\u0004 ש\u0003קרבן יחיד היא, ו\u0004ממין ה\u0003נקבה\u0004 היא \u0003אתיא\u0004 \u0005[באה],\u0006 וממין ה\u0003זכר\u0004 היא \u0003לא אתיא\u0004 \u0005[באה]?\u0006 ומשיבים: אמנם חטאת יחיד באה מן הנקיבה, ואולם \u0003האיכא\u0004 \u0005[הרי יש],\u0006 גם קרבן \u0003שעיר נשיא,\u0004 שקרבן חטאת יחיד הוא, ודינו \u0003דמייתי\u0004 \u0005[ש\u0006הוא \u0005בא]\u0006 ממין ה\u0003זכר.\u0004","ושואלים שוב: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 קרבן \u0003אשם יחיד\u0004 — שממין ה\u0003זכר\u0004 הוא \u0003אתי\u0004 \u0005[בא],\u0006 וממין ה\u0003נקבה לא אתי\u0004 \u0005[בא]?\u0006 ומשיבים: \u0003כי קאמרי רבנן\u0004 \u0005[כאשר אמרו חכמים]\u0006 במשנתנו את הכלל שקרבנות היחיד באים מן הזכרים ומן הנקיבות — הכוונה דווקא ל\u0003קרבן דשוי\u0004 \u0005[השווה]\u0006 \u0003בין ביחיד בין בציבור,\u0004 ואילו קרבן \u0003אשם\u0004 — רק \u0003ביחיד\u0004 הוא \u0003איתיה\u0004 \u0005[ישנו],\u0006 ואולם \u0003בצבור\u0004 הוא \u0003ליתיה\u0004 \u0005[אינו]\u0006 כלל, שהרי אין ציבור מביא קרבן אשם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לשאלה זו: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 במשנתנו \u0003\"כל קרבנות\",\u0004 והלא \u0003\"יש בקרבנות\"\u0004 \u0003קתני\u0004 \u0005[שנינו],\u0006 שיש מכלל קרבנות היחיד שנוהג בין בזכרים בין בנקבות, \u0003ומאי ניהו\u0004 \u0005[ומה הם]?\u0006 — קרבן ה\u0003שלמים. ואי בעי\u0004 \u0005[ואם רוצה]\u0006 הבעלים — \u0003נקבה מייתי\u0004 \u0005[מביא],\u0006 \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 — \u0003זכר מייתי\u0004 \u0005[מביא].\u0006","שנינו במשנה ש\u0003קרבנות יחיד חייבין\u0004 הבעלים \u0003באחריותן,\u0004 שאם לא הוקרבו בזמנם צריך להקריבם אף לאחר מכן, ואילו קרבנות הציבור אין חייבים באחריותם. ומסבירים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הדין, שאם לא קרבו בזמנם הראוי, שוב אין מביאים אותם לאחר זמנם?","— \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על הנאמר בפרשת המוספים הבאים במועדים (שהם קרבנות ציבור): \"אלה מועדי ה' אשר תקראו אותם מקראי קודש להקריב אשה לה' עולה ומנחה זבח ונסכים דבר יום ביומו\" (ויקרא כג, לז), והכתוב \u0003\"דבר יום\"\u0004 \u0003מלמד שכל היום\u0004 כולו \u0003כשר ל\u0004הקרבת קרבנות ה\u0003מוספין,\u0004 ואילו הכתוב \u0003\"ביומו\"\u0004 \u0003מלמד שאם עבר היום\u0004 המיועד להקרבת המוספים \u0003ולא הביאן\u0004 — שוב \u0003אינו חייב באחריותן,\u0004 ואין הוא מקריבם לאחר זמן.","ודנים עוד: \u0003יכול לא יהא חייב\u0004 אף \u0003באחריות נסכיהם,\u0004 להביאם לאחר זמן, \u0003ואף על פי ש\u0004כבר \u0003קרב הזבח,\u0004 וכגון באופן שלא היו לו מנחות ונסכים בשעה שקרב הקרבן? — לכך \u0003תלמוד לומר\u0004 (מלמדנו) כתוב אחר האמור בפרשת פינחס בדין מוספי הקרבנות \u0003\"מנחתם ונסכיהם\u0004 לפרים לאילים ולכבשים במספרם כמשפט\" (במדבר כט, כד) שמשמעו, שמכל מקום מביא את המנחות והנסכים — שאם לא הקריבם ביום, הריהם קרבים אף \u0003בלילה.\u0004 ועוד חזר ונאמר בפרשה זו: \u0003\"מנחתם ונסכיהם\u0004 לפר לאיל ולכבשים במספרם כמשפט\" (במדבר כט לז) — ללמדנו, שאם לא הקריבם ביום הקרבת הקרבן, הריהם קרבים \u0003למחר\u0004 (לאחר יום זה).","\u0003ריש לקיש אמר\u0004 שיש ללמוד דין זה \u0003מהכא\u0004 \u0005[מכאן],\u0006 מן הכתוב בקרבנות המוספים הבאים במועדים: \"...עולה ומנחה זבח ונסכים דבר יום ביומו. \u0003מלבד שבתת ה'...\"\u0004(ויקרא כג, לז—לח). והרי מסמיכות הכתובים נראה שמדובר ביום טוב הסמוך לאותן שבתות שהוזכר קודם לכן, ומכאן אנו למדים כי מביאים את המנחות והנסכים ביום טוב, ואף את המנחות והנסכים של השבת שלא הוקרבו אתמול.","ומסבירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני הכתובים הללו (שבפרשת אמור ובפרשת פינחס) המלמדים שהמנחות והנסכים קרבים אף לאחר זמן, משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק את האמור בפרשת אמור \"דבר יום ביומו. \u0003מלבד שבתת ה'\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003ביום\u0004 של החג שחל למחרת השבת — \u0003אין\u0004 \u0005[כן]\u0006 נוהג דין זה, שמקריבים בו את המנחה והנסכים של אתמול, \u0003ו\u0004אולם \u0003בלילה\u0004 — \u0003לא\u0004 נוהג דין זה, וכדרך שאין מקריבים קרבנות בלילה, אלא ביום בלבד. לכן חזר ו\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשת פינחס \u0003\"ומנחתם ונסכיהם\"\u0004 ללמדנו שהריהם קרבים אף בלילה. \u0003ו\u0004מן הצד האחר, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה\u0006 חוזרת ו\u0005כותבת התורה]\u0006 רק את הכתוב \u0003\"מנחתם ונסכיהם\" ולא כתב\u0004 \u0005[ולא היתה כותבת]\u0006 גם את הכתוב \u0003\"מלבד שבתת ה'\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003בלילה\u0004 שלאחר יום הקרבת הקרבן (בלא מנחותיו ונסכיו) — \u0003אין\u0004 \u0005[כן]\u0006 מקריבים את המנחות והנסכים, אבל \u0003ביממא\u0004 \u0005[ביום]\u0006 שלאחריו — \u0003לא\u0004 מביאים אותם.","\u0003ומאי שנא\u0004 \u0005[ובמה שונה,\u0006 מיוחד\u0005]\u0006 הוא הלילה, שיביאו בו ולא ביום שלאחריו? — \u0003משום\u0004 שכלל הוא ש\u0003בקדשים\u0004 ה\u0003לילה הולך אחר היום\u0004 שלפניו, לכך בא הכתוב בפרשת אמור המלמדנו שאף ביום שלאחריו הריהם באים. משום כך \u0003צריכי\u0004 \u0005[צריכים]\u0006 היו להיאמר שני הכתובים הללו.","ושואלים: \u0003ונסכים מי קרבי\u0004 \u0005[האם קרבים]\u0006 \u0003בלילה? והתנן\u0004 \u0005[והרי שנינו]\u0006 בברייתא בדינם של הדברים העולים על המזבח בלילה: \u0003אין לי\u0004 שקרבים בלילה \u0003אלא דברים שדרכן ליקרב\u0004 (שרגילות היא שיהיו קרבים) \u0003בלילה, כגון אברים\u0004 של קרבן העולה \u0003ופדרים\u0004 (חלבים) של כל הקרבנות, \u0003שמקריבין\u0004 אותם על המזבח \u0003מ\u0004זמן \u0003בוא\u0004 (שקיעת) \u0003השמש, ו\u0004הריהם \u0003מתעכלין והולכין כל הלילה כולו.\u0004","ואולם \u0003דברים שדרכן ליקרב ביום, כגון הקומץ\u0004 מקרבן המנחה שבהקטרתו על המזבח הריהו מתיר את המנחה לכהנים, ו\u0003הלבונה\u0004 המוקטרת עם קומץ המנחה, \u0003ומנחת נסכים\u0004 (היין והסולת הבאים עם הקרבן) \u0003ש\u0004הריהו \u0003מעלן\u0004 על המזבח \u0003מ\u0004זמן \u0003בוא השמש.\u0004 ולפני שסיימו להביא את דברי הברייתא במלואה, תוהים חכמים על הנאמר: \u0003\"מבוא השמש\"\u0004 (משקיעת השמש) \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 כי \u0003דברים שדרכן ליקרב ביום נינהו\u0004 \u0005[הם]!\u0006 \u0003אלא\u0004 יש לתקן את הנוסח, ולגרוס בברייתא במקום \"מבוא השמש\" \u0003\"עם בא השמש\"\u0004 (ביום, בזמן הסמוך לשקיעת השמש). וממשיכים בדברי הברייתא: שאף דינם \u0003שמתעכלין והולכין כל הלילה מנין\u0004 לנו? \u0003תלמוד לומר\u0004 האמור בקרבן העולה: \u0003\"זאת תורת העלה\u0004 היא העולה על מוקדה כל הלילה עד הבוקר\" (ויקרא ו, ב), שבכך \u0003ריבה\u0004 הכתוב את כל העולים על המזבח, שהריהם הולכים ומתעכלים על גבי המזבח כל הלילה, ואף אלו בכלל.","ומעתה נדון בדבר: \u0003קתני מיהא\u0004 \u0005[שנינו על כל פנים]\u0006 בדברי הברייתא כי זמן מנחת ה\u0003נסכים\u0004 הוא \u0003ביום\u0004 ולא בלילה, וכיצד נלמד איפוא מהכתוב \"מנחתם ונסכיהם\" כי זמן מנחת נסכים הוא אף בלילה? \u0003אמר רמי בר חמא\u0004 בתשובה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003כאן\u0004 (הכתוב \"מנחתם ונסכיהם\" המלמדנו כי זמנם הוא אף בלילה) — הריהו לענין \u0003ליקדש\u0004 \u0005[שיתקדשו]\u0006 בלבד: שאם ניתנה מנחת הנסכים בכלי שרת, בלילה — הריהי קדושה בכך, ואינה יוצאת לחולין. ואילו \u0003כאן\u0004 (הכתוב המלמדנו כי זמנם הוא ביום) — הריהו לענין \u0003ליקרב\u0004 \u0005[שיוקרבו]\u0006 ביום דווקא, שאף אם התקדשו בלילה, אין הם קרבים אלא ביום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרמי בר חמא בשאלה: \u0003אי מיקדש קדשי\u0004 \u0005[אם להתקדש\u0006 הם \u0005התקדשו]\u0006 בלילה — אף \u0003קרובי מיקרבי\u0004 \u0005[ליקרב\u0006 הם \u0005מוקרבים]\u0006 בלילה, שאין להפריד בענין זה בין ההקרבה וההתקדשות, שכן \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שכך היא המידה: \u0003זה הכלל, כל\u0004 קרבן \u0003הקרב ביום\u0004 — \u0003אין קדוש אלא ביום. וכל הקרב בלילה\u0004 — \u0003קדוש בלילה.\u0004 וכל הקרב \u0003בין ביום בין בלילה\u0004 — \u0003קדוש בין ביום בין בלילה! אלא אמר רב יוסף:\u0004 דין מנחת נסכים שהיא קרבה בלילה, ובאשר לברייתא בה היא נזכרת בין הדברים הקרבים ביום, אכן \u0003סמי\u0004 \u0005[הסר,\u0006 הוצא\u0005]\u0006 את הלשון \u0003\"מנחת נסכים\" מהא מתניתא\u0004 \u0005[מברייתא זו].\u0006","בעקבות דבריו אלה של רב יוסף, כי יש להסיר מהברייתא את הלשון \"מנחת נסכים\", מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב דימי\u0004 מבבל לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא,\u0006 פגש, \u0005את]\u0006 \u0003רב ירמיה דיתיב וקאמר משמיה\u0004 \u0005[שיושב ואומר בשמו]\u0006 של \u0003ר' יהושע בן לוי: מנין לנסכים הבאים עם הזבח שאין קריבין אלא ביום?\u0004 — \u0003תלמוד לומר\u0004 האמור בפרשת קרבנות המועדים שבפרשת פינחס \"אלה תעשו לה' במועדיכם... \u0003ולנסכיכם ולשלמיכם\"\u0004 (במדבר כט, לט), ומהשוואה זו שבין הנסכים לשלמים למדים אנו: \u0003מה שלמים\u0004 — קרבים דווקא \u0003ביום\u0004 ולא בלילה, \u0003אף נסכים\u0004 — קרבים \u0003ביום\u0004 ולא בלילה.","\u0003אמר\u0004 רב דימי: \u0003אי אשכחיה דכתיב איגרתא, שלחי ליה\u0004 \u0005[אם אמצא\u0006 מי \u0005שיכתוב איגרת, אשלח לו]\u0006 \u0003לרב יוסף\u0004 בבבל איגרת בה אכתוב לו את הדברים הללו ששמעתי מרב ירמיה."],["\u0003ו\u0004אציין כי לאור אותם דברים \u0003לא תיסמי\u0004 \u0005[אל תסיר]\u0006 את הלשון \u0003\"מנחת נסכים\" ממתניתא\u0004 \u0005[מהברייתא].\u0006 \u0003ו\u0004באשר לסתירה בין הברייתות אם קרבים נסכים בלילה, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש לחלק ולומר כי \u0003כאן\u0004 בברייתא האומרת שמנחת נסכים הריהי מכלל הדברים שדרכם ליקרב ביום — מדובר \u0003בנסכים הבאין עם הזבח,\u0004 וכדין הזבחים אם כן אף דין הנסכים, שאף הם אינם קרבים אלא ביום. ואילו \u0003כאן\u0004 בברייתא זו האומרת שהנסכים קרבים אף בלילה — מדובר \u0003בנסכים הבאין בפני עצמן,\u0004 שאין דינם כדין הזבחים, ולכן הם קרבים אף בלילה.","ותוהים על דברי רב דימי: \u0003ואי הוה ליה איגרתא\u0004 \u0005[ואם היה לו\u0006 מי שיכתוב \u0005איגרת],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אפשר\u0004 היה \u0003למישלחא\u0004 \u0005[לשולחה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של ר' חייא בר אבא, אמר ר' יוחנן: \u0003כותבי הלכות\u0004 הריהם \u0003כ\u0004מי ש\u0003שורף\u0004 את \u0003התורה. ו\u0004האדם \u0003הלמד מהן,\u0004 מכתבי הלכה — \u0003אינו נוטל\u0004 על כך \u0003שכר\u0004 לימוד תורה. הרי איפוא, שאין לכתוב דברי הלכה!","ועוד מוסיפים מדברי חכמים בענין איסור כתיבת תורה שבעל פה: \u0003דרש ר' יהודה בר נחמני מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 של \u0003ריש לקיש\u0004 בפסוק \"ויאמר ה' אל משה כתוב לך את הדברים האלה כי על פי הדברים האלה כרתי אתך ברית ואת ישראל\" (שמות לד, כז): והרי בפסוק זה \u0003כתוב אחד אומר \"כתב לך את הדברים האלה\"\u0004 — שנדרש הוא לכותבם, \u0003ו\u0004אילו \u0003כתוב אחד אומר \"כי על פי הדברים האלה\"\u0004 — להורות שיהיו הדברים בעל פה (\"על פי\"), והרי זו כעין סתירה בין הכתובים! אלא כוונת הפסוק \u0003לומר לך: דברים שעל פה\u0004 — \u0003אי\u0004 (אין) \u0003אתה רשאי לאומרן בכתב\u0004 (לכותבם), \u0003ו\u0004דברים \u0003שבכתב\u0004 — \u0003אי\u0004 (אין) \u0003אתה רשאי לאומרן על פה. ו\u0004עוד בענין זה","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על האמור \u0003\"כתב לך את הדברים האלה\"\u0004 — דווקא דברים \u0003אלה אתה כותב, אבל אין אתה כותב הלכות.\u0004 הרי מכל אלה עולה שאין לכתוב דברי הלכה, וכיצד רב דימי ביקש לכתוב דברי הלכה ולשולחם לרב יוסף?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לשאלה זו: \u0003דלמא מילתא חדתא שאני\u0004 \u0005[שמא דבר חידוש שונה,\u0006 מיוחד הוא\u0005],\u0006 שהותר לכותבו, על מנת שלא יישכח. וראיה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0005ר' יוחנן וריש לקיש\u0006 \u0003מעייני בסיפרא דאגדתא בשבתא\u0004 \u0005[היו מעיינים בספר אגדה בשבת],\u0006 אף שהוא מכלל תורה שבעל פה, שאין לכותבה, \u0003ו\u0004בטעם הנהגתם זו \u0003דרשי הכי\u0004 \u0005[דרשו כך]\u0006 את הכתוב \u0003\"עת לעשות לה' הפרו תורתך\"\u0004 (תהלים קיט, קכו), שכאשר עושה אדם דבר לקיום רצון ה' ולשם קדושתו ראוי אף להפר את ציווי התורה. ועוד הוסיפו ו\u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003מוטב\u0004 ש\u0003תיעקר\u0004 מצות ה\u0003תורה,\u0004 שלא לכותבה, \u0003ואל תשתכח תורה מישראל.\u0004","ובעקבות דברי רב דימי המבחין בין נסכים הבאים עם הזבח (שאינם קרבים בלילה) לבין נסכים הבאים בפני עצמם (הקרבים בלילה) \u0003אמר רב פפא: השתא דאמרת\u0004 \u0005[עתה שאומר אתה]\u0006 כי \u0003נסכים הבאין בפני עצמן\u0004 הריהם \u0003קריבין\u0004 על המזבח \u0003אפילו בלילה,\u0004 מעתה אם \u0003נזדמנו נסכים\u0004 כאלו \u0003בלילה\u0004 — הרי אף \u0003מקדישין\u0004 אותם (בנתינתם בכלי שרת) \u0003בלילה ו\u0004לאחר מכן \u0003מקריבין\u0004 אותם בלילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמעיה לרב פפא:\u0004 הרי \u0003תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת]\u0006 \u0003לך,\u0004 שכך שנינו: \u0003זה הכלל, כל הקרב ביום\u0004 — \u0003אינו קדוש\u0004 (מתקדש) \u0003אלא ביום, וכל הקרב בלילה\u0004 — \u0003קדוש בין ביום בין בלילה.\u0004 ואף הנסכים הבאים בפני עצמם, כיון שקרבים הם בלילה — אף מתקדשים הם בלילה לפני ההקרבה.","\u0003אמר רב אדא בר אהבה\u0004 עוד בדין הנסכים הבאים בפני עצמם: \u0003ו\u0004אף \u0003עלות השחר פוסלת בהן,\u0004 שמשעלה עמוד השחר הריהם נפסלים \u0003כ\u0004דרך שנפסלים ה\u0003אברין\u0004 של הקרבנות שנזרק דמם ביום שהם הולכים ומתעכלים על גבי המזבח במשך הלילה, ומשעלה השחר ולא עלו למזבח הריהם פסולים ושוב אינם עולים.","בעמוד הקודם הובא כי כאשר עלה רב דימי לארץ ישראל מבבל מצא את רב ירמיה הדורש בשם ר' יהושע בן לוי היקש הנסכים לשלמים מתוך הכתוב \"ולנסכיכם ולשלמיכם\" (במדבר כט, לט), לומר שאין הנסכים קרבים אלא ביום, כקרבן השלמים עצמו. ועתה מביאים דרשה נוספת על כתוב זה: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשמו של \u0003ר' יוחנן\u0004 שאמר \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יהוצדק:\u0004 מה שנאמר \"אלה תעשו לה' במועדיכם לבד מנדריכם ונדבותיכם לעולותיכם ולמנחותיכם ולנסכיכם ולשלמיכם\" נדרש כך: \u0003\"אלה תעשו לה' במועדיכם\"\u0004 — \u0003אלו\u0004 קרבנות \u0003חובות הבאות\u0004 כ\u0003חובה ב\u0004של ה\u0003רגל,\u0004 וכגון עולת ראיה, קרבן חגיגה וקרבנות המוספים.","\u0003\"לבד מנדריכם ונדבתיכם\"\u0004 — כתוב זה \u0003לימד על\u0004 קרבנות \u0003נדרים ונדבות שקרבין בחולו של מועד.\u0004","ומעתה מה שנאמר עוד בכתוב \u0003\"ולעלתיכם\"\u0004 — יש לדון: \u0003במה הכתוב מדבר,\u0004 באיזה קרבן עולה מדובר כאן? שכן \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003בעולת נדר\u0004 (שאמר \"הרי עלי עולה\") — \u0003הרי\u0004 דבר זה \u0003כבר אמור\u0004 בכתוב \u0003\"נדריכם\", ואי\u0004 \u0005[ואם]\u0006 המדובר \u0003בעולת נדבה\u0004 (שאמר על בהמתו \"הרי זו עולה\") — \u0003הרי\u0004 אף דבר זה \u0003כבר אמור\u0004 בכתוב \u0003\"ונדבתיכם\"!\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 נסיק מכאן כי הכתוב \"לבד מנדריכם ונדבותיכם\" \u0003אינו מדבר\u0004 לא בעולת נדר ולא בעולת נדבה, \u0003אלא בעולת\u0004 ה\u0003יולדת ועולת\u0004 ה\u0003מצורע,\u0004 שהן עולות הבאות כחובה, ולימדנו כתוב זה כי אף אלה קרבות בחול המועד.","ומה שנאמר בהמשך הכתוב \u0003\"ולמנחתיכם\"\u0004 — אף בזה יש לדון: \u0003במה,\u0004 באיזו מנחה \u0003הכתוב מדבר?\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003במנחת נדר\u0004 — \u0003הרי\u0004 דבר זה \u0003כבר אמור\u0004 בכתוב (\"נדריכם\"). ו\u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003במנחת נדבה\u0004 — אף דבר זה \u0003הרי\u0004 \u0003כבר אמור\u0004 (\"ונדבותיכם\")! \u0003הא\u0004 \u0005[הרי]\u0006 יש לומר כי הכתוב \"ולמנחותיכם\" \u0003אינו מדבר אלא במנחת\u0004 ה\u0003סוטה\u0004 המכונה \u0003מנחת קנאות,\u0004 שאף היא קרבה בחול המועד.","ומה שנאמר עוד בכתוב \u0003\"ולנסכיכם ולשלמיכם\"\u0004 — והרי \u0003מקיש\u0004 הכתוב את דין ה\u0003נסכים\u0004 \u0003ל\u0004דין ה\u0003שלמים.\u0004 לומר לך: \u0003מה שלמים\u0004 — קרבים דווקא \u0003ביום\u0004 ולא בלילה, \u0003אף\u0004 ה\u0003נסכים\u0004 — קרבים דווקא \u0003ביום\u0004 ולא בלילה. ומה שנאמר \u0003\"ולשלמיכם\"\u0004 ולא כתב \"ולשלמים\" — הרי זה בא \u0003לרבות\u0004 אף \u0003שלמי נזיר\u0004 (שמביא הנזיר בגמר נזירותו) שקרבים בחולו של מועד.","על דרשה אחרונה זו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב דימי שהביא את השמועה הזו שבשמו של ר' שמעון בן יהוצדק: \u0003ולימא מר\u0004 \u0005[ויאמר אדוני]\u0006 שהכתוב \"ולשלמיכם\" בא לרבות את \u0003שלמי פסח,\u0004 הם קרבן חגיגת ארבעה עשר בניסן, שכשהיו המנויים על קרבן הפסח מרובים ולא הספיק קרבן הפסח עצמו להשביע את כולם, הביאו עמו שלמים. ומלמד שאם לא קרבו עם הפסח בארבעה עשר יש להקריבם אף בחול המועד. ומסתבר יותר לומר ששלמים אלו ריבה הכתוב, \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 כדבריך, שריבה הכתוב \u0003שלמי נזיר\u0004 — אין צורך בכתוב מיוחד כדי לרבותם, שהרי קרבן שלמים זה כ\u0003נידר ונידב הוא\u0004 נחשב (ואלו, כבר התרבו, כנאמר למעלה).","\u0003דהתניא\u0004 \u0005[שהרי שנויה\u0006 ברייתא\u0005]\u0006 הדנה בדין \"במת יחיד\", \u0003זה הכלל: כל\u0004 קרבן \u0003שהוא נידב ונידר\u0004 (כעולה וכשלמים) — הריהו \u0003קרב בבמת יחיד, ו\u0004כל קרבן \u0003שאינו נידב ונידר\u0004 אלא בא כחובה — \u0003אינו קרב בבמת יחיד.\u0004","\u0003ותנן\u0004 \u0005[ושנינו]\u0006 בברייתא נוספת: \u0003המנחות והנזירות\u0004 (הקרבנות שמביא הנזיר) הריהם \u0003קריבין בבמת יחיד,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ונסיק מכאן כי שלמי נזיר הם בכלל הנידר והנידב, ולכן אין צורך לריבוי מיוחד בכתוב שאף הם קרבים בחול המועד! השיב רב דימי לאביי: \u0003סמי\u0004 \u0005[הסר]\u0006 \u0003מכאן,\u0004 מברייתא זו, את הלשון \u0003\"נזירות\"\u0004 השנויה בה, שכן אין קרבנות הנזיר בכלל הנידר והנידב, ואינם קרבים בבמת יחיד.","ושואלים על כך: \u0003מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 שקרבן ה\u0003נזיר לאו\u0004 \u0005[לא]\u0006 כ\u0003נידר ונידב הוא\u0004 נחשב, ומשום כך אינו קרב בבמת יחיד?! \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \"ויהי \u0003מקץ ארבעים שנה ויאמר אבשלום אל המלך אלכה נא ואשלם את נדרי אשר נדרתי לה' בחברון. כי נדר נדר עבדך\u0004 בשבתי בגשור בארם לאמר אם ישוב ישיבני ה' ירושלם ועבדתי את ה'. ויאמר לו המלך לך בשלום ויקם וילך חברונה\" (שמואל ב טו, ז—ט). \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 ביקש אבשלום ללכת לחברון כדי להקריב \u0003קרבן\u0004 נזירות? שכן אבשלום נזיר עולם היה ובתום כל שלושים יום היה מגלח שערו ומביא קרבן, ומסתבר כי הקרבן שהלך להקריב בחברון קרבן הנזירות היה. ומכאן יש ללמוד כי קרבן נזירות נידר ונידב!","ודוחים: כוונת הכתוב היא \u0003לא\u0004 שהלך אבשלום לשם כדי להקריב את קרבנות נזירותו, אלא לומר כי את \u0003עיקר נדרו\u0004 שנדר בנזירות \u0003אמר\u0004 אבשלום בהיותו בחברון. ותוהים על הסבר זה: וכי \u0003עיקר נדרו בחברון הוה\u0004 \u0005[היה]?\u0006 \u0003והלא בגשור הוה\u0004 \u0005[היה],\u0006 וכדרך שנאמר במפורש בדברי אבשלום \"כי נדר נדר עבדך בשבתי בגשור\"!","\u0003אמר רב אחא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר רב חנן:\u0004 איזכור העיר חברון בפסוק בא לומר כי \u0003לא הלך אבשלום אלא להביא כבשים מחברון,\u0004 אבל לא על מנת להקריבם שם. ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דאי תימא לאקרובי\u0004 \u0005[ש\u0006כן \u0005אם תאמר\u0006 כי \u0005להקריב]\u0006 \u0003הוא דאזיל\u0004 \u0005[שהלך]\u0006 — על כך יש לשאול: האם אבשלום \u0003שביק\u0004 \u0005[היה עוזב]\u0006 את \u0003ירושלים\u0004 בה הוא גר, \u0003ואזיל\u0004 \u0005[והולך]\u0006 \u0003ומקריב בחברון?\u0004","ודוחים הסבר זה של רבה בר רב חנן: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 מוכיח אתה מתוך כך — כי הלך אבשלום \u0003להביא כבשים מחברון,\u0004 ואולם \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \"אלכה נא ואשלם את נדרי \u0003אשר נדרתי לה' בחברון\",\u0004 אינו ברור, שהרי \u0003\"מחברון\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר!","\u0003אלא לעולם\u0004 יש לומר כי \u0003לאקרובי\u0004 \u0005[להקריב]\u0006 הלך אבשלום לחברון, שכן קרבנות נזיר קרבים בבמת יחיד, \u0003ודקא קשיא\u0004 \u0005[ו\u0006זה \u0005שהוקשה]\u0006 \u0003לך: אמאי שבק\u0004 \u0005[מדוע עזב]\u0006 את \u0003ירושלים ומקריב\u0004 \u0005[והקריב]\u0006 \u0003בחברון,\u0004 \u0003תיקשי\u0004 \u0005[תוקשה]\u0006 \u0003לך\u0004 קושיה חמורה מזו: מדוע עזב אבשלום את \u0003גבעון,\u0004 שבאותה עת \u0003מקום קדוש הוא,\u0004 שהרי שכן בה המשכן בזמן ההוא, והיתה זו במה גדולה, במת ציבור, והלך לחברון! \u0003אלא\u0004 מכאן יש לומר כי \u0003כיון שהותרו ה\u0004קרבנות ב\u0003במות\u0004 יחיד באותה עת אף שהיתה אז במה גדולה, \u0003כל היכא דבעי\u0004 \u0005[מקום שרצה]\u0006 אדם להקריב — \u0003מקריב\u0004 \u0005[הקריב].\u0006","בתוך דברי אבשלום צויין כי מלאו באותה עת \u0003ארבעים שנה,\u0004 ומבררים: ארבעים שנה \u0003למאן\u0004 \u0005[למי,\u0006 לאיזה מנין\u0005]?\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין זה, \u0003ר' נהוראי אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יהושע: מקץ ארבעים שנה ששאלו להם\u0004 בני ישראל משמואל להמליך עליהם \u0003מלך,\u0004 וחשב אבשלום שהגיע זמנו למלוך על ישראל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אותה שנה ששאלו להם מלך, אותה שנה\u0004 השנה ה\u0003עשירית\u0004 להנהגתו \u0003של שמואל היתה.\u0004"],["שכך הוא סדר שנות ההנהגה של אלה שקדמו למרד אבשלום: \u0003עשר שנים\u0004 — ש\u0003מלך שמואל בעצמו\u0004 (לבדו), \u0003שנה אחת\u0004 — \u0003שמלך שאול ושמואל\u0004 ביחד, \u0003ו\u0004עוד \u0003שתים\u0004 — שמלך שאול בעצמו (לבדו), \u0003ושלשים ושבע\u0004 שנים — \u0003שמלך דוד.\u0004 וסיכום שנות מלכותם של כל אלה, הריהו ארבעים שנה, וחשב אבשלום, שעתה הגיע זמנו שלו למלוך על ישראל.","המשנה ממשיכה לדון בחילוקים שבין קרבנות יחיד לקרבנות ציבור. הלכה למשה מסיני היא שיש \"חטאות המתות\" והן חמש חטאות שאינן ראויות להיות מוקרבות על המזבח, ואין להן תקנה עד שימותו מעצמן. ואלו הן: ולד חטאת; תמורת החטאת; החטאת שמתו בעליה; החטאת שהתכפרו בעליה בחטאת אחרת, וכגון שאבד קרבן החטאת, ונתכפרו הבעלים בקרבן אחר, ולאחר מכן נמצא הקרבן הראשון; והחטאת שעברה עליה שנתה. והמשנה דנה בחטאת שהתכפרו בעליה: \u0003חטאת היחיד שכפרו\u0004 (שהתכפרו) \u0003בעליה\u0004 באחרת לאחר שאבדה ונמצאה — \u0003מתה.\u0004 \u0003ואם\u0004 היתה זו חטאת \u0003של צבור\u0004 — \u0003אינה מתה.\u0004 שלא נאמר דין זה אלא בחטאת היחיד, ולא בחטאת הציבור.","ואילו \u0003ר' יהודה אומר:\u0004 אף חטאת הציבור שהתכפרו הציבור בחטאת אחרת — \u0003תמות. ר' שמעון אומר: מה מצינו\u0004 (כשם שמצאנו) בשלוש חטאות שמתוך אלה החמש שנקבעה בהן הלכה למשה מסיני כי הן מומתות, \u0003בולד חטאת, ובתמורת חטאת, ובחטאת שמתו בעליה\u0004 — שה\u0003דברים אמורים ב\u0004חטאת \u0003יחיד ולא ב\u0004חטאת \u0003צבור\u0004 (שהרי אין אפשרות שיהיה ולד חטאת בחטאת ציבור, שכן היא באה רק מן הזכרים; ואין אפשרות שתהיה תמורת חטאת בחטאת ציבור, שכן אין דין תמורה כלל בקרבן ציבור; ואין אפשרות שתהיה חטאת ציבור שמתו בעליה, שהרי אין הציבור מת), \u0003אף\u0004 דין שתי החטאות האחרות: חטאת \u0003שכפרו בעליה ו\u0004חטאת ש\u0003עיברה שנתה\u0004 — דווקא \u0003ב\u0004חטאת \u0003יחיד\u0004 ה\u0003דברים אמורים, ולא ב\u0004חטאת \u0003ציבור.\u0004","בענין החטאת שהתכפרו בעליה באחרת, מביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מהו\u0004 (מה מלמדנו) כתוב זה ה\u0003אומר\u0004 בדין \u0003חטאת\u0004 היחיד \u0003\"יביא\"\u0004 (\"ואם כבש יביא קרבנו לחטאת נקבה תמימה יביאנה\". ויקרא ד, לב)? והלא די היה לומר \"ואם כבש קרבנו לחטאת\" וכו'! אלא \u0003מנין למקדיש חטאתו ואבדה, והפריש אחרת תחתיה, ו\u0004לאחר מכן \u0003נמצאת הראשונה קיימת, ו\u0004מעתה \u0003הרי שתיהן עומדות\u0004 לפניו להקרבה, \u0003מנין שאיזו מהן שירצה יביא?\u0004 — \u0003תלמוד לומר:\u0004 \"יביא קרבנו ל\u0003חטאת\",\u0004 שתלוי בו איזה מהן יביא לקרבן. ומעתה יש לשאול: \u0003יכול יביא\u0004 את \u0003שתיהן\u0004 לקרבנו? — \u0003תלמוד לומר\u0004 בהמשך הפסוק: \"נקבה תמימה \u0003יביאנה\"\u0004 — שמביא \u0003אחת ולא שתים. ו\u0004אם כן","\u0003אותה שניה מה תהא עליה? אמר רב המנונא, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: תרעה\u0004 עד שיפול בה מום, ולאחר מכן תיפדה, ויביא בדמיה קרבן נדבה. ואילו \u0003ר' שמעון אומר: תמות,\u0004 כדין חטאת היחיד שכיפרו בעליה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יהודה\u0004 שבמקרה זה \u0003תרעה\u0004 החטאת השניה עד שיפול בה מום, ולא תמות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה\u0004 ש\u0003תמות שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 אומר במשנתנו! ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את שיטות החכמים בברייתא זו, ובאופן זה, \u0003ר' יהודה אומר: תמות, ר' שמעון אמר: תרעה. ו\u0004מקשים על תירוץ זה: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' שמעון תרעה? והא\u0004 \u0005[והרי]\u0006 במשנתנו \u0003אמר ר' שמעון\u0004 כי כל אלו \u0003חמש חטאות\u0004 היחיד, ובכללן זו שהתכפרו בעליה \u0003מתות!\u0004","\u0003אלא (אמר ליה\u0004 \u0005[לו]\u0006\u0003) לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את שיטות החכמים שבברייתא זו, \u0003ו\u0004באשר לסתירה בדברי ר' יהודה יש להשיב כי \u0003לא קשה,\u0004 שכן יש להבחין בין המקרים: \u0003כאן\u0004 בברייתא, שאמר בה ר' יהודה שתרעה — מדובר \u0003ב\u0004מקרה שהחטאת הראשונה היתה \u0003אבודה בשעת\u0004 ה\u0003הפרשה\u0004 של החטאת השניה, אבל לא בשעת הכפרה, שנמצאה קודם לכן, וכיון שבשעת הכפרה לא היתה אבודה — אינה מתה אלא רועה. ואילו \u0003כאן\u0004 במשנתנו, שאמר בה ר' יהודה שתמות — מדובר \u0003ב\u0004מקרה שהיתה החטאת הראשונה \u0003אבודה\u0004 אף \u0003בשעת\u0004 ה\u0003כפרה\u0004 בחטאת השניה, ורק לאחר מכן נמצאה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לסתירה זו שבדברי ר' יהודה: \u0003אידי ואידי\u0004 \u0005[זו וזו],\u0006 הן המשנה והן הברייתא מדברות כשהיתה החטאת הראשונה אבודה \u0003בשעת הפרשה\u0004 ונמצאה קודם הכפרה בשניה, \u0003ולא קשה\u0004 מדברי ר' יהודה על דברי ר' יהודה, שכן \u0003הא\u0004 \u0005[זו]\u0006 שאמר ר' יהודה במשנה שתמות — הריהי שיטת \u0003ר' יהודה אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003רבי\u0004 (ר' יהודה הנשיא) במשנה להלן (כב,ב) הסבור כי אף אם היתה אבודה רק בשעת הפרשה ולא בשעת הכפרה באחרת הריהי מתה. ואילו \u0003הא\u0004 \u0005[זו]\u0006 שאמר ר' יהודה בברייתא שתרעה — הריהי שיטת \u0003ר' יהודה אליבא דרבנן\u0004 \u0005[על פי\u0006 שיטת \u0005חכמים]\u0006 באותה משנה הסבורים שאינה מתה אלא אם היתה אבודה גם בשעת הכפרה באחרת. שנינו במשנתנו בשיטת ר' יהודה כי חטאת ציבור שהתכפרו הציבור באחרת הריהי מתה.","ומקשים: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם\u0006 מבין החכמים \u0005יש מי שאומר]\u0006 כי \u0003חטאת ציבור שכפרו בעלים\u0004 — \u0003מתה?\u0004"],["\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין חטאת הציבור שמתו בעליה: \u0003כיוצא בו אמר ר' יוסי\u0004 על האמור בשיבת ציון, בזמן בית שני: \u0003\"והבאים מהשבי בני הגולה הקריבו עלות\u0004 לאלהי ישראל \u0003פרים בני בקר שנים עשר\u0004 על כל ישראל, \u0003אילים תשעים ותשעה, כבשים שבעים ושבעה, שעירי חטאת שנים עשר, הכל עולה לה'\"\u0004(עזרא ח, לה).","ועל הנאמר בכתוב זה כי \"הכל עולה\", יש לשאול: והלא אף חטאות בכלל האמור בכתוב, \u0003וחטאת מי\u0004 \u0005[האם]\u0006 היא \u0003קרבה\u0004 כ\u0003עולה? אמר רבא:\u0004 אותה חטאת האמורה בכתוב אמנם אינה קרבה כעולה, ואולם הריהי \u0003כי\u0004 \u0005[כמו]\u0006 \u0003עולה,\u0004 וכיצד? — \u0003מה עולה\u0004 \u0003אינה נאכלת\u0004 — \u0003אף חטאת\u0004 זו \u0003אינה נאכלת. ש\u0004כן \u0003היה ר' יוסי אומר:\u0004 שתים עשרה חטאות אלה שהביאו שבי ציון — \u0003על עבודה זרה\u0004 שעבדו עם ישראל \u0003הביאום. ו\u0004בהסבר דברים אלו, \u0003אמר רב יהודה, אמר שמואל:\u0004 חטאות אלו הובאו \u0003על עבודה זרה שעשו\u0004 ישראל \u0003בימי צדקיהו\u0004 המלך.","\u0003קא סלקא דעתין\u0004 \u0005[עולה על דעתנו,\u0006 יש להניח\u0005],\u0006 כי \u0003למאן דאית ליה\u0004 \u0005[ל\u0006שיטת \u0005מי שיש לו,\u0006 שסבור\u0005]\u0006 כי \u0003חטאת צבור שנתכפרו בעליה\u0004 — \u0003מתה, אית ליה נמי\u0004 \u0005[יש לו,\u0006 סבור הוא, \u0005גם כן]\u0006 כי \u0003חטאת צבור שמתו בעליה\u0004 — \u0003מתה, והא הכא\u0004 \u0005[והרי כאן,\u0006 במסופר בשבי ציון בימי בית שני\u0005]\u0006 — \u0003דאיכא\u0004 \u0005[שיש],\u0006 שהיתה זו חטאת ש\u0003מתו בעליה\u0004 (שהרי באה לכפר על דורו של צדקיהו, בזמן הבית הראשון, שמתו מכבר), \u0003וקא\u0004 \u0005[ו\u0006בכל זאת \u0005היא]\u0006 \u0003קרבה!\u0004","\u0003אמר רב פפא\u0004 בתשובה: אין להביא ראיה מחטאת ציבור שמתו בעליה לענין חטאת ציבור שהתכפרו בעליה באחרת, שכן \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003חטאת צבור שכפרו בעליה\u0004 — \u0003מתה,\u0004 סבור הוא ש\u0003חטאת צבור שמתו בעליה\u0004 — \u0003אינה מתה.\u0004 וטעם הדבר: \u0003לפי שאין הצבור מתים.\u0004","ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרב פפא הא\u0004 \u0005[\u0006עיקרון \u0005זה],\u0006 שאין מיתה בציבור? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"תחת אבתיך יהיו בניך\"\u0004 (תהלים מה, יז), שאף שמתו האבות — בניהם עומדים תחתיהם, ונחשב כאילו לא מתו האבות. יש לדחות ראיה זו: שכן \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, \u0003אפילו יחיד\u0004 שמת והשאיר אחריו בנים \u0003נמי\u0004 \u0005[גם כן]\u0006 ייחשב לו הדבר כאילו לא מת!","\u0003אלא היינו טעמא\u0004 \u0005[זהו הטעם,\u0006 המקור\u0005]\u0006 לשיטת רב פפא \u0003שאין הציבור מתים\u0004 — שנלמד הדבר \u0003מ\u0004קרבנות \u0003שעירי רגלים וראשי חדשים,\u0004 שכן \u0003אמר רחמנא\u0004 \u0005[הכתוב]\u0006 בהם: \u0003אייתינהו\u0004 \u0005[הביאם]\u0006 \u0003מ\u0004הכספים של \u0003תרומת הלשכה\u0004 שתרמו הציבור משקליהם במהלך חודש אדר, \u0003ו\u0004יש לשאול: \u0003דלמא\u0004 \u0005[שמא]\u0006 בפרק הזמן שבין חודש אדר לרגלים \u0003מתו מרייהו דהני זוזי\u0004 \u0005[בעליהם של הזוזים הללו],\u0006 ונמצא שמקריבים חטאות ציבור שמתו בעליהן! \u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תשמע מכאן]\u0006 כלל זה ש\u0003אין הצבור מתים.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: אמנם אף חטאת ציבור שמתו בעליה מתה, ובאשר לשאלה כיצד הקריבו שבי ציון חטאות על עבודה זרה שעשו בני דורו של צדקיהו המלך, יש להשיב: \u0003כי אקרובינהו להני\u0004 \u0005[כאשר הקריבום את אותן]\u0006 \u0003חטאות\u0004 — \u0003אחיי אקרבינהו\u0004 \u0005[על\u0006 אלה שעדיין \u0005חיים הקריבו],\u0006 שבתקופת שיבת ציון נותרו עדיין מבני תקופת בית ראשון, וראיה לדבר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור ייסוד בית המקדש בזמן שיבת ציון: \u0003\"ורבים מהכהנים\u0004 ו\u0003הלוים וראשי האבות הזקנים אשר ראו את הבית הראשון ביסדו זה הבית\u0004 בעיניהם \u0003בכים בקול גדול ורבים בתרועה\u0004 בשמחה להרים קול\" (עזרא ג, יב).","ושואלים: \u0003ודילמא הנך מיעוטא\u0004 \u0005[ושמא\u0006 היו \u0005אלה\u0006 שנשארו \u0005מיעוט]\u0006 בלבד, והמיעוט נחשב כיחידים, והיה ראוי להקריב איפוא לכל אחד שעירה, כדין היחיד, ומתוך שהקריבו שעירים, שעיר לכל שבט, כדין מרובים, ודאי בשביל המרובים שמתו כבר הקריבו, ומכאן שאין חטאת ציבור מתה! ומשיבים: \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר\u0006 כן\u0005],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בפסוק שלאחריו \u0003\"ולא הכירו העם בתרועה ושמחה לקול בכי העם\"\u0004 (עזרא ג, יג), הרי שרבים היו הבוכים, בני תקופת בית ראשון, מהשמחים, בני תקופת שיבת ציון, שהרי קול הבכי הוא שגבר.","ושואלים עוד: \u0003והיכי מקרבי להו\u0004 \u0005[ואיך הקריבו אותן,\u0006 את החטאות הללו\u0005],\u0006 על עבודה זרה שעשו בני דורו של צדקיהו, \u0003והרי מזידין הוו\u0004 \u0005[היו],\u0006 ואין החטאת באה אלא על השוגג! \u0003אמר ר' יוחנן\u0004 בתשובה לשאלה זו: \u0003הוראת שעה היתה\u0004 שהביאו חטאת על המזיד.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, משום \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 יש לשאול: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 שהקריבו השבים מן הגולה שנים עשר \u0003פרים ו\u0004שנים עשר \u0003שעירים\u0004 — שכן זהו דינו של ציבור (שבט) שעבד עבודה זרה שמביא פר לעולה ושעיר לחטאת, כאמור בתורה (במדבר טו), והקריבו מכל אחד שנים עשר \u0003כנגד שנים עשר שבטים,\u0004 לכל שבט פר ושעיר, \u0003אלא\u0004 זה שהקריבו תשעים וששה אילים ושבעים וששה \u0003כבשים כנגד מי? אלא\u0004 על כרחך יש לומר כי כל הבאת הקרבנות אז \u0003הוראת שעה היתה.\u0004","אגב הדיון בענין חטאת שמתו בעליה, שהיא מן ההלכות שנשכחו בימי אבלו של משה רבינו (ראה להלן טז,א), יובאו דברים נוספים בענין זה. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה מסכת סוטה] כי \u0003מ\u0004זמן \u0003שמת יוסף בן יועזר איש צרידה ויוסף בן יוחנן איש ירושלים בטלו\u0004 אותם \u0003ה\u0004מכונים \u0003אשכולות,\u0004 ומסבירים: מהו \"אשכולות\"? — \u0003איש שהכל בו. ו\u0004עוד בעניינם של המכונים \"אשכולות\",","\u0003אמר רב יהודה,\u0004 \u0003אמר שמואל: כל אשכולות שעמדו להן לישראל מימות משה עד שמת יוסף בן יועזר\u0004 — \u0003היו למדין תורה כמשה רבינו, מכאן ואילך\u0004 — \u0003לא היו למדין תורה כמשה רבינו.\u0004","ושואלים על כך: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה, אמר שמואל: שלשת אלפים הלכות נשתכחו בימי אבלו של משה,\u0004 הרי איפוא שהחכמים שעמדו אחר משה רבינו לא למדו תורה כמותו! ומשיבים: אותן הלכות \u0003דאישתכח להו\u0004 \u0005[שנשכחו להם,\u0006 מהם\u0005]\u0006 — אכן \u0003אישתכח\u0004 \u0005[נשכחו]\u0006 מהם, \u0003ו\u0004אולם כל מה \u0003דגמירן להו\u0004 \u0005[שהיו למודים להם,\u0006 מסורים בידם\u0005]\u0006 ולא נשכחו — \u0003הוו גמירי\u0004 \u0005[היו למודים]\u0006 אותן \u0003כמשה רבינו.\u0004","וחוזרים ושואלים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בענין דרך הכרעת ההלכה, כי כאשר יש מחלוקת בדבר הלכה בין החכמים \u0003מ\u0004זמן \u0003שמת משה\u0004 רבינו, כך יש לנהוג: עומדים למנין, ו\u0003אם רבו\u0004 החכמים ה\u0003מטמאין\u0004 — \u0003טמאו, אם רבו\u0004 החכמים ה\u0003טהורין\u0004 (המטהרים) — \u0003טיהרו.\u0004 הרי איפוא שאין לימוד התורה לאחר משה רבינו, כבזמנו של משה רבינו. שכן בזמן משה רבינו לא היתה מחלוקת בהלכה, וההכרעה בכל שאלה היתה ברורה!","ומשיבים: מדובר באותן שלשת אלפים הלכות שהשתכחו בימי אבלו של משה ובהן \u0003ליבא דאימעיט\u0004 \u0005[הלב\u0006 הוא \u0005שהתמעט],\u0006 ולא יכלו החכמים לקבוע בהן הלכה ברורה, ולכך היו צריכים להכרעת הרוב, ואולם בכל ההלכות האחרות — \u0003מיגמר הוו גמירי להו\u0004 \u0005[למודים היו אותן]\u0006 \u0003כמשה רבינו.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה\u0006 החכם\u0005]\u0006 עוד בעניינם של האשכולות, שכך אמרו: \u0003כל אשכולות שעמדו לישראל מימות משה עד שמת יוסף בן יועזר איש צרידה\u0004 — \u0003לא היה בהם שום דופי\u0004 (פגם), ואילו האשכולות שעמדו \u0003מכאן ואילך\u0004 — \u0003היה בהן שום דופי.\u0004","ושואלים על כך: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה בחסיד אחד ש\u0004חלה ו\u0003היה גונח מלבו. ושאלו לרופאים\u0004 כיצד יירפא, \u0003ואמרו\u0004 הרופאים כי \u0003אין לו תקנה\u0004 (רפואה) \u0003עד שיינק\u0004 מן העטין \u0003חלב רותח\u0004 (חמים) בכל \u0003שחרית\u0004 (בוקר). \u0003ו\u0004לצורך זה \u0003הביאו\u0004 לו \u0003עז, וקשרו לו\u0004 אותה \u0003בכרעי מיטתו, והיה יונק ממנה\u0004 בכל בוקר \u0003חלב.\u0004","\u0003למחר נכנסו חביריו לבקרו\u0004 ביקור חולים, \u0003כיון שראו\u0004 את \u0003העז\u0004 שבביתו, \u0003אמרו: ליסטים מזויין,\u0004 היא העז שהיא כליסטים, שהולכת ורועה בשדות אחרים, ישנו \u0003בתוך ביתו, ואנו נכנסים לבקרו?!\u0004 ונמסר כי \u0003ישבו\u0004 חכמים \u0003ובדקו\u0004 אחרי כל מעשיו, \u0003ולא מצאו בו\u0004 כל \u0003עון\u0004 שהוא, \u0003אלא של אותה העז בלבד.\u0004","\u0003ואף הוא בשעת מיתתו אמר: יודע אני בעצמי שאין בי\u0004 כל \u0003עון, אלא של אותה העז בלבד, שעברתי על דברי חבירי. שהרי אמרו חכמים: אין מגדלין בהמה דקה בארץ ישראל,\u0004 משום יישוב ארץ ישראל, שמשחיתה היא את הצומח בארץ. עד כאן לשון הברייתא.","\u0003ו\u0004מעתה הרי \u0003קיימא לן\u0004 \u0005[מקובל בידינו]\u0006 כלל זה, כי \u0003כל היכא דאמר\u0004 \u0005[היכן שאמרו\u0006 חכמים בדבריהם\u0005]\u0006 \u0003\"מעשה בחסיד אחד\"\u0004 ולא ציינו במפורש מיהו אותו חסיד — הכוונה היא \u0003או\u0004 ל\u0003ר' יהודה בן בבא או\u0004 ל\u0003ר' יהודה בר אילעאי, ו\u0004הרי \u0003רבנן בתר\u0004 \u0005[חכמים\u0006 אלו, ר' יהודה בן בבא ור' יהודה בר אלעאי, \u0005אחר]\u0006 תקופת \u0003יוסף בן יועזר איש צרידה, דרי דרי הוו\u0004 \u0005[דורות דורות\u0006 רבים \u0005היו],\u0006 נמצא איפוא שגם בדורות מאוחרים שלאחר יוסף בן יועזר היו חכמים שלא היה בהם כל דופי!"],["\u0003אמר רב יוסף\u0004 בתשובה לשאלה זו: מה שאמרו שבדורות שלאחר יוסף בן יועזר איש צרידה היה בהם מקצת דופי, אין הכוונה לדופי שבחטא, אלא רק על \u0003דופי\u0004 שבעניינה \u0003של\u0004 המחלוקת על ה\u0003סמיכה\u0004 על שלמי חגיגה ביום טוב \u0003קתני\u0004 \u0005[שנינו].\u0006 שעד למחלוקת זו שבענין סמיכה לא נחלקו כלל. ודופי זה הכרוך במחלוקת החל רק לאחר שמת יוסף בן יועזר.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אף \u0003יוסף בן יועזר גופיה מיפליג פליג\u0004 \u0005[עצמו חולק]\u0006 \u0003בסמיכה\u0004 על יוסף בן יוחנן איש ירושלים, ומדוע מציינים כי רק לאחריו החל דופי זה של המחלוקת? ומשיבים: \u0003כי איפליג\u0004 \u0005[כאשר חלק]\u0006 \u0003בה\u0004 יוסף בן יועזר — היה זה \u0003בסוף שניה\u0004 \u0005[שנותיו],\u0006 \u0003דבצר ליבא\u0004 \u0005[ש\u0006כבר \u0005התמעט הלב],\u0006 ונחשב הדבר כלאחר זמנו של יוסף בן יועזר.","\u0003גופא\u0004 \u0005[לגופם]\u0006 של הדברים שנשתכחו בימי אבלו של משה. \u0003אמר רב יהודה,\u0004 \u0003אמר שמואל: שלשת אלפים הלכות נשתכחו בימי אבלו של משה. אמרו לו\u0004 עם ישראל שבאותו הדור \u0003ל\u0004ממלא מקומו \u0003יהושע\u0004 בן נון: \u0003שאל\u0004 מן השמים שיורוך אותן הלכות שנשתכחו! \u0003אמר להם: \"לא\u0004 \u0003בשמים היא\u0004 התורה\" (על פי דברים ל, יב), שלאחר שניתנה התורה בסיני הריהי מסורה בידי החכמים שבכל דור לדון בה, ואין היא עוד בשמים להוסיף וללמוד בה בדרך נבואה.","ולאחר שנים \u0003אמרו לו\u0004 עם ישראל \u0003לשמואל\u0004 הנביא: \u0003שאל\u0004 מן השמים ויורוך הלכות אלה שנשתכחו! \u0003אמר להם:\u0004 אין לעשות כן, שהרי נאמר בתורה, בפסוק האחרון שבספר ויקרא \u0003\"אלה המצות\u0004 אשר צוה ה' את משה אל בני ישראל בהר סיני\" (ויקרא כז, לד), והרי לשון הדגשה זו \"אלה\" — באה להורות: דווקא אלה הן המצוות, ואין זולתן, \u0003שאין הנביא\u0004 בכוח נבואתו \u0003רשאי לחדש דבר\u0004 מצוה \u0003מעתה,\u0004 מעת שהסתלק משה רבינו. \u0003אמר ר' יצחק נפחא: אף\u0004 הלכה זו של ה\u0003חטאת שמתו בעליה\u0004 כיצד לנהוג בה, אם ברעייה או בהמתה, \u0003נשתכחה בימי אבלו של משה.\u0004","ועוד קודם לכן \u0003אמרו\u0004 ישראל \u0003לפנחס\u0004 בן אלעזר בן אהרן הכהן: \u0003שאל\u0004 מן השמים שיורוך הלכות אלה שנשתכחו! \u0003אמר ליה\u0004 \u0005[לו,\u0006 להם\u0005]:\u0006 אין לעשות כן, כי \u0003לא בשמים היא\u0004 התורה. ועוד \u0003אמרו לו לאלעזר\u0004 בן אהרן הכהן: \u0003שאל! אמר להם:\u0004 אין לעשות כן, שהרי נאמר בתורה \u0003\"אלה המצות\u0004 אשר צוה ה' את משה אל בני ישראל בהר סיני\" — ללמד \u0003שאין נביא רשאי לחדש דבר מעתה.\u0004","ועוד בענין לימוד תורה שלאחר פטירת משה רבינו. \u0003אמר רב יהודה,\u0004 \u0003אמר רב: בשעה שנפטר משה רבינו לגן עדן, אמר לו ליהושע\u0004 משרתו: \u0003שאל ממני כל ספיקות שיש לך,\u0004 ואפתור לך אותם! \u0003אמר לו\u0004 יהושע: \u0003רבי, כלום הנחתיך שעה אחת והלכתי למקום אחר?\u0004 וכי \u0003לא כך כתבת בי\u0004 בתורה \u0003\"ומשרתו יהושע בן נון נער לא ימיש מתוך האהל\"\u0004 (שמות לג, יא)?! ואילו היו לי ספקות, הייתי שואלם. ונמסר כי \u0003מיד\u0004 שאמר כן, \u0003תשש כחו של יהושע,\u0004 על שהשתבח בעצמו, \u0003ונשתכחו ממנו שלש מאות הלכות, ונולדו לו שבע מאות ספיקות, ועמדו\u0004 עליו \u0003כל ישראל להרגו\u0004 אלא אם כן ילמדם אותן הלכות.","\u0003אמר לו הקדוש ברוך הוא: לומר לך\u0004 אותן הלכות — \u0003אי אפשר,\u0004 ואשר לעם ישראל הדורשים ממך לגלותן — \u0003לך וטורדן\u0004 (העסק אותם) \u0003במלחמה,\u0004 ויניחו לך. \u0003ש\u0004כן \u0003נאמר\u0004 בתחילת ספר יהושע: \u0003\"ויהי אחרי מות משה עבד ה' ויאמר ה'\u0004 אל יהושע בן נון משרת משה לאמר. משה עבדי מת ועתה קום עבור את הירדן הזה אתה וכל העם הזה אל הארץ אשר אנכי נותן להם לבני ישראל\" (יהושע א, א—ב). שמיד בסמוך לפטירת משה, נערכו למלחמה.","\u0003במתניתין תנא\u0004 \u0005[במשנה שנה\u0006 החכם\u0005]:\u0006 \u0003אלף ושבע מאות קלין וחמורין\u0004 (הלכות שנלמדו במידת קל וחומר), \u0003וגזירות שוות\u0004 (הלכות שנלמדו במידת גזירה שווה), \u0003ודקדוקי סופרים נשתכחו בימי אבלו של משה.\u0004","\u0003אמר ר' אבהו: אף על פי כן החזירן\u0004 לכל אותן הלכות \u0003עתניאל בן קנז מתוך פלפולו\u0004 בתורה, \u0003ש\u0004כן \u0003נאמר:\u0004 \"ויאמר כלב אשר יכה את קרית ספר ולכדה ונתתי לו את עכסה בתי לאשה. \u0003וילכדה עתניאל בן קנז אחי כלב ויתן לו את עכסה בתו לאשה\"\u0004 (יהושע טו, טז—יז). ונדרש הדבר על חלק התורה (\"קרית ספר\") שלא היה בידיהם אחר שנשתכח והשיבו עתניאל בפלפולו (\"וילכדה\"). כיון שהובאו דברים בעניינו של עתניאל, דורשים עוד בכתובים אלה. \u0003ולמה נקרא שמה\u0004 של אשתו \u0003\"עכסה\"?\u0004 — \u0003שכל הרואה אותה כועס על אשתו\u0004 שאין היא נאה כמותה.","עוד מסופר שם אודות עכסה, כי \u0003\"ויהי בבואה ותסיתהו לשאל מאת אביה שדה ותצנח מעל החמור\"\u0004 (יהושע טו, יח), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 של כתוב זה \u0003\"ותצנח\"\u0004 שמשמעו בלשונם — צווחה, צעקה רמה, ומה ראתה לעשות זאת מעל גבי החמור? \u0003אמר רבא, אמר ר' יצחק,\u0004 שכך \u0003אמרה לו\u0004 עכסה לכלב: \u0003מה חמור זה,\u0004 כך היא דרכו, \u0003כיון שאין לו מאכל באבוסו\u0004 — \u0003מיד\u0004 הוא \u0003צועק. כך אשה, כיון שאין לה תבואה בתוך ביתה\u0004 — \u0003מיד\u0004 היא \u0003צועקת.\u0004","עוד נאמר שם בענין עכסה: \u0003\"ותאמר תנה לי ברכה כי ארץ הנגב נתתני\u0004 ונתתה לי גולות מים ויתן לה את גולות עליות ואת גולות תחתיות\" (יהושע טו יט). ודורשים: \"ארץ הנגב נתתני\" — שאמרה לו: נתתני ב\u0003בית שמנוגב\u0004 (יבש, חרב) \u0003מכל טובה.\u0004 ואף על פי כן \u0003\"ונתתה לי גלת מים\"\u0004 — \u0003אדם שאין בו אלא תורה\u0004 (המכונה \"מים\") \u0003בלבד\u0004 שרק היא גלויה (\"גולות\") לו, ואולם אינו יכול לפרנס אותי, ומנין לי מזונות? ולכן אני מבקשת: \"תנה לי ברכה\" — אדם שחוץ מלימוד התורה יעסוק אף בפרנסה. ומסופר: \u0003\"ויתן לה כלב את גלת עליות ואת גלת תחתיות\",\u0004 ונדרש הדבר כך: ש\u0003אמר לה: מי\u0004 שחכם הוא בתורה, \u0003שדר\u0004 ב\u0003עליונים ו\u0004ב\u0003תחתונים, יבקש ממנו מזונות?!\u0004 שאין הוא נזקק לכך, שוודאי אלה יימצאו לו בזכות עיסוקו בתורה.","\u0003ו\u0004שואלים: האם \u0003כלב, בן קנז הוא? והלא כלב בן יפונה הוא!\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יפונה\"?\u0004 — הרי זה כינוי שניתן לו על \u0003שפנה מעצת מרגלים,\u0004 שלא היה עימם בהוצאת דיבת הארץ.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 האם \u0003בן קנז הוא?\u0004 והלא \u0003בן חצרון הוא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וכלב בן חצרון הוליד את עזובה\"\u0004 (דברי הימים א' ב, יח)! \u0003אמר רבא:\u0004 כלב אמנם היה בנו של חצרון, ואולם לאחר שמת אביו חצרון נישאה אמו לקנז, ונמצא איפוא שכלב \u0003חורגיה\u0004 \u0005[\u0006בנו \u0005חורגו]\u0006 של \u0003קנז הוא\u0004 ועתניאל היה אחיו מן האם.","ועוד בעניינו של עתניאל. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003הוא עתניאל, הוא יעבץ,\u0004 שאין אלה אלא כינויים, \u0003ומה שמו\u0004 המקורי? — \u0003יהודה אחי שמעון שמו.\u0004 ולפשרם של כינויים אלה: \u0003\"עתניאל\"\u0004 — על שם \u0003שענאו אל\u0004 לתפילתו. \u0003\"יעבץ\"\u0004 — על שם \u0003שיעץ וריבץ תורה בישראל.\u0004","\u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 \u0003שענאו אל\u0004 לתפילתו? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויקרא יעבץ לאלהי ישראל לאמר אם ברך תברכני והרבית את גבולי והיתה ידך עמדי ועשה מרעתי לבלתי עצבי ויבא אלהים את אשר שאל\"\u0004 (דברי הימים א ד, י).","ומסבירים את תפילתו זו: \u0003\"אם ברך תברכני\"\u0004 — \u0003ב\u0004לימוד ה\u0003תורה, \"והרבית את גבולי\"\u0004 — \u0003בתלמידים\u0004 שילמדו לפניי, \u0003\"והיתה ידך עמדי\"\u0004 — \u0003שלא ישתכח תלמודי מלבי, \"ועשה מרעתי\"\u0004 — \u0003שיזדמנו לי ריעים כמותי, \"לבלתי עצבי\"\u0004 — \u0003שלא ישגבני\u0004 (יתעצם עלי) \u0003יצר הרע\u0004 לבטלני \u0003מלשנות\u0004 בתורה. \u0003אם אתה עושה כן\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הריני הולך לנסיסי\u0004 \u0005[בעצב]\u0006 \u0003לשאול\u0004 (לקבר). \u0003מיד, \"ויבא אלהים את אשר שאל\".\u0004","\u0003כיוצא בדבר אתה אומר\u0004 שכל המוסר נפשו על לימוד התורה — ה' נענה לו, וכפי שנאמר: \u0003\"רש ואיש תככים נפגשו מאיר עיני שניהם ה'\"\u0004(משלי כט, יג), ופירשו פסוק זה: \u0003בשעה שהתלמיד\u0004 (\"רש\" שאינו יודע כלום) \u0003הולך אצל רבו\u0004 (\"איש תככים\" — המצוי בתווך, שיודע די כדי ללמד לזה שאינו יודע כלום, אבל הוא עצמו צריך עדיין ללמוד), \u0003ואומר לו: למדני תורה! אם מלמדו\u0004 — מתקיים בשניהם הכתוב \u0003\"מאיר עיני שניהם ה'\"\u0004(שהן התלמיד והן הרב גדלים בתורה). \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין הרב נענה לתלמיד ללמדו תורה — מתקיים בהם הכתוב \u0003\"עשיר ורש נפגשו עשה כלם ה'\"\u0004(משלי כב, ב), ללמד: כי \u0003מי שעשאו חכם לזה,\u0004 הרב שסירב ללמד תורה — \u0003עושה אותו\u0004 עתה ל\u0003טיפש,\u0004 ומי שעשאו \u0003טיפש לזה,\u0004 התלמיד המבקש ללמוד תורה — \u0003עושה אותו\u0004 עתה לחכם. זו משנת ר' נתן.","\u0003ר' יהודה הנשיא אומר\u0004 פירוש אחר בתפילת יעבץ: \u0003\"אם ברך תברכני\"\u0004 — \u0003בפריה ורביה, \"והרבית את גבולי\"\u0004 — \u0003בבנים ובבנות, \"והיתה ידך עמדי\"\u0004 — \u0003במשא ובמתן, \"ועשית מרעתי\"\u0004 — \u0003שלא יהא בי מיחוש\u0004 (כאב) \u0003ראש ומיחוש אזנים ומיחוש עינים, \"לבלתי עצבי\"\u0004 — \u0003שלא ישגבני\u0004 (יתחזק עלי) \u0003יצר הרע\u0004 לבטלני \u0003מלשנות\u0004 בתורה. \u0003אם אתה עושה כן\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הריני הולך בנסיסי\u0004 \u0005[בעצב]\u0006 \u0003לשאול\u0004 (לקבר). מיד, \u0003\"ויבא לו אלהים את אשר שאל\"\u0004 — שנענה לתפילתו.","\u0003כיוצא בדבר אתה אומר: \"רש ואיש תככים נפגשו מאיר עיני שניהם ה'\"\u0004— \u0003בשעה שעני הולך אצל בעל הבית, ואמר\u0004 לו: \u0003פרנסני! אם\u0004 העשיר אכן \u0003מפרנסו\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — מתקיים בשניהם \u0003\"עשיר ורש נפגשו עשה כלם ה'\", מי שעשאו עשיר לזה\u0004 — הריהו \u0003עושה אותו\u0004 עתה ל\u0003עני,\u0004 ומי שעשאו \u0003עני לזה\u0004 — הריהו \u0003עושה אותו\u0004 עתה ל\u0003עשיר.\u0004","שנינו במשנתנו ש\u0003אמר ר' שמעון מה מצינו\u0004 בשלוש מבין חמש חטאות המתות (ולד החטאת, תמורה החטאת, וחטאת שמתו בעליה) שאין הן מתקיימות אלא בחטאת היחיד ולא בחטאת הציבור, אף השתים האחרות, החטאת שהתכפרו בעליה והחטאת שעברה שנתה, אינן אלא בחטאת יחיד ולא בחטאת ציבור.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003ר' שמעון אומר: חמש חטאות מתות,\u0004 ואלו הן: \u0003ולד חטאת, ותמורת חטאת, וחטאת שמתו בעליה, וחטאת שכפרו בעליה, וחטאת שעיברה שנתה.\u0004","\u0003אי\u0004 (אין) \u0003אתה יכול לומר\u0004 ב\u0003ולד חטאת\u0004 שמדובר \u0003ב\u0004חטאת \u0003ציבור\u0004 — \u0003לפי שאין חטאת נקבה בציבור. ואי אתה יכול לומר\u0004 ב\u0003תמורת חטאת\u0004 שמדובר \u0003ב\u0004חטאת \u0003ציבור\u0004 — \u0003לפי שאין ציבור עושין תמורה. ואי אתה יכול לומר\u0004 ב\u0003חטאת שמתו בעליה\u0004 שמדובר \u0003ב\u0004חטאת \u0003ציבור\u0004 — \u0003לפי שאין הציבור מתים.\u0004","ואילו ביחס לחטאת \u0003שכיפרו\u0004 (שהתכפרו כבר) \u0003בעליה\u0004 בחטאת אחרת אחר שאבדה זו ואחר הכפרה נמצאה, \u0003ו\u0004חטאת ציבור \u0003שעיברה\u0004 (עברה) \u0003שנתה\u0004 — \u0003לא מצינו\u0004 \u0005[מצאנו]\u0006 במפורש מה דינן, \u0003יכול יהו נוהגות\u0004 בדין זהה \u0003בין ב\u0004חטאת \u0003יחיד בין ב\u0004חטאת \u0003ציבור?\u0004","— \u0003אמרת: ילמד אדם\u0004 דינו של ה\u0003סתום\u0004 (זה שלא נתפרש דינו, שתי חטאות אלה של ציבור) \u0003מ\u0004זה ש\u0003מפורש\u0004 דינו (שאר שלש החטאות של ציבור). ומעתה נאמר: \u0003מה מפורש\u0004 — נוהג דווקא \u0003ביחיד ולא בצבור, אף ב\u0004חטאת \u0003שכיפרו בעליה ו\u0004חטאת \u0003שעיברה שנתה\u0004 — דווקא \u0003ב\u0004חטאת \u0003יחיד\u0004 ה\u0003דברים אמורים ולא ב\u0004חטאת \u0003ציבור.\u0004"],["ומבררים את דברי ר' שמעון אלה: \u0003וכי דנין\u0004 (למדים) דינו של דבר שהוא בגדר \u0003אפשר\u0004 (כגון שתי חטאות אלו, שהתכפרו בעליה ושעבר שנתה, שאפשר שתתקיימנה בציבור) \u0003מ\u0004דינו של זה \u0003ש\u0004הוא בגדר \u0003אי אפשר\u0004 (כגון בשלש החטאות הללו, ולד חטאת, תמורת חטאת, וחטאת שמתו בעליה, שאין אפשרות שתתקיימנה בציבור)? ומשיבים: \u0003ר' שמעון בחד מקום גמיר להו\u0004 \u0005[במקום אחד,\u0006 כהלכה אחת, \u0005למד אותן],\u0006 את דינן של כל החטאות הללו, ואין לחלק ביניהם בדין.","\u0003אמר ריש לקיש\u0004 בהסבר הדברים: מעיקרה של ההלכה למשה בסיני, \u0003ארבעה\u0004 חטאות בלבד הן ש\u0003נתנו להן\u0004 לישראל שדינן כחטאות המתות, ועוד נאמרה להם הלכה נוספת בחטאת חמישית, שדינה לרעייה. \u0003ו\u0004אולם כיון שלא ידעו מיהי אותה חטאת חמישית, \u0003העמידום\u0004 חכמים את דין ההמתה \u0003על\u0004 כל \u0003חמש\u0004 החטאות. \u0003ו\u0004כיון שכל ארבע החטאות נאמרו כהלכה אחת, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שמדובר בהלכה זו \u0003ב\u0004חטאות \u0003צבור,\u0004 יש לתמוה: וכי \u0003הנך מי איתנהו\u0004 \u0005[הללו,\u0006 ארבע חטאות, \u0005האם\u0006 כולן \u0005ישנן,\u0006 נוהגות\u0005]\u0006 \u0003בצבור?\u0004 הלא, כאמור, רק שתים מהן שייכות בציבור! \u0003אלא על כרחיך\u0004 יש לומר שנאמרה ההלכה רק בחטאת יחיד. ומעתה, \u0003ילמד\u0004 גם ה\u0003סתום\u0004 (דינה של החטאת החמישית, שנתעלמה מיהי) \u0003מ\u0004הדין ה\u0003מפורש\u0004 שאין המתה אלא בחטאות יחיד.","ואילו \u0003ר' נתן אומר\u0004 בהסבר הדברים באופן אחר: רק דינה של \u0003אחת\u0004 מתוך חמש החטאות הללו היא ש\u0003נתנה להן\u0004 לישראל כחטאת המתה, ואילו שאר הארבע דינן מעיקרו היה לרעייה, \u0003ו\u0004מן הספק איזו מהן היא המתה \u0003העמידוה\u0004 חכמים להלכה זו של המתה \u0003על\u0004 כל \u0003חמש\u0004 החטאות.","\u0003ו\u0004שואלים על דברי ר' נתן אלו: מדוע העמידו חכמים בגלל הספק את דין כל חמש החטאות הללו למיתה, והרי שתי סדרות (קבוצות) חטאות הן: האחת — ולד חטאת, תמורת חטאת, וחטאת שמתו בעליה — שכולן אפשריות רק ביחיד, והשנית — שהתכפרו בעליה, ושעברה שנתה — שאפשריות ביחיד ובציבור. ומעתה, \u0003ליחזי בהי סידרא גמירי להו\u0004 \u0005[שיראו,\u0006 שיבדקו תחילה, \u0005באיזו סדרה למדו אותה,\u0006 את החטאת המתה\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 בין החטאות הנוהגות רק \u0003ביחיד אי\u0004 \u0005[אם]\u0006 בין החטאות הנוהגות גם \u0003בצבור?\u0004 ושמא דין המתה נאמר בסדרה אחת של החטאות, ורק בהן יתקיים דין המתה, ואילו בסדרה האחרת תישארנה החטאות בדין רעייה!","ומשיבים: \u0003שתיי שכחיות שכחו,\u0004 שבתחילה נשכח מהם איזו היא החטאת שדינה למיתה, ולאחר מכן נשכח מהם אף באיזו סדרת חטאות היא נכללת. \u0003ו\u0004כיון שנשכחו שני אלה, לפיכך \u0003קשיא להו\u0004 \u0005[היה קשה להם]\u0006 מה דינן של החטאות הללו.","\u0003ו\u0004אמרו מן הסברה: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר כי הלכה זו של המתה נאמרה גם \u0003ב\u0004חטאות \u0003צבור\u0004 — יש לתמוה: וכי כל \u0003הנך מי איתנהו\u0004 \u0005[אלה,\u0006 הארבע חטאות הנוספות, \u0005האם\u0006 כולן \u0005ישנן,\u0006 נוהגות\u0005]\u0006 \u0003בצבור?\u0004 והלא רק שתים מהן שייכות בציבור, כאמור לעיל. \u0003אלא\u0004 על כרחך \u0003שמע מינה\u0004 \u0005[שמע,\u0006 למד, \u0005מכאן]\u0006 שנאמרה ההלכה רק בחטאת יחיד. ומעתה, \u0003ילמד\u0004 גם ה\u0003סתום\u0004 (דינן של ארבע החטאות שנתעלמו מיהן) \u0003מ\u0004הדין ה\u0003מפורש, מה\u0004 ב\u0003מפורש\u0004 אין המתה בחטאות, אלא \u0003ב\u0004חטאות \u0003יחיד ולא בצבור, אף\u0004 ה\u0003סתום\u0004 — דווקא \u0003ב\u0004חטאות \u0003יחיד ולא ב\u0004חטאות \u0003צבור.\u0004","יש צדדים של \u0003חומר\u0004 (חומרה) \u0003בקדשים\u0004 (בהמה שהוקדשה לקרבן) יותר \u0003מ\u0004אשר \u0003בתמורה\u0004 (בהמה שהוקדשה בדרך המרה), \u0003ו\u0004יש צדדים של \u0003חומר\u0004 (חומרה) \u0003בתמורה\u0004 יותר \u0003מ\u0004אשר \u0003בקדשים.\u0004 ומפרטים: \u0003חומר בקדשים\u0004 יותר \u0003מבתמורה: שהקדשים עושין תמורה,\u0004 שהממיר בהמת הקדש על בהמת חולין — חלה התמורה ובהמת החולין קדושה, ולוקה על כך. \u0003ואין\u0004 בהמת \u0003תמורה עושה תמורה,\u0004 שהממיר בהמה שקדושתה באה לה מהיותה תמורה לבהמת קרבן, על בהמת חולין — לא חלה התמורה. ועוד חומרה: ש\u0003הצבור והשותפין מקדישין\u0004 בהמה לקרבן, \u0003אבל לא ממירין.\u0004 וחומרה נוספת: \u0003מקדישין\u0004 אף \u0003עוברין\u0004 במעי אמם \u0003ואברים\u0004 של בהמה, \u0003אבל לא ממירין\u0004 אברים ועוברים.","ומן הצד האחר, יש \u0003חומר\u0004 \u0003בתמורה\u0004 יותר \u0003מבקדשים: ש\u0004אם המיר בהמת קודש שאין בה מום קבוע (שאינו עובר) על בהמת חולין שיש בה מום קבוע — \u0003הקדושה חלה\u0004 אף \u0003על\u0004 בהמת חולין זו שהיא \u0003בעלת מום קבוע,\u0004 מה שאין כן בהקדש שאינו חל על בהמה בעלת מום קבוע. \u0003ו\u0004חומרה נוספת שיש בתמורה ואין בקדשים, שאף אם יפדו את התמורה בדמים — \u0003אין\u0004 היא \u0003יוצא\u0004 (יוצאת) \u0003לחולין\u0004"],["לענין זה שיהיה מותר \u0003לגזוז\u0004 את צמרה, \u0003וליעבד\u0004 (לעשות עבודה בה). \u0003ר' יוסי בר' יהודה אומר:\u0004 חומרה נוספת שיש בתמורה על פני הקדשים: ש\u0003עשה\u0004 דין ה\u0003שוגג כ\u0004דין \u0003מזיד בתמורה,\u0004 שאף הממיר בשוגג — הרי זו תמורה, ולוקה עליה, כדין הממיר במזיד. \u0003ולא עשה שוגג כמזיד במוקדשין,\u0004 שאם הקדיש בשוגג — אין זה הקדש, ואם הקדיש בשוגג בעל מום — אינו לוקה על כך.","\u0003ר' אלעזר אומר: הכלאים\u0004 (הנולד מהכלאה של שני בעלי חיים ממינים שונים, כגון מזיווגם של תיש ורחל), \u0003והטרפה\u0004 (העומדת למות תוך שנים עשר חודש, וכגון שנטרפה על ידי חיה), \u0003והיוצא דופן\u0004 (שנולד שלא כדרך הרגילה אלא בניתוח, שנחתך דופן הרחם כדי שיצא משם), \u0003וטומטום\u0004 (שאין בו מסימני המין, ואין ידוע אם זכר הוא או נקיבה היא) \u0003ואנדרוגינוס\u0004 (שיש בו מסימני הזכר ומסימני הנקיבה גם יחד) — כל אלה \u0003לא קדושין\u0004 (אין הם עצמם מתקדשים בקדושת הגוף, בכל דרך הקדשה שהיא), \u0003ו\u0004אם התקדשו (כגון שהקדיש בהמה ואחר כך נטרפה) — \u0003לא מקדישין\u0004 אחרים, שאם המיר בהמת חולין עליהם — אין היא קדושה.","על דברי ר' יוסי בר' יהודה שדין התמורה נוהג בשוגג כבמזיד, שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מה מקור\u0005]\u0006 שיטתו זו של \u0003ר' יוסי בר' יהודה?\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת התמורה \"והיה הוא ותמורתו \u0003יהיה קדש\"\u0004 (ויקרא כז, י), והמלה \"יהיה\" לכאורה מיותרת, אלא הרי זה בא \u0003לרבות\u0004 את הממיר ב\u0003שוגג\u0004 שיהיה דינו \u0003כ\u0004ממיר ב\u0003מזיד.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 באיזה אופן של תמורה יהיה דין ה\u0003שוגג כ\u0004דין ה\u0003מזיד? אמר חזקיה: כ\u0004מקרה זה של האדם ה\u0003סבור שהוא מותר להמיר.\u0004 שבכגון זה \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 ה\u0003תמורה\u0004 — חלה קדושה על בהמת החולין, וממילא הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על שעבר על איסור תורה, אף ששגג בדבר, ונלמד הדבר מגזירת הכתוב (\"יהיה\"). ואילו \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003קדשים,\u0004 אם שגג והקדיש את שאינו ראוי, וכגון בעל מום — \u0003לא לקי\u0004 \u0005[אינו לוקה],\u0006 שאין לוקה אלא העובר במזיד ושהתרו בו.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תמורה\u0004 — בהמת החולין \u0003קדיש\u0004 \u0005[מתקדשת]\u0006 בכך, אף שהיה הדבר בשוגג. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים\u0004 — בהמה בעלת מום שהוקדשה בשוגג \u0003לא קדיש\u0004 \u0005[אינה מתקדשת]\u0006 בכך.","\u0003ריש לקיש ור' יוחנן אמרי\u0004 \u0005[אומרים]\u0006 הסבר אחר בדברי ר' יוסי בר' יהודה: דרך השגגה היתה \u0003כ\u0004מקרה זה של האדם שהיה \u0003סבור לומר\u0004 \"בהמה זו תהא \u0003תמורת עולה\u0004 שיש לי\", \u0003ו\u0004במקום זה שגג ו\u0003אמר\u0004 \"בהמה זו תהא \u0003תמורת שלמים\u0004 שיש לי\". \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 נאמרה ביחס לאופן בו יש הבדל בין דין השוגג בתמורה ובין דין השוגג בקדשים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תמורת שלמים,\u0004 אם המיר בשוגג בהמת שלמים בבהמת חולין — הרי בהמת החולין \u0003קדיש\u0004 \u0005[מתקדשת]\u0006 בכך, אף שהיה הדבר בשוגג. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים\u0004 אם הקדיש בעלת מום לשלמים — הבהמה \u0003לא קדיש\u0004 \u0005[אינה מתקדשת]\u0006 בכך.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחר]\u0006 באופן השגגה בה דיבר ר' יוסי בר' יהודה: \u0003כ\u0004מקרה זה של אדם שהיה \u0003סבור לומר\u0004 \"שור \u0003שחור\u0004 שיצא מביתי תחילה יהיה תמורה תחת בהמת קדשים זו\", \u0003ו\u0004במקום זה \u0003אמר\u0004 \"שור \u0003לבן\u0004 שיצא מביתי תחילה יהיה תמורה תחת בהמת קדשים זו\", ואכן יצא מביתו שור לבן. ובכך נבדלים דין התמורה מדין הקדשים, שכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תמורה\u0004 — הריהו קדוש, והממיר \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך, ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים\u0004 אם רצה לומר \"שור בעל מום שחור שיצא מביתי תחילה יהיה קרבן\", ובמקום זה אמר \"שור בעל מום לבן שיצא תחילה מביתי יהיה קרבן\" ואכן יצא מביתו שור לבן בעל מום — אינו קדוש, ולכך המקדיש \u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 על כך.","\u0003ר' יוחנן אמר\u0004 אופן אחר של השגגה: מדובר \u0003ב\u0004אדם ה\u0003אומר \"תצא\u0004 מקדושתה לחולין בהמת הקדש \u0003זו, ותיכנס\u0004 מחולין לקדושה תחתיה בהמת חולין \u0003זו\",\u0004 שהממיר סבור היה בטעות, כי בהמרתו יוצאת בהמת ההקדש מכלל קדושתה ונעשית חולין. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים\u0004 מדובר \u0003ב\u0004אדם שהיתה לו בהמת ההקדש ונפל בה מום, ו\u0003אמר\u0004 לעצמו, בטעות שקדשים \u0003שנולד\u0004 (שנפל) \u0003בהם מום\u0004 הריהם יוצאים בכך מידי קדושתם, ומעתה הם \u0003נאכלין בלא פדיון,\u0004 ואכן אכלם בלא פדיון. ובשגגות מעין אלה נבדל דין הקדשים מדין התמורה, שבקדשים — \u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 על כך, ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תמורה\u0004 — \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך.","\u0003רב ששת אמר\u0004 אופן אחר של השגגה: \u0003ב\u0004אדם ה\u0003אומר\u0004 לעצמו \"אלך ו\u0003אכנס לבית זה ו\u0004בהיותי שם \u0003אקדיש\u0004 בהמה מדעתי\", כלומר, בהכרה שלמה. או שאמר \"אלך ואכנס לבית זה \u0003ו\u0004בהיותי שם \u0003אמיר מדעתי\".\u0004 ואכן הלך \u0003ונכנס\u0004 לאותו בית, \u0003ו\u0004אולם בהיותו שם \u0003המיר\u0004 או \u0003הקדיש שלא מדעתו\u0004 (שלא מתוך מודעות והכרה למעשיו). ובזה נבדל דין התמורה מדין הקדשים, שכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תמורה\u0004 — הועילו דבריו ולכן הריהו \u0003לקי\u0004 \u0005[לוקה]\u0006 על כך, ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים\u0004 — לא הועילו דבריו ולכן \u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 על כך.","שנינו במשנתנו ש\u0003ר' אלעזר אומר\u0004 ש\u0003הכלאים והטרפה\u0004 והיוצא דופן וטומטום ואנדרוגינוס הריהם לא קדושים ולא מקדישים. ו\u0003אמר שמואל\u0004 בהסבר הדברים: \u0003לא קדושין\u0004 — הכוונה היא \u0003בתמורה,\u0004 שאם אמר על בהמה אחת מכל אלה, שתהיה תמורת בהמת הקדש, אין היא מתקדשת בכך. \u0003ולא מקדישין\u0004 — הכוונה היא \u0003לעשות תמורה,\u0004 שאם היתה אחת מכל אלה קדושה, והמירו עליה בהמת חולין, אין בהמת החולין מתקדשת על ידה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' מאיר: ומאחר שאין\u0004 כל אלה (הכלאים, והטריפה ושאר המנויים במשנתנו) \u0003קדושין, מהיכן\u0004 יעלה על הדעת לומר שהם \u0003מקדישין\u0004 אחרים? \u0003אלא\u0004 יש לומר כי \u0003אי\u0004 (אין) \u0003אתה מוצא\u0004 אופן בו מתקיימים דברי המשנה הללו \u0003אלא במקדיש בהמה\u0004 הכשרה להקרבה, \u0003ואחר כך נטרפה.\u0004 ביוצא דופן — \u0003ב\u0004מקרה של ה\u0003מקדיש ולד,\u0004 שחלה עליו קדושה, \u0003ויצא [דרך] דופן.\u0004 שעל אלה שייך לומר שאף שהם קדושים — אינם מקדישים. \u0003אבל\u0004 ב\u0003כלאים ו\u0004ב\u0003טומטום ו\u0004ב\u0003אנדרוגינוס, אי\u0004 (אין) \u0003אתה מוצא\u0004 אופן שבו הם קדושים \u0003אלא בולדי קדשים,\u0004 שנולדו לבהמת קדשים, וחלה עליהם קדושה ממילא, \u0003ו\u0004נצרך לומר שאין הם מקדישים \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003הולד עושה תמורה,\u0004 וללמדנו שאין ולדות אלה עושים תמורה.","ובהסבר שיטתו זו של ר' אלעזר, \u0003אמר רב פפא\u0004 [רבא]: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 [אלעזר]? — סבור הוא שדינם של אלה הריהו \u0003כ\u0004דין \u0003בהמה טמאה.\u0004 ומעתה נאמר, \u0003מה בהמה טמאה\u0004 — \u0003לא קרבה\u0004 על המזבח, \u0003ולא נחתא לה\u0004 \u0005[חלה עליה]\u0006 \u0003קדושת הגוף, אף הנך\u0004 \u0005[אלו]\u0006 — \u0003לא קרבי ולא נחתא להו\u0004 \u0005[אינם קרבים, ואין חלה עליהם]\u0006 \u0003קדושת הגוף.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 בדחיית הסבר זה: \u0003והרי בעל מום\u0004 יוכיח, \u0003דלא קריב\u0004 \u0005[ש\u0006כן \u0005אינו קרב]\u0006 על המזבח, \u0003ו\u0004בכל זאת \u0003נחתא ליה\u0004 \u0005[יורדת,\u0006 חלה \u0005עליו]\u0006 \u0003קדושת הגוף,\u0004 שהרי אם המירו בהמת הקדש על בהמת חולין בעלת מום — חלה עליה קדושה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה: אין להוכיח כן מ\u0003בעל מום,\u0004 שכן אף שבעל מום אינו קרב, מכל מקום \u0003קרב במינו\u0004 (סוג זה של בעלי חיים קרב), ואילו הכלאים והטומטום והאנדרוגינוס הריהם סוג שאינו קרב כלל. ושואלים על הסבר זה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחלות הקדושה תלויה בסוגו של בעל החיים, אם הוא קרב, \u0003טרפה נמי קא\u0004 \u0005[גם כן הריהי]\u0006 \u0003קרבה במינה,\u0004 ומדוע איפוא לא חלה קדושה עליה, אם המירו עליה, ואינה עושה תמורה?","\u0003אלא אמר רבא:\u0004 טעמו של ר' אלעזר, שסבור הוא אכן שדינם של אלה הריהו \u0003כ\u0004דין \u0003בהמה טמאה,\u0004 ואולם למד הוא זאת בדרך אחרת: \u0003מה בהמה טמאה\u0004 — הרי זה \u0003פסול הגוף,\u0004 ואינה קדושה ואינה מקדישה, \u0003אף כל\u0004 אלה — ש\u0003פסול הגוף\u0004 הוא, אינם קדושים ואינם מקדישים. ובאה השוואה זו \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את \u0003בעל\u0004 ה\u0003מום\u0004 — שאין זה פסול הגוף, אלא \u0003פסול חסרון\u0004 (של אבר בגופו) \u0003נינהו\u0004 \u0005[הם].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא לרבא\u0004 בקושיה: והאם פסול בעל מום הריהו תמיד מפני חסרון אבר בגוף הבהמה, \u0003והלא\u0004 אף \u0003שרוע\u0004 (שאחד מאברי הבהמה גדול מחבירו) \u0003וקלוט\u0004 (שפרסותיו אינן שסועות) \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בפרשה\u0004 המונה את בעלי המומים הפסולים להקרבה (ויקרא כב, כג), \u0003והא הני\u0004 \u0005[והרי אלו]\u0006 \u0003פסול הגוף נינהו\u0004 \u0005[הם]!\u0006","\u0003אלא אמר רבא:\u0004 טעמו של ר' אלעזר כדרך שנאמר מקודם, הריהו \u0003כ\u0004דין \u0003בהמה [טמאה],\u0004 אלא שכך היא ההשוואה בין דינם של אלו לדין בהמה טמאה: \u0003מה בהמה טמאה\u0004 — הריהי זו \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003במינה\u0004 בהמה הכשרה להקרבה, ואינה קדושה ואינה מקדישה, \u0003אף כל\u0004 אלה, \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003במינה\u0004 הכשר להקרבה, ובא לימוד זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בעל מום\u0004 — \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 \u0003במינה\u0004 הכשרה להקרבה.","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמרת\u0004 בדחיית טעם זה: \u0003טרפה\u0004 תוכיח שאינו כן, שהרי \u0003איכא\u0004 \u0005[יש]\u0006 \u0003במינה\u0004 הכשרה להקרבה ואינה קדושה ואינה מקדישה — \u0003לא דמיא\u0004 \u0005[אינה דומה]\u0006 \u0003לבעל מום,\u0004 אלא ל\u0003בהמה טמאה.\u0004 שכן בהמה טמאה \u0003אסורה באכילה, ו\u0004אף \u0003טרפה אסורה באכילה, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בעל מום\u0004 — ש\u0003מותר באכילה.\u0004","ועוד בענין הטריפה \u0003אמר שמואל: המקדיש את הטריפה\u0004 — התקדשה בכך, ו\u0003צריכה\u0004 שיפול בה \u0003מום קבוע\u0004 כדי שאפשר יהיה \u0003לפדות עליו.\u0004 ומקשים על דברים אלה: הרי אין בהמה זו מותרת לאכילת אדם על ידי פדייתה, שהרי טריפה היא, ובפדייתה היא מותרת רק לאכילת כלבים, ואם כן שמע מינה \u0005[למד מכאן]\u0006 כי \u0003פודין את הקדשים להאכילן לכלבים,\u0004 כנגד ההלכה המקובלת בידינו!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך את דברי שמואל: המקדיש את הטריפה — הרי זה עושה קדושה (למיתה. כסבור מותר להקדיש בעלי מומין לגבי מזבח, גבי \u0003תמורה\u0004 — \u0003קדיש, גבי קדשים\u0004 — \u0003לא קדיש.\u0004 ראה גרסות\u0003) למות,\u0004 שנקברת הטריפה במותה בקדושתה, ואין היא נפדית ויוצאת לחולין. \u0003ו\u0004אילו \u0003ר' אושעיא\u0004 חולק על שמואל ו\u0003אומר\u0004 כי המקדיש את הטריפה — לא אמר כלום, ו\u0003אינה אלא כמקדיש עצים ואבנים בלבד,\u0004 שאינם מתקדשים בקדושת הגוף אלא לבדק הבית, ונפדים אף שייאכלו על ידי כלבים.","ומקשים על דברי שמואל אלו: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה במסכתנו\u0005],\u0006 \u0003כל\u0004 בהמות \u0003הקדשים שנעשו טרפה\u0004 — \u0003אין פודין אותן,\u0004 להוציאן בכך לחולין, ולקנות בדמיהם קרבנות אחרים, וטעם הדבר: \u0003לפי שאין פודין\u0004 את \u0003הקדשים\u0004 על מנת \u0003להאכילן לכלבים,\u0004 אלא ימותו וייקברו בקדושתם. ויש לדייק בדברים: \u0003טעמא\u0004 \u0005[טעם,\u0006 דווקא\u0005]\u0006 שאין פודים אותם הריהו בקדשים \u0003שנעשו\u0004 טריפה, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שאם \u0003היו\u0004 טריפה \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 קודם שהקדישם — אינם קדושים כלל בקדושת הגוף אלא כבדק הבית, ו\u0003פודין אותן!\u0004 ודוחים: \u0003דלמא האי תנא סבר\u0004 \u0005[שמא תנא זה סבור]\u0006 כשיטת ר' אלעזר ש\u0003כל היכא דלא חזי\u0004 \u0005[מקום שאינו ראויה]\u0006 הבהמה \u0003לגופה\u0004 \u0005[ל\u0006היות מוקרבת \u0005בעצמה]\u0006 — אף \u0003לא נחתא\u0004 \u0005[חלה]\u0006 \u0003לה קדושת הגוף.\u0004","ומביאים עוד ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו, \u0003ר' אלעזר אומר: הכלאים, ויוצא דופן, וטריפה, וטומטום ואנדרוגינוס\u0004 — \u0003לא קדושין ולא מקדישין. ואמר\u0004 על כך \u0003שמואל\u0004 בהסבר הדברים: \u0003לא קדושין\u0004 — \u0003בתמורה, ולא מקדישין\u0004 — \u0003לעשות תמורה.\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 ש\u0003אמר ר' מאיר\u0004 בשיטת הדברים הללו: \u0003וכי מאחר שאין קדושין, מהיכן מקדישין? אלא אי\u0004 (אין) \u0003אתה מוצא\u0004 אפשרות שיהיו קדושים (הטרפה) ויהיו מקדישים \u0003אלא במקדיש בהמה ואחר כך נטרפה.\u0004 ונדייק מכאן: זה הדין כשהקדיש את הבהמה כשלא היתה טריפה, ואחר כך נטרפה, \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם \u0003היתה טרפה מעיקרא\u0004 \u0005[מתחילה],\u0006 קודם שהקדישה — \u0003לא נחתא ליה\u0004 \u0005[חלה לה]\u0006 \u0003קדושת הגוף\u0004 כלל, ושלא כדברי שמואל!"],["ומתרצים: \u0003אמר \u0004\u0005[יכול לומר] \u0006\u0003לך שמואל \u0004על כך כי \u0003דלמא הך תנא נמי סבר \u0004\u0005[שמא התנא הזה גם כן סבור] \u0006כשיטת ר' אלעזר ש\u0003כל היכא \u0004\u0005[מקום] \u0006\u0003דלא חזיא \u0004\u0005[שאינה ראויה] \u0006\u0003לגופה \u0004— \u0003לא נחתא לה \u0004\u0005[חלה עליה] \u0006\u0003קדושת הגוף. \u0004ואולם אני סבור כחכמים החולקים עליו, וסבורים שחלה קדושת הגוף.","","\u0003אלו\u0004 הם ה\u0003קדשים\u0004 (קרבנות) \u0003ש\u0004דין \u0003וולדותיהן\u0004 (הוולדות שנולדו לקרבנות ממין נקיבה) \u0003ו\u0004דין \u0003תמורותיהן\u0004 (בהמות חולין שהמירו בהן) הינו \u0003כיוצא בהן\u0004 (כדין אותם הקדשים שמהם נאצלה קדושתם): \u0003ולד\u0004 קרבן ה\u0003שלמים, ותמורתן\u0004 של השלמים, ואף \u0003ולדן\u0004 של וולד השלמים או של תמורת השלמים, \u0003ו\u0004כן \u0003ולד ולדן,\u0004 וכן הלאה \u0003עד סוף כל\u0004 דורות \u0003העולם\u0004 — הרי הן עומדים בקדושת קרבן \u0003שלמים,\u0004 וחלים עליהם דיני השלמים, \u0003ו\u0004לכן הריהם \u0003טעונין\u0004 (חייבים) \u0003סמיכה\u0004 על ראש הקרבן, \u0003ונסכים\u0004 (יין הבא עם הקרבן), \u0003ותנופת,\u0004 כלומר, לקיחה מהקרבן ונתינה לכהן של ה\u0003חזה ו\u0004ה\u0003שוק.\u0004","שואלים: \u0003כיון דתנא\u0004 \u0005[ש\u0006כבר \u0005שנה]\u0006 התנא \u0003\"ולדן וולד ולדן\",\u0004 אם כן \u0003\"עד סוף כל העולם\" למה לי?\u0004 ומשיבים: ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003שמעיה\u0004 \u0005[שמע אותו]\u0006 את \u0003ר' אלעזר\u0004 (בהמשך המשנה, בעמוד הבא) ש\u0003אמר\u0004 כי \u0003ולד שלמים לא יקרב\u0004 למזבח כקרבן ה\u0003שלמים,\u0004 אלא כונסים אותו למקום שבו נמנע ממנו מזון, והרי הוא מת. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ה\u0003תנא דידן\u0004 \u0005[שלנו]:\u0006 \u0003לא מיבעיא\u0004 \u0005[נצרך]\u0006 לומר \u0003בוולדן\u0004 — \u0003דלא מודינא\u0004 \u0005[שאין אני מודה]\u0006 לך, וסבור אני שהוא קרב על המזבח כשלמים, \u0003אלא אפילו עד סוף העולם\u0004 גם כן \u0003לא מודינא\u0004 \u0005[אינני מודה]\u0006 \u0003לך,\u0004 בכך וסבור אני שכולם קרבים שלמים. עוד שנינו במשנה שדין הולדות והתמורות כדין השלמים עצמם, ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים,\u0006 מה המקור להם בתורה\u0005]?\u0006 — \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים\u0006 בברייתא\u0005]\u0006 על האמור בתחילת פרשת השלמים \"ואם זבח שלמים קרבנו אם מן הבקר הוא מקריב אם זכר אם נקבה תמים יקריבנו...\" (ויקרא ג, א). שמאחר וכבר כתב \"אם מן הבקר\" — די בכך, והמילים \"זכר או נקבה\" מיותרות. אלא באה תוספת לשון זו, \u0003\"זכר\"\u0004 — \u0003לרבות\u0004 לכל דיני השלמים אף \u0003את הולד\u0004 הנולד לבהמת שלמים.","","ושואלים: מדוע נזקק כתוב ללמדנו דין ולדות השלמים, \u0003והלא דין\u0004 (דרך לימוד, קל וחומר) \u0003הוא\u0004 המלמדנו כן, ובאופן זה: \u0003ומה תמורה\u0004 של שלמים, הקלה, \u0003ש\u0004הרי \u0003אין\u0004 היא \u0003גידולי הקדש,\u0004 שלא גדלה במעי בהמת הקדש — דינה שהיא \u0003קריבה\u0004 כשלמים. \u0003ולד\u0004 שלמים, החמור, \u0003ש\u0004הרי הוא \u0003גידולי הקדש\u0004 — \u0003אינו דין שיקרב\u0004 כשלמים?!","ומשיבים: ניתן לפרוך קל וחומר זה, שכן: \u0003מה לתמורה,\u0004 שיש בה צד חמור, \u0003שכן\u0004 תמורה \u0003נוהגת בכל הקדשים\u0004 של יחיד, \u0003תאמר בולד,\u0004 שיש בו צד קל, \u0003ש\u0004כן \u0003אינו נוהג בכל הקדשים\u0004 (שיש קרבנות הבאים מן הזכרים, ואין בהם ולד הקדשים). והיה מקום לומר בולד השלמים ש\u0003אינו קרב\u0004 כשלמים, \u0003הואיל ו\u0004דין קדושת הולד \u0003אינו נוהג בכל הקדשים\u0004 — לכך \u0003תלמוד לומר\u0004 (משמיענו הכתוב) בייתור המלה \u0003\"זכר\"\u0004 — \u0003לרבות את הולד.\u0004 ומה שאמר עוד הכתוב \u0003\"נקבה\"\u0004 — הרי זה בא \u0003לרבות\u0004 את \u0003התמורה\u0004 של השלמים, שדינה כשלמים.","ומעירים: \u0003אין לי\u0004 ללמוד מכתוב זה \u0003אלא\u0004 ב\u0003תמורת שלמים ו\u0004ב\u0003ולד\u0004 שלמים שהם \u0003תמימין\u0004 שדינם כשלמים, ואולם \u0003ולד\u0004 של \u0003בעלי מומין ותמורת בעלי מומין\u0004 שהם עצמם תמימים \u0003מנין\u0004 לנו שגם כן דינם כשלמים? לכך תלמוד לומר\"אם זכר\", שהתוספת באה \u0003לרבות ולד בעלי מומין\u0004 וכן \u0003\"אם נקבה\"\u0004 — \u0003לרבות תמורת בעלי מומין.\u0004 ודנים בדברי ברייתא זו.","אמר ליה \u0005[לו]\u0006 \u0003רב ספרא לאביי:\u0004 מנין לנו שמ\"אם זכר\" למדים לענין ולד השלמים ומ\"אם נקבה\" למדים לענין התמורה, \u0003ואיפוך אנא\u0004 \u0005[ו\u0006מדוע לא \u0005אהפוך אני]\u0006 את דרשות הכתובים, שמ\"אם זכר\" למדים לענין התמורה ומ\"אם נקבה\" למדים לענין הולד? השיב לו אביי: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר, \u0003מ\u0004אותו \u0003מקום שנתרבתה תמורת תמימין\u0004 (מן הכתוב \"נקבה\"), בודאי \u0003נתרבתה\u0004 ממנו (מהכתוב המורחב \"אם נקבה\") גם \u0003תמורת בעלי מומין.\u0004 ובדומה לכך, כיון שמ\"זכר\" למדנו לענין ולד השלמים התמימים, אף ולד השלמים בעלי המום נלמד מאותו כתוב (\"אם זכר\"). \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא לאביי בהסבר שאלתו: \u0003מי קאמינא\u0004 \u0005[האם אמרתי]\u0006 \u0003לך ליפוך\u0004 \u0005[להפוך]\u0006 את הדרשות הנלמדות מהכתוב \u0003\"אם זכר\"\u0004 ומהכתוב \u0003\"אם נקבה\"? אנא, כוליה קרא קאמינא\u0004 \u0005[אני,\u0006 בשאלתי, על \u0005כל הכתוב אמרתי],\u0006 וכך כוונת דברי: \u0003אימא\u0004 \u0005[אמור]\u0006 שהלשון \u0003\"זכר\"\u0004 בא \u0003לרבות את התמורה,\u0004 בין בתמימים בין בבעלי מומים, והלשון \u0003\"נקבה\"\u0004 בא \u0003לרבות את הולד\u0004 בין של התמימים בין של בעלי מומים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אביי בתשובה: מסתבר לדרוש כדברי הברייתא, שכן \u0003\"ולד\"\u0004 — \u0003לשון זכר משמע,\u0004 ואילו \u0003\"תמורה\"\u0004 — \u0003לשון נקבה משמע.\u0004","","שנינו בברייתא זו כי אף ולדותיהם של קרבנות שלמים בעלי מומים נוהג בהם דין השלמים. ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לענין איזו \u0005הלכה]\u0006 נאמרו הדברים? \u0003אמר שמואל: ליקרב\u0004 \u0005[שיקרב]\u0006 הולד על המזבח, אף שאימו בעלת מום, ואינה קריבה. \u0003ואליבא\u0004 \u0005[וכשיטת] ר' אלעזר,\u0006 שכן אמר ר' אלעזר (להלן יח,ב) שהמפריש בהמה נקבה לקרבן עולה, וילדה אותה בהמה ולד זכר — הרי ולד זה קרב כעולה, אף שאימו אינה קריבה לעולה. ואף שכך היא שיטת ר' אלעזר, נצרכה הברייתא להשמיענו כן בוולדות שלמים בעלי מומים, שכן \u0003מהו\u0004","\u0003דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]:\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' אלעזר\u0004 את שיטתו זו, הרי זה דווקא בקרבן \u0003עולה\u0004 — משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם עולה על אמו,\u0004 משום שיש מציאות של עולה אף בנקיבות, בעולת העוף, \u0003אבל הני\u0004 \u0005[אלו]\u0006 \u0003ולדות\u0004 שלמים בעלי מומים — \u0003לא קרבי\u0004 \u0005[אינם קרבים],\u0006 משום שאין אופן בו ייקרא שם שלמים על בעלי מומים. לכך \u0003קמשמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאף אלה קרבים.","\u0003בר פדא אמר:\u0004 לא אמרה הברייתא שדין ולדות שלמים בעלי מומים הריהו כדין השלמים אלא \u0003ל\u0004ענין \u0003רעיה,\u0004 שיש בהם קדושה כקדושת אימם, והריהם רועים עד שיפול בהם מום, וייפדו ויביאו בדמיהם עולה, אבל הם עצמם אינם קרבים. \u0003ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003דברי הכל.\u0004 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו במחלוקת זו של שמואל ובר פדא אף רבא ורב פפא, \u0003רבא אמר:\u0004 נאמר דין ולדות בעלי מומים לענין \u0003ליקרב\u0004 \u0005[שיקרב],\u0006 \u0003ואליבא\u0004 \u0005[וכשיטת]\u0006 \u0003ר' אלעזר,\u0004 ואילו \u0003רב פפא אמר:\u0004 לא נאמר דין זה אלא \u0003ל\u0004ענין \u0003רעיה, ואליבא\u0004 \u0005[וכשיטת]\u0006 \u0003דברי הכל.\u0004 בברייתא שהובאה למעלה למדנו את דין תמורות וולדות השלמים מייתור הכתובים \"זכר\" ו\"נקבה\", \u0003ו\u0004אילו \u0003האי תנא מייתי לה מהכא\u0004 \u0005[תנא זה מביא,\u0006 לומד, \u0005אותה מכאן],\u0006 שנאמר \"רק קדשיך אשר יהיו לך ונדריך תשא ובאת אל המקום אשר יבחר ה'. ועשית עולותיך הבשר והדם על מזבח ה' אלהיך ודם זבחיך ישפך על מזבח ה' אלהיך והבשר תאכל\" (דברים יב, כו—כז).","","ובאופן זה: \u0003\"רק קדשיך\"\u0004 — \u0003אלו תמורות, \"אשר יהיו לך\"\u0004 — \u0003אלו הוולדות.\u0004 ונאמר בהם \u0003\"תשא ובאת\u0004 אל המקום אשר יבחר ה'\" — שחייב להעלותם למקדש.","ומעתה יש לדון בדבר: \u0003יכול\u0004 יהא דינם ש\u0003יכניסנו לבית הבחירה, ו\u0004אולם \u0003ימנע מהם מים ומזון כדי שימותו?\u0004 — לכך \u0003תלמוד לומר\u0004 (השמיענו הכתוב): \u0003\"ועשית עלתיך הבשר והדם\u0004 על מזבח ה' אלהיך והבשר תאכל\", ללמדנו: \u0003כדרך שאתה נוהג ב\u0004קרבן \u0003עולה\u0004 — \u0003אתה נוהג\u0004 אף \u0003בתמורה\u0004 של עולה, ו\u0003כדרך שאתה נוהג ב\u0004קרבן \u0003שלמים\u0004 — \u0003אתה נוהג\u0004 אף \u0003בולדי שלמים ובתמורה\u0004 של שלמים. ומעתה יש לשאול: \u0003יכול\u0004 דין \u0003כל קדשים כן\u0004 הוא, שתמורתם וולדותיהם קרבים על המזבח? — לכך \u0003תלמוד לומר\u0004 (משמיענו הכתוב) \u0003\"רק\u0004 קדשיך\", בלשון מיעוט (ולהלן יפורט איזה ולד התמעט), אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אינו צריך\u0004 מקרא זה של \"רק\", ש\u0003הרי הוא אומר\u0004 בדין קרבן האשם \u0003\"אשם הוא אשם אשם לה'\"\u0004 (ויקרא ה, יט), והמלה \"הוא\" באה להורות כי רק \u0003הוא,\u0004 האשם עצמו, \u0003קרב\u0004 על המזבח, \u0003ואין תמורתו קריבה.\u0004","","ודנים בדברי ברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: ממשמעות הכתוב \u0003\"תשא ובאת\" יכול\u0004 תהא למד כי \u0003יכניסנו\u0004 את הוולד או התמורה \u0003לבית הבחירה\u0004 וימנע מהם מים ומזון עד שימותו — תלמוד לומר: \"ועשית עולותיך הבשר והדם על מזבח ה' אלהיך\".","ושואלים: \u0003מנא תיתי הא\u0004 \u0005[מנין תבוא,\u0006 תעלה סברה \u0005זו],\u0006 שיסתפק בהעלאתם למקדש, ושם ימנע מהם מים ומזון כדי שימותו? שהרי \u0003כיון דגמרי\u0004 \u0005[שנלמדו\u0006 בהלכה למשה מסיני\u0005]\u0006 דינן של \u0003חמש חטאות\u0004 ושתיים מהן הריהן ולד החטאת ותמורת החטאת, נסיק מכאן כי דווקא חטאות אלה הן שמוצאות למיתה, ואילו \u0003הנך מקרב קרבי\u0004 \u0005[אלו,\u0006 ולדות שלמים ותמורות שלמים, הריהן \u0005קריבות]!\u0006","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 יכול היית לומר\u0005]\u0006 כי \u0003חמש חטאות\u0004 הללו דינן שהן \u0003מתות\u0004 (מובאות לכלל מיתה) \u0003בכל מקום, ו\u0004אילו \u0003הנך\u0004 \u0005[אלו]\u0006 וולד ותמורת שלמים — דינם ש\u0003ימותו\u0004 דווקא \u0003בבית הבחירה,\u0004 לכן \u0003קמשמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאינו כן, והריהן קרבות.","ודנים עוד בדברי ברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול אף כל הקדשים כן,\u0004 שיהא דין ולדותיהם ותמורתם כמותם? — \u0003תלמוד לומר \"רק קדשיך\"\u0004 בלשון מיעוט, לומר שאין כולם בדין זה. ושואלים: ב\u0003ולד דמאן\u0004 \u0005[של מי,\u0006 של איזה קרבן\u0005]\u0006 מדובר כאן? \u0003אי\u0004 \u0005[אם]\u0006 המדובר בולד של \u0003עולה\u0004 — הרי קרבן עולה \u0003זכר הוא, ולאו בר אולודי\u0004 \u0005[ולא בן הולדה]\u0006 \u0003הוא! ואי\u0004 \u0005[ואם]\u0006 מדובר בולד או בתמורת \u0003חטאת\u0004 — הרי \u0003גמירי לה\u0004 \u0005[מקובל הוא\u0006 בהלכה למשה מסיני\u0005]\u0006 כי \u0003למיתה\u0004 הם \u0003קיימי\u0004 \u0005[עומדים]!\u0006"],["\u0003אי\u0004 \u0005[אם]\u0006 המדובר בתמורה של קרבן \u0003אשם\u0004 — הרי \u0003גמירי לה\u0004 \u0005[למודה היא\u0006 כהלכה למשה מסיני\u0005]\u0006 שתמורת אשם \u0003לרעייה אזלא\u0004 \u0005[הולכת],\u0006 ואין צורך אם כן למעט זאת מן הכתוב! שכן כלל הוא: \u0003כל שבחטאת\u0004 דינה שהיא \u0003מתה\u0004 (מובלת למיתה, ובכללן תמורת חטאת), \u0003באשם רועה\u0004 עד שייפול בה מום ותיפדה ודמיה יפלו \u0003לעולה.\u0004 ומשיבים: \u0003לעולם\u0004 מדובר בברייתא זו \u0003ב\u0004ולד ובתמורת \u0003חטאת, ו\u0004באשר לשאלה, מדוע נזקקים אנו לפסוק הממעט אותם, שהרי הלכה למשה מסיני היא, יש להשיב: \u0003הילכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005למודה היא]\u0006 דווקא \u0003ל\u0004ענין ה\u0003מיתה, ו\u0004אילו \u0003קרא למעוטי\u0004 \u0005[הפסוק\u0006 בא \u0005למעט]\u0006 אותם \u0003ל\u0004ענין ה\u0003הקרבה,\u0004 שאין מקריבים אותם.","ותוהים על כך: \u0003ו\u0004הרי הא בהא תליא \u0005[זו בזו,\u0006 דין ההקרבה בדין המיתה \u0005תלויה],\u0006 ו\u0003כיון\u0004 ש\u0003למיתה\u0004 היא \u0003אזלא\u0004 \u0005[הולכת]\u0006 — \u0003ממילא\u0004 מובן שהיא \u0003לא קרבה!\u0004 \u0003אלא\u0004 יש לומר כי \u0003הלכתא\u0004 \u0005[ההלכה\u0006 למשה מסיני\u0005]\u0006 — באה \u0003ל\u0004ענין קרבן ה\u0003חטאת, ו\u0004אילו \u0003קרא\u0004 \u0005[הפסוק]\u0006 — בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003תמורת אשם.\u0004","ושואלים: \u0003הא נמי הילכתא גמירי לה\u0004 \u0005[זו גם כן הלכה\u0006 למשה מסיני \u0005למודה היא],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006כן \u0005אמרו]:\u0006 \u0003כל שבחטאת מתה, באשם רועה! אלא, קרא מיבעי ליה\u0004 \u0005[הפסוק נצרך לו]\u0006 להשמיענו דין נוסף, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003עבר ומקריב\u0004 \u0005[והקריב]\u0006 ולד חטאת או ולד אשם וכן תמורת חטאת או תמורת אשם — הריהו \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003ב\u0004איסור \u0003עשה,\u0004 שהרי מיעטו הכתוב ממצות עשה (שנאמרה לענין ולד עולה ושלמים), ולאו הבא מכלל עשה — עשה.","עוד שנינו בברייתא כי \u0003ר' עקיבא\u0004 חולק על ר' ישמעאל ו\u0003אומר\u0004 כי \u0003אינו צריך\u0004 פסוק זה \"רק קדשיך...\" (דברים יב, כו—כז) למעט ולדות ותמורות שאר הקדשים מהקרבה על המזבח, שכן מן הפסוק הנאמר בדין האשם (\"אשם הוא\", ויקרא ה, יט) למדים אנו שרק \u0003הוא\u0004 (האשם עצמו) \u0003קרב\u0004 על המזבח, \u0003ואין תמורתו קריבה.\u0004 ושואלים: \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 זה ללמדנו שאין תמורת האשם קריבה על המזבח, \u0003והא הילכתא גמירי לה\u0004 \u0005[והרי הלכה\u0006 למשה מסיני \u0005למודה היא]\u0006 שתמורת האשם רועה (\"כל שבחטאת מתה — באשם רועה\"), ואינה קריבה!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן, כך גם כן],\u0006 שאין צורך בדרשת הכתוב, \u0003אלא\u0004 \u0003קרא\u0004 \u0005[פסוק]\u0006 \u0003למה לי\u0004 (מהו מלמדנו) — יש לומר כי \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004למדנו \u0003כ\u0004הלכה זו שאמר \u0003רב הונא,\u0004 שכן \u0003אמר רב הונא:\u0004 בהמת קרבן \u0003אשם שניתק\u0004 (נעתק, נפסל מהקרבה, וכגון שנתכפרו בעליו בקרבן אחר) ודינו \u0003לרעייה\u0004 עד שיפול בו מום, וייפדה, ויביאו בדמיו עולה, ועמד הבעלים לפני שנפל בו מום \u0003ושחטו סתם,\u0004 בלא כוונה מיוחדת — \u0003כשר,\u0004 וקרב \u0003לשם עולה.\u0004","ולדיוק ההלכה: רק אם \u0003ניתק\u0004 לרעייה — \u0003אין\u0004 \u0005[כן] כשר לשם עולה, ואולם אם\u0006 \u0003לא ניתק\u0004 לרעיה — \u0003לא,\u0004 אינו כשר. \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור לכך בתורה\u0005]?\u0006 שכן אמר הכתוב באשם \u0003\"הוא\"\u0004 — להדגיש: \u0003בהווייתו יהא,\u0004 שעדיין הוא אשם. בעמוד הקודם הובאו שתי ברייתות בהן נלמד דין ולד השלמים שהוא שלמים. האחת למדה זאת מהכתוב \"אם זכר אם נקבה\" (ויקרא ג, א), והשניה מהכתוב \"תשא ובאת\" (דברים יב, כו).","\u0003ו\u0004שואלים: \u0003להאי\u0004 \u0005[לזה]\u0006 ה\u0003תנא\u0004 (בברייתא השניה) \u0003דקא יליף\u0004 \u0005[שהוא לומד]\u0006 את דין ולדות השלמים שהם כשלמים \u0003מהני קראי\u0004 \u0005[מהמקראות הללו],\u0006 \"תשא ובאת\" (דברים יב, כו), \u0003תיפוק לי\u0004 \u0005[תצא לו,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מ\u0004המקראות \u0003\"זכר\" ו\"נקבה\"\u0004 (ויקרא ג, א), כדרך שנלמד הדבר בברייתא הראשונה? ומשיבים: אין הוא לומד ממקרא זה, שכן הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004עניינו של \u0003ולד בעלי מומין, ולתמורת בעלי מומין.\u0004","ושואלים על כך: \u0003ותיפוק לי כולהו מהאי קרא\u0004 \u0005[ויצאו לו,\u0006 ויילמדו, \u0005כולם,\u0006 כל הדינים, הן של ולדות ותמורות שלמים והן של ולדות ותמורות בעלי מומים, \u0005מהפסוק הזה],\u0006 וכדרך שנלמד בברייתא הראשונה! ומשיבים: הלשון \u0003\"אם\"\u0004 (\"אם זכר\", \"אם נקבה\") \u0003לא משמע ליה\u0004 \u0005[אינו נראה לו]\u0006 שבא ללמד, שכן אין היא מיותרת אלא צורת לשון המקובלת במקרא.","ושואלים לצד האחר: \u0003ולהאי\u0004 \u0005[ולזה]\u0006 ה\u0003תנא\u0004 בברייתא הראשונה, \u0003דנפקא ליה\u0004 \u0005[שיוצא לו,\u0006 שלשיטתו למדים\u0005]\u0006 \u0003מ\u0004הכתוב \u0003\"זכר\" \"אם נקבה\"\u0004 את כל הדינים כולם, אם כן בכתוב \u0003\"תשא ובאת\" מה עביד להו\u0004 \u0005[עושה בו,\u0006 מה נלמד ממנו\u0005]?\u0006 ומשיבים: כתוב זה בא ללמד הלכה אחרת, שהבעלים חייבים להביא את קרבנותיהם למקדש, בעת שעולים לרגל, \u0003אפילו ממירעייהו\u0004 \u0005[מהמרעה שלהם],\u0006 שלא יתעצלו מלחפשם ומלקחתם, ולא ידחו את הבאתם לרגל הבא. \u0003לישנא אחרינא\u0004 \u0005[לשון אחר]:\u0006 בא כתוב זה ללמד שאפילו \u0003ממורגייהו\u0004 \u0005[מן המורג,\u0006 כלי הדישה \u0005שלהן]\u0006 יש לקחת את הבהמות אותן הוא רוצה להקדיש, ועתה הוא עומד לעלות לרגל, ואל ידחה את הבאתן.","במשנה הקודמת שנינו שדין ולדות השלמים הריהו כדין השלמים, ומוסיפים כי בדבר זה נחלקו חכמים, ש\u0003ר' אליעזר אומר: ולד שלמים לא יקרב שלמים,\u0004 אלא יסגרנו במקום שבו לא יינתן לו מזון, וימות (רש\"י). \u0003ו\u0004אילו \u0003חכמים אומרים: יקרב\u0004 כשלמים.","ובהסבר מחלוקתם, \u0003אמר ר' שמעון: לא נחלקו\u0004 ר' אליעזר וחכמים \u0003על\u0004 ה\u0003ולד\u0004 שנולד ל\u0003ולד שלמים, ו\u0004כן \u0003על\u0004 ה\u0003ולד\u0004 שנולד ל\u0003ולד תמורה\u0004 — \u0003ש\u0004לדעת הכל \u0003לא יקרב. על מה נחלקו\u0004 — \u0003על הולד\u0004 של השלמים עצמו, שבזה \u0003ר' אליעזר אמר: לא יקרב, וחכמים אומרים: יקרב.\u0004","ובענין זה \u0003העיד\u0004 (מסרו במסורת מפי רבותיהם) ר' יהושע ור' פפייס על ולד שלמים שיקרב שלמים. אמר ר' פפייס: אני מעיד שהיתה לנו פרה של זבחי \u0003שלמים, ואכלנוה\u0004 מבשרה \u0003ב\u0004חג ה\u0003פסח, ואכלנו\u0004 לאחר מכן את בשר \u0003ולדה\u0004 כקרבן \u0003שלמים בחג\u0004 (ברגל אחר).","שנינו במשנה כי שיטת ר' אליעזר היא שולד שלמים אינו קרב שלמים. ובענין זה \u0003אמר ר' אמי, אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור שיטתו\u0005]\u0006 של \u0003ר' אליעזר?\u0004 — שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בתחילת פרשת השלמים \u0003\"ואם זבח שלמים קרבנו לה'\"\u0004 (ויקרא ג, א). והלשון \u0003\"ואם\"\u0004 שניתן לקוראה \"ואם\" באה להורות: \u0003ולא ולד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' אמי\u0004 בשאלה: \u0003אלא מעתה\u0004 שכך נדרש הכתוב \"אם\", הכתוב \u0003\"אם על תודה יקריבנו\"\u0004 (ויקרא ז, יב), אם כן לכאורה \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יידרש באותו אופן: \u0003\"אם\"\u0004 — \u0003ולא ולד,\u0004 שולד התודה אינו קרב, \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 : \u0003הכי נמי\u0004 \u0005[אכן כך גם כן],\u0006 שלדעת ר' אליעזר אף ולד התודה אינו קרב כקרבן תודה, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בדין התודה: \u0003ולדה\u0004 של התודה, \u0003ותמורתה\u0004 של התודה, \u0003וחילופיה\u0004 (הבהמה המובאת לקרבן תודה במקום קרבן תודה שאבד, ולאחר מכן נמצא אותו קרבן, ועתה שתיהן עומדות לפניו להקרבה), \u0003מנין\u0004 שדינם של כל אלו להקרבה כתודה עצמה? — \u0003תלמוד לומר \"אם על תודה\u0004 יקריבנו\" — והרי זה בא לרבות \u0003מכל מקום\u0004 (כל אופני התודה) שקרבים כתודה!","\u0003אלא אמר ר' חייא בר אבא, אמר ר' יוחנן: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של שיטת \u0003ר' אליעזר\u0004 שאין ולדות השלמים קרבים — אין זה מדין תורה, אלא \u0003גזירה\u0004 שגזרו חכמים על ולדות השלמים שלא יקרבו, וטעם הגזירה: שאם נאמר שהולדות קרבות, יש לחשוש \u0003שמא\u0004 ימתינו הבעלים, וישאירו את האמהות אצלם לזמן רב, עד ש\u0003יגדל מהם עדרים עדרים\u0004 כדי למוכרם לצרכי שלמים.","עוד שנינו במשנה ש\u0003אמר ר' שמעון\u0004 בהסבר מחלוקתם של ר' אליעזר וחכמים ש\u0003לא נחלקו\u0004 על ולד ולד שלמים ועל ולד ולד תמורה שלא יקרב, ועל מה כן נחלקו? — על הולד...\".","ובדברי ר' שמעון אלה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005],\u0006 \u0003היכי תני\u0004 \u0005[איך\u0006 בדיוק \u0005שנויים\u0006 הדברים\u0005],\u0006 האם יש לשנות בהם \u0003\"לא נחלקו\u0004 ר' אליעזר וחכמים בכלל אם יקרבו או \u0003שלא יקרבו\u0004 ולדות הולדות, \u0003אלא\u0004 לדעת הכל (ואף ר' אליעזר מודה בכך) \u0003יקרבו\", או דילמא\u0004 \u0005[שמא],\u0006 כך יש לשנות: \u0003\"לא נחלקו\u0004 ר' אליעזר וחכמים בולדות ולדות אלה \u0003ש\u0004לדעת מי מהם \u0003יקרבו,\u0004 \u0003אלא\u0004 לדעת הכל (ואף לדעת חכמים) \u0003לא יקרבו\"?\u0004","\u0003אמר רבה: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר שכך הוא נוסח הדברים: \u0003\"לא נחלקו\u0004 בולדות ולדות \u0003שלא יקרבו, אלא\u0004 לדעת הכל \u0003יקרבו\". מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן \u0003עד כאן לא\u0004 שמענו כי \u0003פליג\u0004 \u0005[חלק]\u0006 \u0003ר' אליעזר עליה דרבנן\u0004 \u0005[על חכמים]\u0006 ואמר שלא יקרבו \u0003אלא בולד\u0004 עצמו, \u0003אבל ולד ולד\u0004 — לא אסר ר' אליעזר להקריבו, שכן \u0003אקראי בעלמא\u0004 \u0005[\u0006דבר \u0005מזדמן סתם]\u0006 \u0003הוא,\u0004 שאין זה דבר מצוי שישהו אותם עד שיהיו להם ולדי ולדות.","\u0003ו\u0004אילו \u0003ר' יהושע בן לוי אמר:\u0004 נוסח המשנה הוא \u0003\"לא נחלקו\u0004 בולדות ולדות \u0003שיקרבו, אלא\u0004 לדעת הכל \u0003לא יקרבו\". מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חולקים חכמים על]\u0006 \u0003ר' אליעזר\u0004 ואומרים שיקרבו, \u0003אלא בולד\u0004 השלמים, \u0003אבל ולד ולד\u0004 — \u0003מתוך מעשיה\u0004 (התוצאה של מה שעשה בה, שהשהה אותה) \u0003ניכרת מחשבתו\u0004 ש\u0003לגדל קא בעי ליה\u0004 \u0005[הוא רוצה אותו]\u0006 ולכן לא יקריבו, כדי שלא יגדלו מלכתחילה לשם כך."],["\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 מדרש חכמים, שיש בו \u0003לסיועי\u0004 \u0005[לסייע]\u0006 \u0003ל\u0004שיטת \u0003ר' יהושע בן לוי,\u0004 שהכל סבורים, שאין ולדות ולדות השלמים קרבים, שכך נדרש המקרא בפרשת השלמים: \u0003\"אם כשב הוא מקריב\u0004 את קרבנו והקריב אותו...\" (ויקרא ג, ז), ויש בכתוב זה שני מיעוטים: \"כשב\" משמעו ולד, ולא ולד הולד, ולכן דווקא \u0003ולד ראשון\u0004 (ולד השלמים עצמם) — \u0003קרב,\u0004 ואילו \u0003ולד שני\u0004 (ולד הולד) — \u0003אינו קרב.\u0004","ועוד, מאחר ובפסוק זה עוסקים בענין השלמים, מכאן שדווקא \u0003הוא\u0004 (ולד השלמים) — \u0003קרב, ואין ולד כל הקדשים קרב.\u0004 הרי שאף מי שסבור שולדות השלמים קרבים (חכמים), מסכים שאין ולדות הולדות קרבים.","ומבררים את המיעוט השני ששנינו במדרש חכמים זה, שדווקא הוא קרב ואין ולד כל הקדשים קרב: ב\u0003ולד דמאי\u0004 \u0005[של מה,\u0006 של איזה קדשים\u0005]\u0006 מדובר? \u0003אי\u0004 \u0005[אם]\u0006 בולד של \u0003עולה ואשם\u0004 — אין זה יכול להיות, שהרי קרבנות אלה \u0003זכרים הם, ולא\u0004 יתכן ש\u0003בני ולד הם. אי\u0004 \u0005[אם]\u0006 מדובר בולד של \u0003חטאת\u0004 — \u0003הילכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005למודה היא]\u0006 ש\u0003למיתה\u0004 היא \u0003אזלא\u0004 \u0005[הולכת],\u0006 ולא להקרבה!","\u0003אמר רבינא:\u0004 יש לתרץ כי בא הכתוב \u0003לאיתויי\u0004 \u0005[להביא]\u0006 במיעוט שאין ולדות שאר הקדשים קרבים, את \u0003ולד\u0004 הבהמה \u0003המעושרת\u0004 (קרבן מעשר בהמה) שלאחר שנתקדשה ילדה, ובא הכתוב ללמד שהולד אינו קרב. ושואלים: דין זה של \u0003ולד המעושרת\u0004 שאינו קרב, \u0003למה לי קרא\u0004 \u0005[פסוק],\u0006 והרי מגזירה שווה \u0003\"עברה\"\u0004 האמור במעשר בהמה (\"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי יהיה קודש לה'\", ויקרא כז, לב), \u0003\"עברה\" מ\u0004תוך האמור ב\u0003בכור\u0004 (\"והעברת כל פטר רחם לה' וכל פטר שגר בהמה אשר יהיה לך הזכרים לה'\", שמות יג, יב) שולדו אינו קרב, \u0003קא גמר לה\u0004 \u0005[הוא נלמד לו]!\u0006","ומשיבים: \u0003אצטריך\u0004 \u0005[נצרך]\u0006 לימוד זה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי מאחר וכלל בדרכי הלימוד הוא, ש\u0003אין דנין\u0004 (למדים בהיקש) את דינו של מי ש\u0003אפשר\u0004 שתהיה בו מציאות מסויימת (כגון ולד הנולד לבהמת מעשר) \u0003מ\u0004זה \u0003שאי אפשר\u0004 שתהיה בו אותה מציאות (כגון בכור, שאין בו לידה, שהרי אין בכור אלא זכר), ואין אם כן ללמוד אחד מהשני, משום כך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הכתוב \u0005משמיע לנו]\u0006 מיעוט זה בדינו של ולד מעשר בהמה.","שנינו במשנה ש\u0003העיד ר' שמעון ור' פפייס\u0004 על ולד שלמים שהוא קרב כשלמים. והוסיף ואמר ר' פפייס בעדותו שהיתה להם פרה שנאכלה כזבחי שלמים בחג הפסח ואילו ולדה נאכל כשלמים ברגל אחר (\"בחג\").","\u0003ו\u0004שואלים: \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר\u0004 בדין ה\u0003קדשים: כיון שעבר עליהם\u0004 לאחר שהקדישום \u0003רגל אחד,\u0004 ולא הביאום בעליהם למקדש — \u0003כל יום ויום עובר עליהם ב\u0004איסור \u0003\"בל תאחר\"\u0004 (\"כי תדור נדר לה' אלהיך לא תאחר לשלמו\", דברים כג, כב), אם כן כבר \u0003מעצרת\u0004 (חג השבועות) \u0003בעי מיכליה\u0004 \u0005[צריך לאוכלו]\u0006 את ולד השלמים שקרבו בפסח, ומדוע המתינו עד חג הסוכות (המכונה כרגיל \"חג\")? \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 בתשובה: מדובר במקרה שנאנס, ולא יכול היה להקריבו בעצרת, ו\u0003כגון שהיה\u0004 ולד הקרבן \u0003חולה בעצרת.\u0004","\u0003רב אשי אמר\u0004 תירוץ אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חג\" נמי דקתני\u0004 \u0005[גם כן ששנינו]\u0006 במשנתנו בעדותו של ר' פפייס? — \u0003חג שבועות,\u0004 ולא חג הסוכות. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רבא\u0005],\u0006 שלא פירש כן את דברי ר' פפייס, והוכרח לפרש את דבריו במקרה של מי שחלה, מדוע לא פירש כרב אשי? ומשיבים: \u0003כל היכי דקתני\u0004 \u0005[היכן,\u0006 מקום \u0005ששונה\u0006 התנא\u0005]\u0006 במשנה \u0003\"פסח\",\u0004 והוא מציין גם את חג השבועות בדבריו, הריהו \u0003תני\u0004 \u0005[שונה]\u0006 את השם \u0003\"עצרת\"\u0004 כשמו של חג השבועות, ולא את השם \"חג\".","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלא הובא ולד השלמים בחג השבועות, אלא רק בחג הסוכות, משום שהבהמה היתה חולה (כהסברו של רבא), או שאכן הביאוהו בחג השבועות (כהסברו של רב אשי), \u0003מאי אסהדותיה\u0004 \u0005[\u0006לשם \u0005מה\u0006 באה \u0005העדות]\u0006 של ר' פפייס? ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 \u0003מ\u0004שיטת \u0003ר' אליעזר\u0004 ש\u0003אמר ולד שלמים לא יקרב שלמים,\u0004 לכך \u0003קמסהיד\u0004 \u0005[מעיד]\u0006 \u0003הוא\u0004 ש\u0003קרב\u0004 ולד השלמים, ושאף נהגו כך למעשה.","ועוד בדין ולדות הקרבנות. ה\u0003ולד\u0004 הנולד לבהמה שהיא קרבן \u0003תודה, ו\u0004כן בהמת חולין שהיא \u0003תמורתה\u0004 של בהמת קרבן תודה, וכן \u0003ולדן\u0004 של אלו, ואף \u0003ולד ולדן עד סוף כל הדורות\u0004 — \u0003הרי אלו\u0004 דינם \u0003כתודה\u0004 עצמה, לדיני ההקרבה, \u0003ובלבד\u0004 (מלבד) הלכה זו: \u0003שאין\u0004 אלו \u0003טעונין\u0004 (חייבים בהבאת) \u0003לחם\u0004 הבא עם התודה כתודה עצמה.","שנינו בסוף המשנה שולד ותמורת התודה אינם חייבים בהבאת לחם עם הקרבתם, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על האמור בפרשת התודה \"אם על תודה יקריבנו והקריב על זבח התודה חלות מצות בלולות בשמן ורקיקי מצות משוחים בשמן....\" (ויקרא ז, יב), \u0003מהו אומר\u0004 (מה מלמדנו הכתוב) \"תודה \u0003יקריבנו\"?\u0004","עניינו של זה — ה\u0003מפריש\u0004 בהמה לקרבן \u0003תודה, ואבדה,\u0004 ועמד \u0003והפריש\u0004 לקרבנו בהמה \u0003אחרת תחתיה, ו\u0004לאחר מכן \u0003נמצאת\u0004 הבהמה \u0003הראשונה, ו\u0004עתה \u0003הרי שתיהן עומדות\u0004 לפניו להקרבה. \u0003מנין שאיזו\u0004 משתיהן \u0003שירצה\u0004 בה להקרבה, ש\u0003יקריב\u0004 אותה \u0003ולחמה עמה?\u0004 \u0003תלמוד לומר\u0004 (מלמדנו הכתוב): \u0003\"תודה יקריב\"\u0004 — ללמד, שכל תודה שהיא, בין הראשונה בין השניה, רשאי הוא להקריבה.","ושואלים עוד: \u0003יכול תהא\u0004 אף התודה ה\u0003שניה טעונה לחם?\u0004 — לכך \u0003תלמוד לומר\u0004 בלשון המסייגת \"יקריבנו\" — דווקא \u0003אחת\u0004 באה עם לחם, \u0003ולא שתים.\u0004 ועוד: \u0003מנין לרבות\u0004 אף את ה\u0003ולדות תמורות וחליפות\u0004 (שאבדה התודה הראשונה, והפריש בהמה אחרת במקומה, ולאחר מכן נמצאה הבהמה הראשונה)? — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב): \u0003\"ואם על תודה\"\u0004 — שכולן קרבות כתודה. \u0003יכול יהו כולן טעונות לחם?\u0004 — \u0003תלמוד לומר: \"על זבח התודה\"\u0004 — רק ה\u0003תודה\u0004 עצמה \u0003טעונה לחם, ולא ולדה ותמורתה וחליפתה טעונה לחם.\u0004","בהמת חולין (זכר) שהיא \u0003תמורת\u0004 בהמת \u0003עולה,\u0004 וכן \u0003ולד\u0004 בהמת ה\u0003תמורה\u0004 (אם המיר בהמת חולין נקבה בבהמת עולה וילדה זו זכר), ואף \u0003ולד ולד ולדה\u0004 של תמורת העולה, \u0003עד סוף כל\u0004 דורות \u0003העולם\u0004 — \u0003הרי אלו\u0004 דינם \u0003כעולה\u0004 עצמה, \u0003וטעונין\u0004 (חייבים) בכל דיני הקרבת העולה: \u0003הפשט\u0004 העור \u0003וניתוח\u0004 הבשר \u0003וכליל לאשים\u0004 (שריפת כולה על אש המזבח). \u0003המפריש\u0004 בהמה ממין \u0003נקבה ל\u0004קרבן \u0003עולה\u0004 (וקרבן עולה בא רק מן הזכרים), \u0003ו\u0004אם \u0003ילדה\u0004 אותה בהמה \u0003זכר\u0004 — הרי דינו של זה, אף שהוא זכר (וזכר עולה לקרבן עולה), ש\u0003ירעה עד שיסתאב\u0004 (יפול בו מום), \u0003וימכר, ויביא בדמיו עולה. ר' אליעזר אומר: הוא\u0004 (הולד) \u0003עצמו יקרב עולה.\u0004","שנינו בתחילת המשנה כי ולד תמורת עולה הריהו קרב כעולה, ואילו בסופה נחלקו חכמים ור' אליעזר בדינו של ולד בהמה נקיבה שהוקדשה לעולה, ושואלים: \u0003מאי שנא רישא דלא פליגי\u0004 \u0005[מה שונה תחילת\u0006 המשנה, \u0005שלא נחלקו\u0006 בה חכמים ור' אליעזר\u0005],\u0006 והכל מודים שקרב, \u0003ומאי שנא סיפא דפליגי\u0004 \u0005[ובמה שונה סוף\u0006 המשנה, \u0005שנחלקו\u0006 בה\u0005]?\u0006","\u0003אמר רבה בר בר חנה:\u0004 אף במקרה המתואר בתחילת המשנה, \u0003במחלוקת\u0004 היא \u0003שנויה\u0004 בין חכמים לר' אליעזר, \u0003ו\u0004הדעה המובאת במשנתנו שיטת \u0003ר' אליעזר היא. ורבא אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 כי כשיטת \u0005חכמים\u0006 היא תחילת משנתנו\u0005],\u0006 ואולם יש לומר כי \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי עליה\u0004 \u0005[נחלקו עליו]\u0006 על \u0003ר' אליעזר אלא\u0004 דווקא \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 ה\u0003מפריש נקבה לעולה\u0004 שלדעתם אין הולד קרב, משום \u0003דאימיה\u0004 \u0005[שאמו]\u0006 עצמה \u0003לא קריבה. אבל\u0004 במקרה של ולד \u0003תמורה\u0004 — כיון \u0003דאימיה נמי\u0004 \u0005[שאמו,\u0006 (כלומר, מקור קדושת אמו, העולה המקורית שאותה המירו על אמו שהיתה זכר) \u0005גם כן]\u0006 \u0003קריבה, אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שהולד עצמו יקרב.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אליעזר\u0004 ש\u0003יקרב עולה הוא עצמו? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מן האמור במשנה להלן כ,ב, ששנינו: בהמת חולין (בין זכר ובין נקיבה) שהיא \u0003תמורת\u0004 קרבן \u0003אשם,\u0004 וכן \u0003ולד\u0004 בהמה (נקיבה) \u0003תמורה\u0004 של קרבן אשם, וכן \u0003ולדן\u0004 ו\u0003ולד ולדן עד סוף כל\u0004 דורות \u0003העולם\u0004 — דינם ש\u0003ירעו עד שיסתאבו, וימכר, ויפלו\u0004 (וימסרו) \u0003דמיו ל\u0004צורך עולות \u0003נדבה\u0004 של הציבור.","\u0003ר' אלעזר אומר: ימותו. ר' אליעזר אומר:\u0004 אין דמיהם הולכים לצורך נדבת הציבור, אלא הבעלים עצמו של בהמת התמורה \u0003יביא בדמיהן עולה.\u0004 ומתוך דיוק דברי ר' אליעזר נלמד: \u0003בדמים\u0004 המתקבלים ממכירתו של ולד התמורה — \u0003אין\u0004 \u0005[כן]\u0006 יביא קרבן עולה, אבל \u0003הוא\u0004 ולד התמורה עצמו — \u0003לא\u0004 קרב כעולה!","\u0003אמר רב חסדא: ר' אליעזר לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם],\u0006 שכך אמר: \u0003לדידי\u0004 \u0005[לי כשעלצמי]\u0006 — \u0003סבירא לי\u0004 \u0005[אני סבור]\u0006 ש\u0003אפילו\u0004 ה\u0003ולד\u0004 עצמו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003קרבה עולה.\u0004 ואולם \u0003לדידכו דאמריתו\u0004 \u0005[לכם,\u0006 לשיטתכם, \u0005שאומרים אתם]\u0006 שהיא \u0003רועה\u0004 ולכשיפול בה מום תימכר ויביא בדמיה עולה — \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[לפחות]\u0006 ש\u0003מותרות\u0004 (מותר הכסף שנשאר לאחר שקנו באשם עולה) \u0003לנדבת יחיד אזלי\u0004 \u0005[הולכים],\u0006 ולא לנדבת ציבור. \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]\u0006 חכמים בתשובה: \u0003מותרות לנדבת ציבור אזלי\u0004 \u0005[הולכים].\u0006","\u0003רבא אמר\u0004 הסבר אחר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר\u0004 ש\u0003הוא\u0004 הולד \u0003עצמו יקרב עולה\u0004 — \u0003אלא\u0004 דווקא \u0003במפריש נקבה לעולה,\u0004 וילדה, וטעם הדבר: \u0003דאיכא\u0004 \u0005[ש\u0006כן \u0005יש]\u0006 \u0003שם עולה על אמו,\u0004"],["\u0003אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003תמורת ולד אשם,\u0004 כיון \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שם עולה על אמו\u0004 — \u0003מודי\u0004 \u0005[מודה]\u0006 \u0003ר' אליעזר\u0004 ש\u0003בדמיו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יוקרב קרבן עולה, ואולם \u0003הוא עצמו,\u0004 ולד התמורה — \u0003לא קרב\u0004 כעולה.","\u0003איתיביה\u0004 \u0005[הקשה עליו,\u0006 על רבא\u0005]\u0006 \u0003אביי: וכי בעי\u0004 \u0005[והאם מצריך]\u0006 \u0003ר' אליעזר\u0004 שיהיה \u0003שם עולה על אמו\u0004 על מנת שיוקרב הולד כעולה, \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפריש נקבה ל\u0004קרבן \u0003פסחו\u0004 (ואין קרבן הפסח בא אלא מן הזכרים), מה דינו? — \u0003ירעה עד שיסתאב\u0004 (יפול בו מום), \u0003ותמכר, ויביא בדמיה\u0004 קרבן \u0003פסח.\u0004 ואם \u0003ילדה\u0004 בהמה זו זכר — אין הולד קרב כקרבן הפסח אף שהוא זכר, אלא אף דינו ש\u0003ירעה עד שיסתאב, וימכר, ויביא בדמיו\u0004 קרבן \u0003פסח.\u0004","ואם בהמה זו \u0003נשתיירה\u0004 (נשארה ללא מום) עד ל\u0003אחר הפסח\u0004 — דינה הוא ש\u0003תרעה עד שיסתאב, ויביא בדמיה שלמים.\u0004 ואם \u0003ילדה\u0004 לאחר הפסח זכר — אף הוא דינו ש\u0003ירעה עד שיסתאב, וימכר, ויביא בדמיו שלמים.\u0004 ואילו \u0003ר' אליעזר\u0004 חולק על כך ו\u0003אומר: הוא,\u0004 הולד \u0003עצמו,\u0004 ולא דמיו, \u0003יקרב בשלמים.\u0004","ומעתה יש לשאול: והא הכא \u0005[והרי כאן\u0006, במקרה זה\u0005],\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שם שלמים על אמו,\u0004 שהרי לא הוקדשה אלא לשם קרבן פסח, \u0003ו\u0004בכל זאת \u0003אמר ר' אלעזר\u0004 שהולד \u0003יקרב שלמים! אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי בתשובה: וכי מדברי \u0003ר' אלעזר\u0004 בדינו של קרבן זה ל\u0003אחר הפסח קא אמרת\u0004 \u0005[אתה אומר]\u0006 לסתור את הסברי?! \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא דינו של קרבן הפסח ל\u0003אחר הפסח\u0004 — שכן \u0003מותר פסח\u0004 (קרבן הפסח שנותר בלא שהקריבוהו) \u0003גופיה\u0004 \u0005[עצמו]\u0006 \u0003קרב שלמים,\u0004 ואף בהמה נקיבה זו, שם שלמים עליה לאחר הפסח.","חזר ושאל אביי את רבא: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שטעם הדבר שקרב הולד לשיטת ר' אליעזר משום ששם שלמים על אמו, \u0003ניפלוג נמי ברישא\u0004 \u0005[שיחלקו גם כן\u0006 ר' אליעזר וחכמים \u0005בתחילת\u0006 הברייתא, במקרה שילדה לפני הפסח\u0005],\u0006 שלדעת חכמים דין הולד לרעייה, ולדעת ר' אליעזר הוא עצמו קרב! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי בתשובה: \u0003אין הכי נמי, ופליגי\u0004 \u0005[אכן כך גם כן, וחולקים]\u0006 חכמים ור' אליעזר אף בולד שילדה לפני הפסח.","\u0003אביי אמר\u0004 הסבר אחר, בשיטת ר' אליעזר: במקרה שילדה הבהמה לפני הפסח, \u0003לא פליג מידי\u0004 \u0005[אין חולק בדבר],\u0006 והכל סבורים שאין הולד עצמו קרב, וטעם הדבר: \u0003דגמירי\u0004 \u0005[שלמודים,\u0006 מקובלים במסורת\u0005]\u0006 הלכה זו, כי \u0003למקום שהמותר\u0004 (הקרבן שלא הוקרב בשעתו) \u0003הולך\u0004 — אף \u0003הולד הולך.\u0004 ומעתה נאמר, \u0003לאחר הפסח\u0004 — ש\u0003מותר\u0004 הפסח \u0003קרב שלמים, ולד נמי\u0004 \u0005[גם כן]\u0006 — \u0003קרב שלמים.\u0004","\u0003אבל לפני הפסח,\u0004 שאין זה בכלל \"מותר הפסח\", חלה על הולד קדושת אמו. \u0003אימיה למאי אקדשה\u0004 \u0005[אמו למה הוקדשה]?\u0006 — \u0003לדמי פסח\u0004 (שתימכר, ויקנו בדמיה קרבן פסח) שהרי היא עצמה אינה יכולה להיקרב פסח, שהרי נקבה היא, ואם כן \u0003ולד נמי\u0004 \u0005[גם כן]\u0006 — הריהו קדוש רק \u0003לדמי פסח.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עוקבא בר חמא\u0004 על הסברו זה של אביי: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 כלל זה בשיטת ר' אליעזר, \u0003מדאימיה\u0004 \u0005[מתוך שאמו]\u0006 \u0003לדמי\u0004 פסח, אף ה\u0003ולד נמי\u0004 \u0005[גם כן]\u0006 \u0003לדמי\u0004 פסח? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפריש נקבה לפסח\u0004 — \u0003היא וולדותיה ירעו עד שיסתאבו, וימכרו, ויביא בדמיהם פסח. ר' אליעזר אומר: הוא עצמו יקרב פסח.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן],\u0006 \u0003דאימיה\u0004 \u0005[שאמו]\u0006 הוקדשה \u0003לדמי\u0004 פסח, ובכל זאת \u0003אמר ר' אליעזר\u0004 ש\u0003הוא עצמו קרב פסח, ו\u0004הרי שלדעתו \u0003לא מוקמינן ליה באימיה\u0004 \u0005[אין אנו מעמידים אותו ב\u0006קדושת \u0005אמו]!\u0006","\u0003אמר רבינא:\u0004 אין להקשות מכאן, כיון ש\u0003במפריש בהמה מעוברת עסקינן\u0004 \u0005[עוסקים אנו]\u0006 כאן, ו\u0003ר' אליעזר סבר כר' יוחנן,\u0004 ש\u0003אמר:\u0004 המקדיש בהמה מעוברת לקדושה מסויימת, \u0003אם שיירו\u0004 את העובר שבמעיה לקדושה אחרת — הרי זה \u0003משוייר,\u0004 וקדוש הוא באותה קדושה לה הקדישו משום שלשיטתו \u0003עובר לאו\u0004 \u0005[לא]\u0006 כ\u0003ירך\u0004 (חלק מגוף) \u0003אמו הוא\u0004 נחשב, אלא הם כשתי בהמות נפרדות. \u0003ו\u0004אף כאן \u0003אמו היא\u0004 זו ש\u0003לא קדשה\u0004 \u0005[התקדשה]\u0006 ב\u0003קדושת הגוף\u0004 לקרבן פסח, שכן היא נקבה, וקדשה רק לדמיה. \u0003אבל היא\u0004 (הולד) — \u0003קדשה\u0004 \u0005[התקדשה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר ש\u0003בבהמה מעוברת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 \u0003\"היא וולדותיה\",\u0004 הרי זה מורה שהיא וולדותיה היו בשעת ההקדש. ומסכמים: אכן \u0003שמע מיניה\u0004 \u0005[למד מכאן]\u0006 שכך הוא."],["ודנים עוד בשיטת ר' אליעזר. \u0003אמר ר' יוסי בר' חנינא: ומודה ר' אליעזר\u0004 לחכמים \u0003ב\u0004מקרה של ה\u0003מפריש נקבה לאשם\u0004 (ואין אשם בא אלא מן הזכרים), וילדה זכר, ש\u0003אין בנה קרב אשם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ואין צורך להשמיענו זאת, שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר\u0004 שהולד קרב, \u0003אלא\u0004 דווקא \u0003ב\u0004מקרה של ה\u0003מפריש נקבה לעולה\u0004 וילדה, וטעמו: משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם עולה על אמו,\u0004 (בעולת העוף שקרבה אף נקבה). \u0003אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 ה\u0003מפריש נקבה לאשם, דליכא\u0004 \u0005[שאין]\u0006 \u0005שם אשם על אמו. מובן ש\u0006\u0003אפילו ר' אליעזר מודה דלא\u0004 \u0005[שאינו]\u0006 \u0003קרב אשם!\u0004","ומשיבים: נצרך ר' יוסי בר' חנינא להשמיענו כן, כי \u0003אי לאו דאשמעינן, הוה אמינא\u0004 \u0005[אם לא שהשמיענו, הייתי אומר]:\u0006 \u0003טעמא\u0004 \u0005[טעם]\u0006 שיטתו של \u0003ר' אליעזר\u0004 במפריש נקבה לעולה שהולד קרב לעולה, הוא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום\u0004 ש\u0003שם עולה על אמו, אלא משום דחזי\u0004 \u0005[שראוי]\u0006 ה\u0003ולד להקרבה,\u0004 שהרי ממין זכר הוא, והייתי אומר: \u0003האי נמי, הא חזי\u0004 \u0005[זה,\u0006 הולד הנולד לנקיבה שהופרשה לאשם, \u0005גם כן הרי ראוי]\u0006 \u0003להקרבה,\u0004 שהרי ממין זכר הוא! לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' יוסי בר' חנינא, \u0005משמיע לנו]\u0006 שאין ולד זה קרב אף לשיטת ר' אליעזר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שהשמיענו ר' יוסי בר' חנינא זאת הוא כדי שלא נחשוב שטעמו של ר' אליעזר הוא מפני שהולד ראוי להקרבה, \u0003אדמשמע לן\u0004 \u0005[עד ש\u0006הוא \u0005משמיע לנו]\u0006 ש\u0003אין בנה\u0004 של נקיבה שהופרשה לאשם \u0003קרב אשם, נישמעינן\u0004 \u0005[שישמיענו]\u0006 זאת, ובאופן רחב יותר, ויאמר ש\u0003אין בנה\u0004 של נקיבה שהופרשה לאשם \u0003קרב עולה\u0004 אף שהאם רועה עד שיפול בה מום ונמכרת לצורך לעולה, \u0003ו\u0004נדע מתוך כך שהוא הדין שאין בנה קרב \u0003לאשם\u0004 ומשיבים:","\u0003אי אשמעינן\u0004 \u0005[אם היה משמיענו]\u0006 ר' יוסי בר' חנינא מהי שיטתו של ר' אליעזר במקרה זה לענין קרבן \u0003עולה,\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא ל\u0003עולה הוא דלא קרבה\u0004 \u0005[שלא קרב]\u0006 הולד, וטעם הדבר: משום ש\u0003לא אקדשה\u0004 \u0005[הקדישה]\u0006 \u0003לאמה\u0004 של ולד זה אותה \u0003קדושה\u0004 שלה יוקרב \u0003עוברה,\u0004 שהרי האם הוקדשה לאשם, והולד אמור להיות מוקרב כעולה. \u0003אבל\u0004 להקריב את הולד לקרבן ל\u0003אשם,\u0004 כאותה קדושה שאף אמו הוקדשה לו — \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 כי ה\u0003ולד קרב אשם,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאינו קרב, אף לשיטת ר' אליעזר.","\u0003המפריש\u0004 בהמה ממין \u0003נקבה ל\u0004קרבן \u0003אשם,\u0004 כיון שאין האשם בא אלא מן הזכרים, מה יעשה? — \u0003תרעה\u0004 הבהמה \u0003עד שתסתאב\u0004 (שיפול בה מום), \u0003ותימכר\u0004 לחולין, \u0003ויביא בדמיה\u0004 קרבן \u0003אשם. ו\u0004אולם \u0003אם\u0004 בתוך זמן זה הפרישו הבעלים אשם אחר וכבר \u0003קרב אשמו,\u0004 ושוב אין הם נזקקים לאשם — \u0003יפלו דמיו\u0004 של אותה נקיבה לאחר שיפול בה מום ותימכר לעולות \u0003נדבה\u0004","\u0003ר' שמעון אומר:\u0004 כיון שאין בהמה נקיבה זו ראויה (מעצם היותה נקיבה) לקרבן אשם, הריהי כבעלת מום, ולא חלה עליה קדושת הגוף מעיקרה, אלא קדושת דמים בלבד, ומשום כך \u0003תימכר\u0004 אף \u0003שלא במום\u0004 (שלא נפל בה מום) ויביא בדמיה קרבן אשם.","שנינו במשנה בדין המפריש נקיבה לאשם, שתרעה הבהמה עד שתסתאב. ושואלים: \u0003ולמה לי\u0004 להמתין במכירתה עד ש\u0003תסתאב? תימכר\u0004 מיד אף בלא מום, שהרי \u0003כיון דלא חזיא למילתא\u0004 \u0005[שאינה ראויה לדבר\u0006 שהוקדשה לו\u0005],\u0006 שהרי היא ממין נקיבה — \u0003היינו מומא\u0004 \u0005[זהו\u0006 כשלעצמו \u0003מום]!\u0004","\u0003אמר רב יהודה, אמר רב\u0004 בתשובה לשאלה זו: \u0003היינו\u0004 \u0005[זהו]\u0006 ה\u0003טעם\u0004 שאינה נמכרת בלא מום, משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו],\u0006 \u0003מיגו דנחתא לה\u0004 \u0005[מתוך שירדה,\u0006 חלה, \u0005עליה]\u0006 \u0003קדושת דמים\u0004 — \u0003נחתא נמי\u0004 \u0005[ירדה,\u0006 חלה, \u0005עליה גם כן]\u0006 \u0003קדושת הגוף,\u0004 ואף שאין היא עצמה קריבה, הועילה לה קדושת הגוף לענין שלא תימכר אלא אם יש בה מום. \u0003אמר רבא:\u0004 עתה שלמדנו שאין הבהמה נמכרת אלא אם נפל בה מום, אף שחלה עליה בתחילתה רק קדושת דמים, \u0003זאת אומרת\u0004 (מכאן נלמד עוד) שאף מי ש\u0003הקדיש\u0004 בהמה ממין \u0003זכר לדמיו,\u0004 שהקדישו על מנת למוכרו ובדמיו יביא קרבן עולה או קרבן אשם — מתוך שחלה עליו קדושת דמים, הריהו אף \u0003קדוש קדושת הגוף,\u0004 וכיון שראוי הוא להקרבה כעולה או כאשם (שהרי זכר הוא) — הריהו קרב.","איתמר \u0005[למדנו],\u0006 שנחלקו חכמים בדין זה ש\u0003הקדיש זכר לדמיו, רב כהנא אמר: קדוש קדושת הגוף,\u0004 ואילו \u0003רבא אמר: אינו קדוש קדושת הגוף. ו\u0004מעירים: \u0003הדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רבא\u0004 משיטתו לשיטת \u0003רב כהנא,\u0004 ואף הוא סבור שקדוש קדושת הגוף, והסיבה שחזר בו רבא — \u0003מ\u0004תוך הדברים ש\u0003רב יהודה\u0004 \u0003אמר\u0004 בשם \u0003רב,\u0004 שמתוך שחלה עליו קדושת דמים — חלה עליו קדושת הגוף.","שנינו במשנתנו כי \u0003ר' שמעון\u0004 חולק על חכמים, ו\u0003אומר\u0004 שהמפריש נקיבה לקרבן אשם, הרי זו \u0003תימכר\u0004 אף \u0003שלא במום,\u0004 שכיון שאינה ראויה לקרבן שהוקדשה לו, הרי זה כשלעצמו מום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חייא בר אבין לר' יוחנן:\u0004 מדוע לא נאמר כי \u0003מיגו דנחתא ליה\u0004 \u0005[מתוך שירדה,\u0006 שחלה \u0005עליה,\u0006 על בהמה נקיבה זו\u0005]\u0006 \u0003קדושת דמים\u0004 — \u0003תיחות ליה נמי\u0004 \u0005[תרד,\u0006 תחול, \u0005עליה גם כן]\u0006 \u0003קדושת הגוף,\u0004 שלא תימכר אלא כשיפול בה מום?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לרב חייא בר אבין בתשובה: \u0003ר' שמעון\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 כשיטתו\u0005],\u0006 שכן \u0003אמר: כל מידי דלא חזי ליה לגופיה\u0004 \u0005[דבר שאינו ראוי לו לגופו,\u0006 להיות קרב בעצמו על המזבח\u0005]\u0006 — \u0003לא נחתא ליה\u0004 \u0005[אין יורדת,\u0006 חלה \u0005עליו]\u0006 \u0003קדושת הגוף. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 בהמה שהוקדשה לקרבן \u0003אשם\u0004 שקרב \u0003בן שנה\u0004 (וכגון אשם נזיר ואשם מצורע), \u0003ו\u0004אולם \u0003הביאו\u0004 בעליו להקרבה כשהוא כבר \u0003בן שתים,\u0004 או לחילופין, בהמה שהוקדשה לקרבן אשם שדינו שהוא קרב \u0003בן שתים\u0004 (וכגון אשם גזילות, אשם מעילות, ואשם שפחה חרופה), ואולם \u0003הביאו\u0004 בעליו להקרבה כשהוא רק \u0003בן שנה\u0004 — הרי זו הקרבה \u0003כשירה, ו\u0004אולם \u0003לא עלו לבעלים לשם חובה,\u0004 שלא נפטרו בכך מחובת אשם שעליהם, ועליהם להביא קרבן אחר כראוי.","ואילו \u0003ר' שמעון\u0004 חולק על חכמים ו\u0003אומר\u0004 שאין זו הקרבה כשירה, כיון ש\u0003כל עצמן\u0004 של קרבנות אלה, מחמת שעבר זמנם או שטרם הגיע זמנם \u0003אינן קדושין.\u0004 הרי ששיטת ר' שמעון שדבר שאינו ראוי להקרבה כשלעצמו, לא חלה עליו קדושת הגוף כלל ועיקר.","ושואלים על שיטת ר' שמעון: \u0003והרי\u0004 המקדיש לקרבן את המוגדר כ\u0003\"מחוסר זמן\"\u0004 (כגון כבש שעדיין לא הגיע יום השמיני ללידתו), \u0003דלא חזי\u0004 \u0005[שאינו ראוי]\u0006 עתה להקרבה, ואמר ר' שמעון שהוא \u0003קדוש\u0004 לענין זה שאם שחטו מחוץ לעזרה הריהו בכלל האיסור לשחוט קדשים בחוץ, והרי אין איסור זה חל אלא על הראויים להיות קרבים על המזבח, וזה אינו ראוי?! ומתרצים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003מחוסר זמן,\u0004 משום \u0003דחזי\u0004 \u0005[שראוי]\u0006 הוא להיות קרב \u0003למחר\u0004 (מאוחר יותר, לכשיגיע זמנו), ולכן אינו נחשב כאינו ראוי.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכל שראוי להיות קרב לכשיגיע זמנו הריהו קדוש בקדושת הגוף, אף \u0003אשם\u0004 הקרב רק כשהוא \u0003בן שתים והביאו\u0004 להקרבה כשהוא עדיין \u0003בן שנה, הא חזי\u0004 \u0005[הרי ראוי]\u0006 הוא להיות קרב \u0003לשנה\u0004 הבאה, כשיהיה בן שתיים, ומדוע לדעת ר' שמעון אין הוא קדוש בקדושת הגוף? \u0003אלא\u0004 \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון במחוסר זמן:\u0004 משום \u0003דיליף ליה\u0004 \u0005[שלומד אותו]\u0006 \u0003מ\u0004דינו של \u0003בכור.\u0004","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אמר משום\u0004 \u0005[בשם]\u0006 \u0005ר' שמעון:\u0006 \u0003מחוסר זמן נכנס לדיר\u0004 יחד עם בהמות שהגיע זמנן \u0003להתעשר\u0004 מעשר בהמה, \u0003והרי הוא\u0004 לענין זה \u0003כבכור, מה בכור\u0004 — הריהו \u0003קדוש לפני זמנו\u0004 (מיד כשנולד, קודם שעברו שבעת ימים), \u0003ו\u0004הריהו \u0003קרב\u0004 רק \u0003לאחר זמנו,\u0004 מיום השמיני והלאה, \u0003אף מחוסר זמן\u0004 — הריהו \u0003קדוש לפני זמנו, וקרב לאחר זמנו.\u0004","ודנים עוד במחלוקת זו שבין חכמים ור' שמעון. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המקדיש נקבה לעולתו\u0004"],["\u0003ו\u0004כן זה המקדיש בהמה נקיבה \u0003לפסחו ו\u0004כן \u0003לאשמו,\u0004 אף שאין קרבנות אלה באים אלא מן הזכרים — חלה עליה קדושת הגוף, ומשום כך הריהי \u0003עושה תמורה.\u0004 שאם המירו עליה בהמת חולין — חלה אותה קדושה על בהמת החולין.","ואילו \u0003ר' שמעון\u0004 חולק על חכמים ו\u0003אומר:\u0004 אין דין כל הקרבנות הללו שווה, שהמקדיש בהמה נקיבה \u0003לעולתו\u0004 — הריהי \u0003עושה תמורה,\u0004 וזאת משום ששם עולה עליה (בעולת העוף שבאה אף מן הנקיבות), ומשום כך הריהי קדושה בקדושת הגוף, ולכן אינה נמכרת אלא לאחר שנפל בה מום. אבל המקדיש בהמה נקיבה \u0003לפסחו\u0004 או \u0003לאשמו,\u0004 שלא חלה עליה קדושת הגוף כלל, והריהי נמכרת כפי שהיא בלא מום — \u0003אין עושה תמורה. ש\u0004כן כלל הוא בדין התמורה:","\u0003אין לך דבר\u0004 (קרבן) ה\u0003עושה תמורה אלא\u0004 רק \u0003ה\u0004בהמה שחלה עליה קדושת הגוף, ואף אם אינה יכולה להיקרב — הריהי \u0003רועה\u0004 עד \u0003להסתאב\u0004 (לנפילת מום), ומשנפל בה מום הריהי נמכרת, וקונים בדמיה אותו קרבן כראוי.","\u0003אמר רבי\u0004 בהכרעת מחלוקת זו בין חכמים לר' שמעון: \u0003אין אני רואה\u0004 (איני מקבל) את \u0003דבריו של ר' שמעון ב\u0004ענין קרבן \u0003פסח,\u0004 שאינה עושה תמורה, וטעם הדבר: \u0003הואיל ומותר הפסח\u0004 (קרבן הפסח שלא הוקרב בשעתו) הריהו \u0003קרב\u0004 לאחר הפסח כקרבן \u0003שלמים.\u0004 וכיון שהשלמים באים מן הנקיבה, אף במקרה זה של המקדיש בהמה נקיבה לפסח, נחשב הדבר כמי ששם שלמים עליה, וחלה עליה קדושת הגוף לענין שאין היא נמכרת בלא מום, ולכן הריהי עושה תמורה.","ומבררים תחילה את דברי רבי: מדוע אמר רבי שאין הוא מקבל את דברי ר' שמעון רק בענין הפסח, \u0003ולימא\u0004 \u0005[ויאמר]\u0006 אף: \u0003אין אני רואה\u0004 את \u0003דבריו של ר' שמעון באשם,\u0004 ובדומה לטעם שאמר בענין הפסח: \u0003הואיל ומותר אשם קרב עולה,\u0004 ונמצא שנקיבה זו שהוקדשה לאשם הריהי עולה, וקדושה קדושת הגוף (שהרי יש חטאת הבאה נקיבה, בעולת העוף), ותעשה תמורה! ומשיבים: \u0003רבי סבר לה כרבנן\u0004 \u0005[הריהו סבור כחכמים],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]: מותרות\u0006 אשם \u0003לנדבת ציבור אזלי\u0004 \u0005[הולכים],\u0006 שקונים בדמיהם עולות ציבור, \u0003ו\u0004מכלל דיני התמורה הוא ש\u0003אין תמורה ב\u0004קרבן ה\u0003צבור.\u0004","ונפנים עתה לבירור דברי ר' שמעון בברייתא: \u0003קא סלקא דעתך\u0004 \u0005[היה עולה על דעתך]\u0006 לומר כי \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 ה\u0003מפריש נקבה לעולתו:\u0004 \u0003משום הכי\u0004 \u0005[כך],\u0006 מטעם זה בהמה זו \u0003עושה תמורה — דהאיכא\u0004 \u0005[שהרי יש]\u0006 \u0003שם עולה עליה, גבי\u0004 \u0005[אצל,\u0006 בדין\u0005]\u0006 \u0003עולת העוף,\u0004 שעולה מן העוף יכולה לבוא אף נקיבה.","\u0003אלא\u0004 שאם כן הוא, מעתה אף \u0003בכהן גדול\u0004 החייב בפר חטאת של יום הכיפורים שהוא זכר, \u0003שהפריש פרה\u0004 נקיבה עבור \u0003פרו\u0004 — \u0003תיקדוש\u0004 \u0005[תתקדש]\u0006 הפרה לענין זה שתעשה תמורה, מאותו הטעם, \u0003דהאיכא\u0004 \u0005[שהרי יש]\u0006 שם חטאת עליה, שכן \u0003פרת חטאת\u0004 (פרה אדומה הנעשית לצורך מי חטאת) הריהי נקיבה! ומשיבים: אין לומר זאת, משום שפרה אדומה עצמה אין קדושתה קדושת הגוף, שהרי אינה קרבה על המזבח במקדש, אלא \u0003קדשי בדק הבית הוא, ו\u0004הלכה היא ש\u0003קדשי בדק הבית לא עבדי\u0004 \u0005[אינם עושים]\u0006 \u0003תמורה.\u0004","ושואלים עוד על שיטת ר' שמעון: \u0003יחיד\u0004 (כל אדם מישראל) \u0003ש\u0004חייב בקרבן חטאת הבאה מן הנקיבה, ועמד ו\u0003הפריש שעיר\u0004 זכר \u0003ל\u0004חיוב זה של \u0003שעירתו\u0004 — \u0003תיקדוש\u0004 \u0005[תתקדש]\u0006 בהמה זו בקדושת הגוף לענין שיעשה תמורה, שכן יש שם חטאת בזכר, \u0003דהאיכא\u0004 \u0005[שהרי יש]\u0006 \u0003שעיר\u0004 חטאת שמביא ה\u0003נשיא\u0004 והוא בא מן הזכר! \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לשאול באופן הפוך: \u0003נשיא ש\u0004חייב בקרבן חטאתו ועמד ו\u0003הפריש שעירה\u0004 נקיבה \u0003ל\u0004שם \u0003שעירו\u0004 — \u0003תיקדוש\u0004 \u0005[תתקדש]\u0006 הבהמה בקדושת הגוף לענין זה שתעשה תמורה, שכן יש שם חטאת עליה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003יחיד מפריש שעירה.\u0004 ובכל אלה היה לר' שמעון לציין שאף הם עושים תמורה!","ומשיבים: אין זה נחשב שם חטאת על שעירת נשיא (משום שיש כמותה ביחיד) וכן בשעיר יחיד (משום שיש שעיר נשיא) כי \u0003הני\u0004 \u0005[אלו]\u0006 נשיא ויחיד מישראל, \u0003תרי גופי נינהו\u0004 \u0005[שני גופים הם],\u0006 ואין שם הקרבן נקרא אלא כשהוא בכלל חיובי אותו אדם עצמו.","ושואלים על כך: אלא מעתה, אם \u0003חטאו\u0004 יחידים מישראל בדבר המחייבם בחטאת \u0003עד שלא\u0004 (בטרם) \u0003נתמנו\u0004 לנשיא, אף שהקרבן הראוי להם הוא שעירה, אם לא הספיק החוטא להפריש שעירה לחטאתו לפני מינויו לנשיא, \u0003כי\u0004 \u0005[כאשר,\u0006 אם\u0005]\u0006 \u0003מפריש\u0004 הוא \u0003שעיר לשעירתו\u0004 משכבר נתמנה לנשיא — \u0003תיקדוש\u0004 \u0005[תתקדש]\u0006 הבהמה בקדושת הגוף לענין זה שתעשה תמורה, שכן יש שם חטאת עליה, ומכלל חיובי אדם אחד הוא, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אילו חטא\u0004 הנשיא הזה \u0003השתא\u0004 \u0005[עכשיו]\u0006 והתחייב חטאת — \u0003בר איתויי\u0004 \u0005[בן הבאת]\u0006 \u0003שעיר הוא!\u0004 ומשיבים: אין זה כך, שכן \u0003הא\u0004 \u0005[הרי]\u0006 אדם זה \u0003לא חטא\u0004 בהיותו נשיא, ומשום כך \u0003לא איחייב\u0004 \u0005[התחייב]\u0006 \u0003בשעיר\u0004 אלא בשעירה.","וחוזרים ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שאין המצב החדש של היותו נשיא נחשב להחיל שם חטאת על היחיד מישראל, \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 תאמר במפריש נקיבה לעולתו שאין כאן שם עולה משום עולת העוף הבאה מן הנקיבה, שכן \u0003הא\u0004 \u0005[הרי]\u0006 סוף סוף לא מצורע עני הוא ו\u0003לאו\u0004 \u0005[לא]\u0006 \u0003עולת העוף קמייתי\u0004 \u0005[הוא מביא]\u0006 עתה, ומדוע מודה ר' שמעון בדבר זה שעושה תמורה?","ומשיבים: אין המדובר בברייתא בעולה הבאה חובה, אלא בעולת נדבה, ו\u0003ר' שמעון סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה\u0004 האומר שכל אדם, ואפילו הוא עשיר, יכול להביא עוף לעולתו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"הרי עלי עולה\"\u0004 בלא שפירש מה הוא מתנדב — \u0003יביא כבש\u0004 זכר לעולתו, שהוא הפחות שבעולות הבהמה. \u0003ר' אלעזר בן עזריה אומר:\u0004 יביא עולת העוף, שהוא \u0003או תור או בני יונה.\u0004","ודנים עוד בדברי ר' שמעון שבברייתא. \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו\u0004 למקדש סתם, והרי זו הקדשה לבדק הבית, \u0003והיה בהן\u0004 בכלל נכסיו \u0003בהמה\u0004 ה\u0003ראויה ל\u0004הקרבה \u0003גבי\u0004 \u0005[אצל,\u0006 על\u0005]\u0006 ה\u0003מזבח,\u0004 והיו בהמות אלה \u0003זכרים ונקבות.\u0004 במקרה זה ברור שכל הראוי למזבח צריך להקריבו, ואולם נחלקו חכמים כיצד מקריבים.","\u0003ר' אליעזר אומר:\u0004 ה\u0003זכרים\u0004 — \u0003ימכרו\u0004 ובדמיהן ישתמשו \u0003לצרכי\u0004 (להקרבת) \u0003עולות, ו\u0004אילו ה\u0003נקבות,\u0004 שאין מביאים מהן לעולה — \u0003ימכרו לצרכי\u0004 זבחי \u0003שלמים\u0004 שיש בהם אף נקבות, \u0003ו\u0004הואיל והוקדשו הבהמות לבדק הבית \u0003דמיהן יפלו עם שאר\u0004 ה\u0003נכסים\u0004 שהקדיש \u0003לבדק הבית.\u0004","\u0003ר' יהושע אומר:\u0004 כל דבר הראוי למזבח, מתכוון האדם המקדישו שיקרב כעולה על המזבח, ולכן, ה\u0003זכרים עצמן\u0004 שבתוך הנכסים שהקדיש — \u0003יקרבו עולות, והנקבות,\u0004 שאין מביאים מהן לעולה — \u0003ימכרו לצרכי\u0004 הקרבתן כקרבנות \u0003שלמים, ויביא\u0004 המקדיש \u0003בדמיהן עולות. ושאר\u0004 ה\u0003נכסים\u0004 שהוקדשו — \u0003יפלו לבדק הבית.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: ל\u0004שיטת \u0003ר' יהושע\u0004 ש\u0003אמר\u0004 שה\u0003זכרים עצמן יקרבו עולות,\u0004 משום שכך היתה כוונת המקדיש, יש לשאול: \u0003ו\u0004ה\u0003נקבות היכי מקרבן\u0004 \u0005[כיצד מקריבים אותן]\u0006 הקונים כקרבנות \u0003שלמים, הא\u0004 \u0005[הרי]\u0006 \u0003מכח קדושה דחוייה קאתיין\u0004 \u0005[הן באות],\u0006 שכן הוקדשו, לשיטת ר' יהושע, לעולות, והלכה היא שנקבה שהופרשה לעולה, אינה קריבה, אלא רועה עד שיפול בה מום, ותימכר!","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003ר' יהושע\u0004 שה\u0003זכרים עצמן יקרבו עולות,\u0004 \u0003למימרא\u0004 \u0005[\u0006נראה \u0005לומר]\u0006 שלשיטתו \u0003קדושת הגוף אקדשינהו\u0004 \u0005[הקדישם],\u0006 ואולם על כך יש לשאול: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שקדושים הם בקדושת הגוף, ה\u0003נקבות אמאי\u0004 \u0005[מדוע]\u0006 \u0003ימכרו לצרכי\u0004 הקרבתן כקרבנות \u0003שלמים\u0004 על ידי הקונה? והרי כיון שהוקדשו לעולות, \u0003בעיא\u0004 \u0005[צריכות]\u0006 הן \u0003רעייה\u0004 עד שיפול בהן מום!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' חייא בר אבא בתשובה לשאלתו: \u0003ר' יהושע סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' שמעון,\u0004 ש\u0003אמר: כל מידי\u0004 \u0005[דבר]\u0006 \u0003דלא חזי ליה לגופיה\u0004 \u0005[שאינו ראוי לו לגופו,\u0006 שיקרב הוא עצמו על המזבח\u0005]\u0006 — \u0003לא נחתא ליה\u0004 \u0005[אין יורדת,\u0006 חלה, \u0005עליו]\u0006 \u0003קדושת הגוף. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 המפריש נקיבה לאשם (והרי אין האשם בא אלא מן הזכרים) — \u0003תמכר\u0004 אף \u0003שלא במום. ואמרינן דטעמא\u0004 \u0005[ואומרים אנו שטעם]\u0006 שיטתו זו של \u0003ר' שמעון\u0004 הוא שמ \u0003כיון דלא חזיא\u0004 \u0005[שאין ראויה]\u0006 \u0003נקבה ל\u0004קרבן \u0003אשם\u0004 — \u0003לא נחתא ליה\u0004 \u0005[אין יורדת,\u0006 חלה \u0005עליו]\u0006 \u0003קדושת הגוף.\u0004","הקשה ר' חייא בר אבא על תשובתו זו של ר' יוחנן: אין להביא ראיה מדינו זה של ר' שמעון לשיטת ר' יהושע, שכן \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר\u0004 כן \u0003ר' שמעון\u0004 את שיטתו זו דווקא \u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 המקדיש \u0003נקבה לאשם\u0004 —"],["\u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שם אשם על אמו,\u0004 שאין אשם בא כלל מן הנקיבה. \u0003אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 המפריש \u0003נקבה לעולה\u0004 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם עולה על אמו\u0004 (בעולת העוף), \u0003אפילו ר' שמעון מודה\u0004 שחלה קדושת הגוף על הנקבות לענין זה שלא ימכרו לצורך שלמים, שכן מכח קדושה דחויה הן באות!","\u0003ועוד\u0004 יש להקשות על הסברו זה של ר' יוחנן: \u0003הא שמעינן ליה\u0004 \u0005[הרי שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 שסבור שהמפריש נקבה \u0003לעולתו\u0004 הריהי \u0003עושה תמורה,\u0004 הרי איפוא שחלה עליה קדושת הגוף לענין זה, ולפיכך כן תיחשב הנקיבה כמי שבאה מכח קדושה דחויה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' חייא בר אבא בתשובה: כוונתי היתה ש\u0003ר' יהושע סבר ליה כאידך תנא אליבא\u0004 \u0005[הריהו סבור כ\u0006דעת \u0005התנא האחר בשיטת]\u0006 \u0005ר' שמעון.\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון: אף\u0004 המקדיש נקבה \u0003לעולתו אין עושה תמורה.\u0004 שאף ששם עולה עליה, לא חלה עליה קדושת הגוף, ומשום כך תמכרנה הנקבות לצורך הקרבתן כשלמים, ואינן שלמים הבאים מכח קדושה דחויה.","בהמה שהיא \u0003תמורת\u0004 קרבן \u0003אשם,\u0004 וכן \u0003ולד\u0004 ה\u0003תמורה,\u0004 וכן \u0003ולדן\u0004 ו\u0003ולד ולדן עד סוף כל\u0004 דורות \u0003העולם\u0004 — הרי אלו \u0003ירעו עד שיסתאבו\u0004 (שיפול בהם מום הפוסל מהקרבה), \u0003וימכרו, ויפלו דמיו ל\u0004קופת המקדש, שממנה מביאים עולות \u0003נדבה\u0004 של ציבור. ר' אליעזר \u0003אומר:\u0004 אין אלה הולכים לרעייה, אלא \u0003ימותו. ור' אליעזר\u0004 (אלעזר. ראה גרסות) \u0003אומר:\u0004 אין מביאים בדמיהם עולות ציבור של נדבה, אלא הבעלים הוא ש\u0003יביא בדמיה עולות\u0004 יחיד.","ועוד נחלקו חכמים אלה בדין קרבן ה\u0003אשם שמתו בעליו\u0004 לפני שקרב והתכפרו בו, \u0003ו\u0004כן בדין קרבן האשם \u0003שכיפרו בעליו\u0004 (וכגון שאבד הקרבן הראשון, והפרישו הבעלים קרבן אחר והקריבוהו והתכפרו בו, ולאחר מכן נמצא הקרבן הראשון) — הרי אלו \u0003ירעו עד שיסתאבו, וימכרו, ויפלו דמיו לנדבה.\u0004 ואף באלו \u0003ר' אליעזר אומר: ימותו,\u0004 ו\u0003ר' אלעזר אומר: יביא\u0004 הוא עצמו \u0003בדמיה עולה.\u0004","ודנים בדברי חכמים ור' אלעזר: \u0003והלא אף\u0004 לדעת חכמים הקרבן הבא ממעות ה\u0003נדבה\u0004 \u0003עולה היא, ו\u0004אם כן \u0003מה\u0004 ההבדל \u0003בין דברי ר' אליעזר\u0004 (ר' אלעזר) האומר שיביא בדמיהם עולה \u0003לדברי חכמים? אלא\u0004 יש לומר שאין חכמים ור' אליעזר (ר' אלעזר) עוסקים באותו קרבן. שעולה המוזכרת בדברי חכמים היא עולת ציבור ואילו זו המוזכרת בדברי ר' אליעזר היא עולת יחיד. ובין שתיהן כמה הבדלים: עולת היחיד \u0003בזמן שהיא באה\u0004 כקרבן \u0003עולה\u0004 — הרי הבעלים \u0003סומך\u0004 בידיו \u0003עליה\u0004 לפני שנשחטת. \u0003ו\u0004כן \u0003מביא נסכים\u0004 (יין ומנחה) עם הקרבן, \u0003ונסכיה\u0004 באים \u0003משלו\u0004 (מממונו). ו\u0003אם היה\u0004 הבעלים \u0003כהן\u0004 — \u0003עבודתה ועורה\u0004 של העולה הריהן \u0003שלו. ו\u0004לעומת זאת,","\u0003בזמן שהיא\u0004 עולת ציבור של \u0003נדבה\u0004 — בעל אותו קרבן שנמכר \u0003אינו סומך עליה,\u0004 שהרי של ציבור היא, ואין סמיכה בקרבנות ציבור. \u0003ו\u0004כן הוא עצמו \u0003אינו מביא עליה נסכים,\u0004 ואולם יש לה נסכים \u0003ונסכיה\u0004 באים \u0003משל ציבור.\u0004 ואף על פי שהוא כהן — אין הוא זוכה ב\u0003עבודתה ו\u0004ב\u0003עורה,\u0004 אלא \u0003משל אנשי משמר\u0004 (של הכהנים העובדים בבית המקדש באותו שבוע) הם.","שנינו בתחילת המשנה שנחלקו חכמים ור' אליעזר בדינם של תמורת אשם וולד התמורה, ושנינו עוד בהמשך המשנה שנחלקו חכמים ור' אליעזר בדיני אשם שמתו בעליו ואשם שהתכפרו בעליו באחר, \u0003ו\u0004מסבירים מה טעם \u0003צריכא\u0004 \u0005[צריך]\u0006 שתאמרנה שתיהן:","\u0003דאי אשמעינן\u0004 \u0005[ש\u0006כן \u0005אם היה\u0006 התנא במשנתנו \u0005משמיענו]\u0006 רק את מחלוקתם בדינו של \u0003אשם\u0004 שהתכפרו בעליו באחר — הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזה הוא\u0006 ש\u0005אמר]\u0006 \u0003ר' אליעזר\u0004 ש\u0003ימותו, משום\u0004 ש\u0003גזר\u0004 באשם זה ש\u0003לאחר כפרה, אטו\u0004 \u0005[משום]\u0006 אשם ש\u0003לפני כפרה.\u0004 שאם היה נקבע דינו שיביאו בדמיו עולות, היו טועים ואומרים שגם לפני כפרה כגון שאבד אשם, והופרש אשם אחר, ונמצא האשם שאבד, ונשלח אחד מהם לרעייה ונפל בו מום, דינו שמביאים בדמיו עולות, אף שהוא לפני כפרה. ואין הדין כן, כי כאשר לא הוקרב האשם השני, דינו שיביאו בדמיו של זה שרעה קרבן אשם.","אבל גבי \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003תמורת אשם\u0004 ובענין \u0003ולד תמורתה,\u0004 שאין מקום לגזירה זו (שהרי הם הולכים לרעיה בכל אופן, אף שלא נתכפר עדיין הבעלים באחר) — \u0003אימא מודי להו לרבנן\u0004 \u0005[אמור\u0006 שר' אליעזר \u0005מודה להם לחכמים]\u0006 שדינם של אלו לרעיה.","\u0003ו\u0004מן הצד האחר, \u0003אי אשמעינן התם\u0004 \u0005[אם היה משמיע לנו\u0006 התנא במשנתנו רק \u0005שם]\u0006 בדינם של תמורת אשם וולד התמורה — הייתי אומר כי דווקא \u0003בהא קאמרי רבנן\u0004 \u0005[בזה אומרים חכמים]\u0006 שדינם לרעיה, משום שאין בהם מקום לגזירה, \u0003אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 \u0003אשם\u0004 שהתכפרו בעליו באחר שיש מקום לגזירה, כאמור — היה מקום לומר כי \u0003מודו ליה\u0004 \u0005[מודים\u0006 חכמים \u0005לו]\u0006 \u0003לר' אליעזר.\u0004 לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתאמרנה שתיהן.","ועוד במחלוקת שבין ר' אליעזר וחכמים בענין ולד התמורה. \u0003אמר רב נחמן, אמר רבה בר אבוה: מחלוקת\u0004 זו בדינו של ולד התמורה, הריהי דווקא \u0003לאחר כפרה,\u0004 שהוקרב כבר קרבן האשם עצמו. \u0003אבל לפני כפרה,\u0004 כשעומדים שניהם, ההקדש והתמורה, לפני הבעלים — ל\u0003דברי הכל\u0004 אף \u0003הוא\u0004 הולד \u0003עצמו יקרב\u0004 \u0003אשם,\u0004 אם רוצה בכך הבעלים.","\u0003אמר רבא: שתי תשובות\u0004 (פירכות) יש \u0003בדבר, חדא\u0004 \u0005[אחת],\u0006 ש\u0003אין אדם מתכפר בדבר הבא בעבירה.\u0004 והרי עובר זה בא מן העבירה (אימו, התמורה, שעבר בה על \"לא ימיר\"). \u0003ועוד, התני\u0004 \u0005[הרי שנה]\u0006 \u0003רב חנניא\u0004 ברייתא שיש בה \u0003לסיועי\u0004 \u0005[לסייע]\u0006 \u0003ל\u0004שיטתו של \u0003ר' יהושע בן לוי\u0004 ש\u0003אמר\u0004 כי דווקא \u0003ולד ראשון\u0004 של שלמים הוא ש\u0003קרב,\u0004 אבל \u0003ולד שני\u0004 (ולדו של הולד) — \u0003אינו קרב.\u0004 ואף ולד התמורה, הריהו כעין \"ולד שני\", שכן הריהו כדור שלישי מהקרבן המקורי!","\u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003אמר רב נחמן,\u0004 \u0003אמר רבה בר אבוה: מחלוקת\u0004 חכמים ור' אליעזר הריהי דווקא \u0003קודם כפרה,\u0004 שלדעת ר' אליעזר דינו למיתה, שכן יש חשש שיבואו להקריבו כאשם. ולדעת חכמים דינו לרעיה, שאין חוששים שיבואו להקריבו כאשם. \u0003אבל לאחר כפרה\u0004 שהקריבו את האשם המקורי — שוב אין מקום לחשוש שיקריבוהו כאשם, ולדברי הכל \u0003הוא עצמו קרב עולה.\u0004","ושואלים על כך: כיצד מקריבים את ולד התמורה, \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב חנניא\u0004 ברייתא שיש בה \u0003לסיועי\u0004 \u0005[לסייע]\u0006 \u0003ל\u0004שיטת \u0003ר' יהושע בן לוי\u0004 שאין מקריבים \"ולד שני\", ואף כאן אין להקריב את ולד התמורה, שכ\"ולד שני\" הוא! ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אבין בר חייא מר' אבין בר כהנא: הפריש\u0004 בהמה \u0003נקבה ל\u0004קרבן \u0003אשם\u0004 (ואשם בא רק מן הזכרים), וילדה זכר, \u0003בנה\u0004 זה \u0003מהו שיקרב לעולה?\u0004 ושואלים על עצם השאלה: מדוע שאל כן ר' אבין בר חייא, \u0003ו\u0004הרי \u0003תיפשוט ליה\u0004 \u0005[תיפתר לו]\u0006 בעיה זו \u0003מ\u0004דבריו של \u0003ר' יוסי בר' חנינא,\u0004 ש\u0003אמר\u0004 כי \u0003מודה ר' אליעזר\u0004 (ר' אלעזר) במפריש נקיבה לאשם שאין בנה קרב כקרבן אשם, שאין שם אשם על אמו, והוא הדין שאינו קרב עולה שאין שם עולה על אמו שהרי הופרשה לאשם! ומשיבים: ר' אבין בר חייא \u0003לא שמיע ליה\u0004 \u0005[לא שמע אותו,\u0006 אין דברי ר' יוסי בר' חנינא הללו נראים לו\u0005].\u0006","וחוזרים לשאלת ר' אבין בר חייא: \u0003מאי\u0004 \u0005[מה]\u0006 יהא אכן הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבין בר כהנא לר' אבין בר חייא בתשובה: \u0003בנה קרב עולה.\u0004 הקשה ר' אבין בר חייא לר' אבין בר כהנא על קביעתו זו: \u0003האי מאי\u0004 \u0005[זה\u0006 הדין \u0005מה\u0006 עניינו\u0005]?\u0006 שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר\u0004 (ר' אלעזר) במשנה (לעיל יח, ב) שהולד עצמו קרב עולה, \u0003אלא\u0004 דווקא ב\u0003מפריש נקבה לעולה\u0004 וילדה — וטעם הדבר: משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם עולה על אמו, אבל גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 המפריש נקבה ל\u0003אשם,\u0004 וילדה, \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שם עולה על אמו,\u0004 שתחילת ההקדש לא היתה לשם עולה, אלא אשם (תוס') — \u0003אפילו ר' אליעזר\u0004 (ר' אלעזר) \u0003מודה\u0004 שאין הולד קרב כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבין בר כהנא בתשובה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר\u0004 (ר' אלעזר) בדין בנה של נקיבה שהופרשה לעולה שקרב הוא עצמו לעולה, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום\u0004 ש\u0003שם עולה על אמו, אלא משום דחזי\u0004 \u0005[שראוי]\u0006 \u0003להקרבה\u0004 — \u0003והא נמי חזי\u0004 \u0005[וזה,\u0006 בנה של הנקיבה שהופרשה לאשם, \u0005גם כן ראוי]\u0006 \u0003להקרבה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד ר' אבין בר חייא ממה ששנינו במשנתנו בדין \u0003ולדן\u0004 של הנקיבה שהופרשה לאשם, או של תמורת אשם, וכן \u0003ולד ולדן עד סוף כל\u0004 דורות \u0003העולם\u0004 — \u0003יביא בדמיהן עולה.\u0004 ויש לדייק: דווקא \u0003בדמיהן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יביא עולה,"],["אבל הוא, הולד \u0003עצמו\u0004 — \u0003לא\u0004 יקרב עולה! השיב ר' אבין בר כהנא: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]?\u0006 במקרה \u0003כגון ש\u0004הנקבה שהופרשה לאשם או תמורת האשם \u0003ילדה נקבה,\u0004 שאין היא ראויה לאשם. הקשה על כך ר' אבין בר חייא: והרי נאמר במשנה שכך הוא הדין בולד ולדן עד סוף כל העולם, \u0003ו\u0004האם נעמיד משנתנו באופן זה שלאורך כל הדורות \u0003עד סוף\u0004 דורות \u0003העולם לא אוליד\u0004 \u0005[נולד]\u0006 אפילו ולד \u0003חד\u0004 \u0005[אחד]\u0006 ממין \u0003זכר?! אמר ליה\u0004 \u0005[לו]\u0006 ר' אבין בר כהנא בתשובה: \u0003משנינא שינויי דחיקי בבלאי\u0004 \u0005[מתרץ אני תירוצים דחוקים,\u0006 כדרכם של \u0005בבליים]\u0006 ויש להעמיד משנתנו באופן דחוק זה, שמדובר בה \u0003כגון שילדה נקבות עד סוף העולם.\u0004","הבהמה שהיא \u0003תמורת\u0004 קרבן \u0003הבכור ו\u0004כן זו שהיא תמורת קרבן \u0003המעשר,\u0004 וכן \u0003ולדן\u0004 של בהמות תמורה אלה, ואף \u0003ולד ולדן עד סוף העולם\u0004 — \u0003הרי\u0004 דינם של כל \u0003אלו כ\u0004דין ה\u0003בכור וכ\u0004דין \u0003מעשר\u0004 בהמה עצמם. לא לענין שיקרבו על המזבח כבכור וכמעשר בהמה, אלא לנהוג בהם בקדושה. והריהם רועים עד שיפול בהם מום. \u0003ו\u0004לאחר שנשחטו הרי אלו \u0003יאכלו במומן,\u0004 תמורת הבכור וולדותיה — לכהנים, ותמורת מעשר בהמה וולדותיה — \u0003לבעלים.\u0004","ומפרטים: \u0003מה\u0004 (איזה הבדל להלכה יש) \u0003בין\u0004 ה\u0003בכור ומעשר\u0004 בהמה \u0003לבין\u0004 שאר \u0003כל הקדשים\u0004 שנפל בהם מום: \u0003שכל\u0004 שאר \u0003הקדשים\u0004 שנפל בהם מום, ונפדו, הריהם \u0003נמכרים באיטלז\u0004 (שוק הבשר), כשאר בשר החולין, \u0003ו\u0004כן \u0003נשחטין\u0004 הם \u0003באיטלז, ונשקלין\u0004 לצורך קנייתם \u0003בליטרא\u0004 (במשקל המקובל בשוק הבשר). אף שיש בכך כעין זלזול בקדשים שנוהגים בהם כבחולין. \u0003חוץ מן הבכור והמעשר\u0004 שנפל בהם מום, שאין הם נמכרים אלא בבית, ואין נשקלים בליטרא.","\u0003ו\u0004עוד בהבדל שבין בכור ומעשר בהמה לבין שאר כל הקדשים, שכן לכל שאר הקדשים שנפל בהם מום \u0003יש להן פדיון\u0004 על ידי שיימכרו, ויצאו בכך לחולין וכספם יפול למקדש, \u0003ו\u0004כן \u0003לתמורותיהן\u0004 שיש בהן מום יש \u0003פדיון\u0004 במכירה, \u0003חוץ מן הבכור והמעשר,\u0004 שאין להם פדיון (שיצאו בכך לחולין). \u0003ו\u0004הבדל נוסף: כל שאר הקדשים \u0003באין\u0004 (מותר להביאם) אף \u0003מחוצה לארץ\u0004 להקרבתם במקדש, \u0003חוץ מן הבכור והמעשר, ש\u0004אין ראוי מלכתחילה להביאם מחוץ לארץ להקרבתם במקדש, ואולם בדיעבד \u0003אם באו\u0004 והם \u0003תמימים\u0004 (שאין בהם מום הפוסלם מהקרבה) — הרי אלו \u0003יקרבו\u0004 במקדש כבכור וכמעשר בהמה הבאים מהארץ. \u0003ואם\u0004 הם \u0003בעלי מומין\u0004 — הרי אלו \u0003יאכלו במומן,\u0004 הבכור — לכהנים, ומעשר בהמה — \u0003לבעלים.\u0004","\u0003אמר ר' שמעון: מה\u0004 ה\u0003טעם\u0004 לדין זה, שאין מביאים בכור ומעשר בהמה מחוץ לארץ להקרבתם במקדש, ושלא כשאר כל הקדשים? — מפני \u0003שהבכור והמעשר יש להן פרנסה\u0004 (אופן שבו ייאכלו) \u0003ממקומן,\u0004 בחוצה לארץ. שהרי יכולים הם לרעות עד שיפול בהם מום, ואז ייאכלו במומם. ואין איפוא צורך להביאם לארץ להקרבתם, על מנת לאוכלם. \u0003ו\u0004אילו \u0003שאר כל הקדשים, אף על פי שנולד בהם מום\u0004 — \u0003הרי אלו בקדושתן,\u0004 וצריך לפדותם ולהביא בדמיהם קרבן. וכיון שכך, נכון הוא להביאם בעצמם כשהם תמימים.","שנינו במשנתנו את דינם של הבכור ומעשר בהמה שנפל בהם מום, ובענין זה \u0003אמר רבא בר רב עזא,\u0004 \u0003בען במערבא\u0004 \u0005[שאלו\u0006 חכמים \u0005במערב,\u0006 בארץ ישראל\u0005]:\u0006 \u0003המטיל מום בתמורת בכור ו\u0004בתמורת \u0003מעשר\u0004 בהמה \u0003מהו\u0004 דינו? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון דלא קריבן\u0004 \u0005[שאין\u0006 תמורות אלה \u0005קרבות]\u0006 על המזבח כבכור ומעשר עצמם — \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 המטיל בהם מום, שכל עיקרו של איסור זה הוא רק כאשר פוסל בכך את הקדשים מהקרבה. \u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003כיון דקדשו\u0004 \u0005[ש\u0006סוף סוף \u0005התקדשו] — הריהו\u0006 \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 על הטלת מום בהם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא בר רב עזא: מדוע לא שאלת שאלתך זו בשם חכמי ארץ ישראל אלא בתמורת בכור ותמורת מעשר, \u0003ותיבעי\u0004 \u0005[ו\u0006הרי \u0005תישאל]\u0006 \u0003לך\u0004 שאלתך זו אף בזה \u0003המטיל מום\u0004 בקדשים אחרים, וכגון \u0003בתשיעי של\u0004 מנין \u0003מעשר\u0004 בהמה, וטעה המונה והכריז עליה \"עשירי\", שהתקדשה לענין איסור גיזה ועבודה בה (עד שיפול בה מום), ואולם אין היא קריבה!","\u0003אלא מאי שנא\u0004 \u0005[במה שונה,\u0006 מיוחד\u0005]\u0006 הוא \u0003תשיעי\u0004 של מעשר בהמה ש\u0003לא קמיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לך\u0004 שאלה זו? — הרי זה משום \u0003דרחמנא מעטיה\u0004 \u0005[שהתורה מיעטה אותו],\u0006 שכן נאמר \u0003\"העשירי\u0004 יהיה קודש\" (ויקרא כז, לב), ומדייקים: דווקא העשירי הוא הקרב, \u0003להוציא\u0004 את \u0003התשיעי\u0004 (שהוכרז בטעות כ\"עשירי\"), שאינו קרב. ומתוך כך נלמד שאין המטיל בתשיעי זה מום מתחייב על כך.","\u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אמור בדין תמורת הבכור: \u0003רחמנא מעטינהו\u0004 \u0005[התורה מיעטה אותם,\u0006 אותה\u0005],\u0006 שאין היא קריבה, שכן נאמר \"אך בכור... \u0003לא תפדה קדש הם\"\u0004 (במדבר יח, יז) — \u0003הם קריבין, ואין תמורתן קריבה,\u0004 ותלמד מכאן, שאף לענין הטלת מום, אין תמורת הבכור בכלל.","\u0003רב נחמן בר יצחק מתני לה הכי\u0004 \u0005[שנה אותה,\u0006 סוגיה זו, \u0005כך,\u0006 באופן הפוך מזה שאמרנו\u0005]:\u0006 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עזא, בען במערבא\u0004 \u0005[שאלו\u0006 חכמים \u0005במערב, בארץ ישראל]:\u0006 \u0003המטיל מום בתשיעי של מעשר מהו\u0004 דינו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003ותיבעי\u0004 \u0005[ותישאל]\u0006 \u0003לך\u0004 שאלתך זו בדין \u0003המטיל מום בתמורת בכור ומעשר!\u0004","\u0003אלא מאי שנא\u0004 \u0005[במה שונה,\u0006 מיוחד\u0005]\u0006 הוא \u0003תמורת בכור ומעשר\u0004 ש\u0003לא מיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לך\u0004 — משום \u0003דרחמנא מעטינהו\u0004 \u0005[שהתורה מיעטה אותם],\u0006 שכן נאמר \u0003\"קדש הם\"\u0004 — \u0003הן קריבין, ואין תמורתן קריבה. תשיעי של מעשר נמי\u0004 \u0005[גם כן],\u0006 \u0003רחמנא מעטיה\u0004 \u0005[התורה מיעטה אותו],\u0006 שכן נאמר \u0003\"העשירי\"\u0004 — \u0003להוציא את התשיעי.\u0004","למדנו במשנתנו שאף שאין מביאים לכתחילה את הבכור והמעשר מחוצה לארץ להקריבם בארץ, \u0003ואם\u0004 אירע ו\u0003באו\u0004 והם \u0003תמימין\u0004 — הרי אלו יקרבו. \u0003ו\u0004בענין זה \u0003רמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: מעשה באדם אחד ששמו \u0003בן אנטיגנוס\u0004 שעמד ו\u0003העלה בכורות מבבל\u0004 לארץ כדי להקריבם, \u0003ו\u0004במקדש \u0003לא קבלו\u0004 אותם \u0003ממנו! אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הא\u0004 \u0005[זו,\u0006 הלכה זו במשנתנו\u0005]\u0006 — הריהי כשיטת \u0003ר' ישמעאל,\u0004 ואילו \u0003הא\u0004 \u0005[זו,\u0006 ההלכה בבן אנטיגנוס\u0005]\u0006 — הריהי כשיטת \u0003ר' עקיבא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 שעולה ממנה שנחלקו בדבר ר' ישמעאל ור' עקיבא: \u0003ר' יוסי אומר\u0004 (מוסר) \u0003שלשה דברים משום\u0004 (בשם) \u0003שלשה זקנים\u0004 (חכמים), והם ר' ישמעאל, ר' עקיבא ובן עזאי. שדרש כל אחד מהם דרשה אחרת בענין בכור ומעשר. \u0003ר' ישמעאל אומר: יכול יעלה אדם\u0004 מחוצה לארץ את \u0003מעשר שני\u0004 שבידו \u0003בזמן הזה\u0004 (לאחר חורבן בית המקדש), \u0003ויאכלנו בירושלים?\u0004","— \u0003ודין\u0004 (דבר הנלמד) \u0003הוא,\u0004 מהשוואה לדין הבכור, ובאופן זה: ה\u0003בכור טעון\u0004 (חייב) הבאת מקום (העלאה לירושלים), ואף \u0003מעשר\u0004 שני \u0003טעון הבאת מקום.\u0004 ומעתה נאמר: \u0003מה בכור\u0004 — \u0003אינו נאכל אלא בפני\u0004 (בזמן) \u0003הבית, אף מעשר\u0004 שני — \u0003אינו נאכל אלא בפני הבית.\u0004 ואולם יש לפרוך השוואה זו: \u0003לא,\u0004 אין ללמוד דין מעשר שני מדין הבכור, שכן \u0003אם אמרת\u0004 כך \u0003בבכור,\u0004 שאינו נאכל אלא בזמן הבית — \u0003שכן\u0004 הריהו \u0003טעון מתן דמים\u0004 (נתינת דמי הקרבן) \u0003ו\u0004הקרבת ה\u0003אימורים\u0004 (חלקי הקרבן הקרבים) \u0003לגבי\u0004 \u0005[אצל,\u0006 על\u0005]\u0006 ה\u0003מזבח,\u0004 ויש לומר שמפני זה אינו נאכל אלא כשיש מזבח, בזמן הבית, \u0003תאמר\u0004 כן אף \u0003במעשר\u0004 שני — ש\u0003לא\u0004 חייב באלו?!","אלא חזרת ו\u0003אמרת\u0004 שיש ללמוד את דין אכילת מעשר שני בירושלים בזמן הזה לא מהשוואה לבכור אלא מהשוואה לביכורים, ובאופן זה: ה\u0003ביכורים טעונין הבאת מקום, ו\u0004אף \u0003מעשר\u0004 שני \u0003טעון הבאת מקום.\u0004 ומעתה נאמר: \u0003מה\u0004 ה\u0003ביכורים\u0004 — \u0003אין נאכלין אלא בפני הבית, אף מעשר\u0004 שני — \u0003אין נאכל אלא בפני הבית.\u0004","ואולם אף השוואה זו יש לפורכה, ובאופן זה: \u0003מה לביכורים\u0004 — \u0003שכן טעונין הנחה\u0004 לפני המזבח במקדש, שכך נאמר בהם: \"ולקח הכהן הטנא מידך והניחו לפני מזבח ה' אלהיך\" (דברים כו, ד), ולכך יש מקום לומר שהוא הטעם שאינם נאכלים אלא בפני הבית, והאם \u0003תאמר\u0004 כן אף \u0003במעשר\u0004 שני — ש\u0003לא\u0004 חייב בהנחה לפני המזבח?!","לכך \u0003תלמוד לומר\u0004 (בא כתוב ומלמדנו), בפרשת מעשר שני: \u0003\"ואכלת לפני ה' אלהיך\u0004 במקום אשר יבחר לשכן שמו שם \u0003מעשר דגנך ותירשך ויצהרך ובכרת בקרך וצאנך\"\u0004 (שם יד, כג), והרי בכך \u0003הקיש\u0004 (השוה) הכתוב \u0003מעשר\u0004 שני \u0003לבכור, מה בכור\u0004 — \u0003אינו נאכל אלא בפני הבית, אף מעשר\u0004 — \u0003אין נאכל אלא בפני הבית.\u0004 עד כאן דרשת ר' ישמעאל, ומעתה דנה הגמרא בדבריו.","ושואלים: מדוע לאחר שפרכנו את ההשוואה לביכורים, הגענו להיקש שבפסוק הזה, \u0003ו\u0004הרי היה מקום להמשיך ולומר: \u0003ליהדר דינא\u0004 \u0005[יסוב הלימוד\u0006 מהשוואה לבכור ולביכורים גם יחד\u0005],\u0006 \u0003וליתי\u0004 \u0005[ויבוא,\u0006 יילמד דינו של מעשר שני\u0005]\u0006 \u0003ב\u0004דרך הלימוד המכונה \u0003\"מה הצד\"\u0004 שאפשר ללמוד מהצד המשותף לבכור ולביכורים ששניהם טעונים הבאת מקום, ואינם נאכלים בזמן הזה, שאף מעשר שני, הטעון הבאת מקום, אינו נאכל בזמן הזה!","\u0003אמר רב אשי:\u0004 אף מצד משותף זה אין ללמוד לעניין מעשר שני, \u0003משום דאיכא למימר\u0004 \u0005[שיש מקום\u0006 לפרוך אותו ו\u0005לומר]:\u0006 \u0003מה להצד השוה שבהן\u0004 — \u0003שכן יש בהן צד\u0004 (היבט אחד מדיניהם עניינו) \u0003מזבח\u0004 (הבכור — החייב בנתינת דמים והקרבת אימורים על המזבח, והביכורים — החייבים בהנחה לפני המזבח), בעוד שבמעשר שני אין כל צד מזבח.","\u0003ו\u0004חוזרים לדון בדברי ר' ישמעאל: לדבריו הבכור אינו נאכל בזמן הזה, ואילו בעניינו של מעשר שני הריהו מסופק, \u0003ו\u0004יש לשאול: \u0003מאי קסבר\u0004 \u0005[ומה הוא סבור],\u0006 \u0003אי קסבר\u0004 \u0005[אם הוא סבור]\u0006 ש\u0003קדושה ראשונה\u0004 שהתקדשה ירושלים, \u0003קידשה לשעתה ו\u0004אף \u0003קידשה לעתיד לבא,\u0004 ואף בזמן שבית המקדש חרב, קדושתה עליה — אם כן, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דינו של ה\u0003בכור ולא שנא\u0004 \u0005[ואינו שונה]\u0006 דינו של \u0003מעשר\u0004 שני, ושניהם \u0003בני הבאה נינהו\u0004 \u0005[הם],\u0006 שלצורך הבכור יבנו מזבח בירושלים ויקריבוהו עליו, והמעשר שני יובא לירושלים וייאכל שם. \u0003ואי קסבר\u0004 \u0005[ואם הוא סבור]\u0006 כי \u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא,\u0004 ועם כל זה הריהו מסופק במעשר שני — \u0003אפילו\u0004 ב\u0003בכור נמי תיבעי\u0004 \u0005[גם כן תישאל]\u0006 \u0003לך!\u0004","ומשיבים: \u0003לעולם קסבר\u0004 \u0005[הוא סבור]\u0006 כי \u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא, והכא\u0004 \u0005[וכאן]\u0006 בדינו של בכור שפשוט לו שאינו נאכל בזמן הזה \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 — \u0003כגון שנזרק דמו של בכור\u0004 על המזבח עדיין \u0003בפני הבית, ו\u0004לאחר מכן \u0003חרב הבית, ועדיין בשרו קיים.\u0004","ו\u0003כיון דאי איתיה\u0004 \u0005[שאם היה עדיין]\u0006 \u0003לדם\u0004 הבכור, שעדיין לא נזרק על גבי המזבח — שוב \u0003לא בר\u0004 \u0005[בן]\u0006 \u0003זריקה\u0004 \u0003הוא,\u0004 שהרי חרב הבית. לכן \u0003אתי\u0004 \u0005[בא]\u0006 \u0003בשר\u0004 הבכור ו\u0003יליף\u0004 \u0005[למד]\u0006 \u0003מדם,\u0004 שכן הוקש בכתוב בשר הבכור לדם, שנאמר: \"את דמם תזרוק על המזבח... ובשרם יהיה לך\" (במדבר יח, יז—יח), ללמדנו שאין הבשר נאכל אלא בשעה שהדם ראוי להיזרק על המזבח."],["\u0003ו\u0004מאחר שפשוט לו לר' ישמעאל שבכור אינו נאכל בזמן הזה, דן ואמר כי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003מעשר\u0004 שני \u0003ויליף\u0004 \u0005[ולמד]\u0006 \u0003מ\u0004השוואתו ל\u0003בכור. ו\u0004שואלים על עצם דרך הלימוד המבוססת על השוואת מעשר שני לבשר הבכור: \u0003מי ילפינן\u0004 \u0005[האם למדים אנו]\u0006 דינם של דברים שהם מכלל ה\u0003קדש מהדדי\u0004 \u0005[אלו מאלו]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 ב\u0003כל\u0004 דיני \u0003התורה כולה למדין\u0004 אנו בדרכי לימוד התורה \u0003למד\u0004 (דין הנלמד) \u0003מן הלמד\u0004 (דין שהוא עצמו נלמד מדין אחר), \u0003חוץ מן הקדשים שאין למדין\u0004 בהם \u0003למד מן הלמד!\u0004 ומשיבים: אין זה לימוד בקדשים, שכן \u0003מעשר\u0004 שני \u0003חולין הוא\u0004 נחשב. וחוזרים ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006הסבר \u0005זה נוח למי שאומר]\u0006 כי \u0003בתר\u0004 \u0005[לאחר]\u0006 \u0003למד אזלינן\u0004 \u0005[הולכים אנו],\u0006 שאם הנושא הנלמד הוא קודש — אינו נלמד מדין אחר שהוא עצמו נלמד, ואם הוא חולין — הריהו נלמד מדין אחר שהוא עצמו נלמד. \u0003אלא למאן דאמר\u0004 \u0005[למי שאומר]\u0006 כי \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003מלמד אזלינן\u0004 \u0005[אנו הולכים],\u0006 שהדבר הקובע בכלל זה, הוא הדבר המלמד (ובענייננו, בשר הבכור הנלמד מדם הבכור), \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: דין \u0003בשר\u0004 הבכור \u0003ו\u0004דין \u0003דם\u0004 הבכור \u0003חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 ואין לומר שהבשר למד מן הדם וממילא אין כאן למד מן הלמד. שנינו בברייתא שר' יוסי מסר שלשה דברים משום שלשה זקנים. ומביאים את הדבר השני, ש\u0003ר' עקיבא אומר: יכול\u0004 מותר ש\u0003יעלה אדם בכור מחוצה לארץ לארץ בזמן שבית המקדש קיים, ויקריבנו?\u0004 — \u0003תלמוד לומר: \"ואכלת לפני ה' אלהיך\u0004 במקום אשר יבחר לשכן שמו שם \u0003מעשר דגנך ותירשך ויצהרך ובכרת בקרך וצאנך\"\u0004 (דברים יד, כג) — ללמדנו: רק \u0003ממקום שאתה מעלה\u0004 לירושלים את \u0003מעשר דגן\u0004 לאכילה, כלומר, מארץ ישראל — \u0003אתה מעלה\u0004 למקדש את ה\u0003בכור\u0004 להקרבה ולאכילה. \u0003ו\u0004אילו \u0003ממקום שאי\u0004 (שאין) \u0003אתה מעלה מעשר דגן\u0004 (חוצה לארץ) — \u0003אי\u0004 (אין) \u0003אתה מעלה בכור.\u0004 ולפיכך האמור במשנתנו שאם בדיעבד העלו בכורות מחוצה לארץ (אף שאסור מלכתחילה לעשות כן), הרי אלו קרבים, הוא כשיטת ר' ישמעאל, הסבור שאף שאין ראוי להביא לכתחילה מחוץ לארץ בכור להקרבה בארץ, אם הביא מחוץ לארץ בכור שאינו בעל מום — הריהו קרב. ומה ששנינו כי בן אנטיגנוס העלה בכורות מבבל, ולא קיבלו אותם ממנו להקרבה — משנה זו הריהי כשיטת ר' עקיבא.","","","","ושבים לבאר את הדבר השלישי באותה ברייתא, ובענין אכילת מעשר שני. \u0003בן עזאי אומר: יכול\u0004 מותר הדבר שיהא אדם \u0003מעלה את מעשר שני\u0004 שלו מביתו בארץ ישראל לירושלים, \u0003ויאכלנו\u0004 לאו דווקא בין חומות ירושלים (\"לפנים מן החומה\") אלא \u0003בכל\u0004 התחום \u0003הרואה\u0004 את ירושלים? \u0003ו\u0004מסביר בן עזאי את בעייתו זו: אכן \u0003דין\u0004 (דבר הנלמד) \u0003הוא\u0004 מהשוואת מעשר שני לקרבן בכור, ובאופן זה: קרבן \u0003בכור טעון\u0004 (חייב) ב\u0003הבאת מקום\u0004 (העלאה לירושלים), \u0003ו\u0004אף \u0003מעשר\u0004 שני \u0003טעון הבאת מקום.\u0004 ומעתה יש לומר: \u0003מה\u0004 ה\u0003בכור\u0004 — \u0003אינו נאכל אלא לפנים מן החומה, אף מעשר\u0004 שני — \u0003אינו נאכל אלא לפנים מן החומה.\u0004","אולם אפשר לפרוך: \u0003מה לבכור\u0004 — \u0003שכן\u0004 יש בו צד חומרה, שהוא \u0003טעון מתן דמים ואימורין\u0004 (חלקי הקרבן הקרבים) \u0003לגבי מזבח,\u0004 והאם \u0003תאמר במעשר\u0004 שני — ש\u0003לא\u0004 מחוייב באלו?! לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב): \u0003\"ואכלת לפני ה' אלהיך\u0004 במקום אשר יבחר לשכן שמו שם \u0003מעשר דגנך ותירשך ויצהרך ובכרת בקרך וצאנך\"\u0004 — \u0003מקיש\u0004 הכתוב דין ה\u0003מעשר ל\u0004דין ה\u0003בכור,\u0004 ללמדנו: \u0003מה בכור\u0004 — \u0003אינו נאכל אלא לפנים מן החומה, אף מעשר\u0004 — \u0003אינו נאכל אלא לפנים מן החומה.\u0004","ודנים: \u0003מאי קשיא ליה דקאמר\u0004 \u0005[מה\u0006 היה \u0005קשה לו,\u0006 לבן עזאי, \u0005שהוא אמר]\u0006 \u0003יכול\u0004 שיעלה את מעשר שני ויאכלנו בכל הרואה, מדוע נדרש בן עזאי כלל לשאלה זו? ומסבירים: שכן \u0003אמרת\u0004 (יכול היית לומר) שמותרת אכילת מעשר שני בירושלים בכל הרואה, וטעם הדבר, \u0003הואיל ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 \u0003אין בין\u0004 הדינים שנהגו בהיות המשכן ב\u0003שילה ל\u0004בין הדינים הנוהגים בהיות בית המקדש ב\u0003ירושלים, אלא ש\u0004בהיות המשכן \u0003בשילה\u0004 היו \u0003אוכלין\u0004 \u0003קדשים קלים ו\u0004כן \u0003מעשר שני בכל הרואה, ו\u0004אילו בהיות המקדש \u0003בירושלים\u0004 אין אלו נאכלים אלא \u0003לפנים מן החומה,\u0004","\u0003וכן\u0004 הקרבנות שהם בכלל \u0003קדשי קדשים\u0004 אינם נאכלים, הן בשילה והן בירושלים, אלא \u0003לפנים מן הקלעים\u0004 (בשילה — בין יריעות חצר המשכן, ובירושלים — בין חומות העזרה). ומעתה היה מקום לומר כי מאחר וכאמור, אין במעשר שני חומרה מיוחדת כמו בבכור (שהוא טעון מתן דמים ואימורים), ואם כן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שאף \u0003בירושלים ליתי\u0004 \u0005[יביאו]\u0006 \u0003מעשר שני בכל הרואה,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאין הדין כן, וכפי ששנינו במשנה.","באותה ברייתא הביא ר' יוסי מסורת נוספת של חכמים, בענין הבכור. במשנה בבכורות (כו,ב) נאמר שהבכור נאכל בתוך שנתו, כנאמר בו: \"לפני ה' אלהיך תאכלנו שנה בשנה\" (דברים טו, כ). \u0003אחרים אומרים: יכול\u0004 אדם לומר ש\u0003יהא\u0004 דינו של ה\u0003בכור שעברה שנתו כ\u0004שאר \u0003פסולי המוקדשין\u0004 (קרבנות שנפסלו), \u0003ויפסל\u0004 בכך?","לכך \u0003תלמוד לומר\u0004 (הכתוב אומר) \"ואכלת לפני ה' אלהיך... \u0003מעשר דגנך ותירשך ויצהרך\u0004 ובכורות בקרך וצאנך\", הרי שהכתוב \u0003מקיש בכור למעשר,\u0004 ומכאן נלמד: \u0003מה מעשר\u0004 — \u0003אינו נפסל משנה לחבירתה, אף בכור\u0004 — \u0003אינו נפסל משנה לחבירתה.\u0004","ושואלים: \u0003ולרבנן\u0004 \u0005[ולחכמים,\u0006 האחרים שבמסורותיו של ר' יוסי, ר' ישמעאל, ר' עקיבא ובן עזאי\u0005],\u0006 \u0003דמפקי להו לטעמא אחרינא\u0004 \u0005[שמוציאים הם,\u0006 שלמדים מכתוב זה בדרך היקש \u0005לטעם,\u0006 לדין \u0005אחר],\u0006 אם כן הלכה זו שאין הבכור נפסל \u0003משנה לחבירתה מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצאת,\u0006 נלמד \u0005להם]\u0006 הלכה זו \u0003מ\u0004הכתוב \u0003\"לפני ה' אלהיך תאכלנו שנה בשנה\"\u0004 (דברים ט, ב) — והרי לשון הכתוב \"שנה בשנה\", יש בה הוראת שתי שנים, ובכך \u0003לימד\u0004 בין השאר \u0003על הבכור שאינו נפסל משנה לחברתה. ו\u0004חוזרים ושואלים לצד ההפוך: \u0003ל\u0004שיטתם של \u0003אחרים\u0004 הלמדים מהיקש הכתוב בכור למעשר, אם כן בכתוב זה \u0003\"לפני ה' אלהיך תאכלנו שנה בשנה\"\u0004 (דברים ט, ב) \u0003מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך להם\u0006 כתוב זה, \u0005ל\u0006הלכה אחרת בבכור, ו\u0005כמו ששנינו\u0006 בברייתא\u0005]\u0006 בענין זמן אכילתו של הבכור: שכך נלמד מהכתוב בו \"שנה בשנה\" — שיש אופן שייאכל בשרו על פני שנתיים: ב\u0003יום אחד\u0004 (שהוא היום האחרון) \u0003משנה זו, ו\u0004ב\u0003יום אחד\u0004 (שהוא היום הראשון) \u0003משנה אחרת,\u0004 ומכאן \u0003לימד\u0004 הכתוב \u0003על הבכור ש\u0004הוא \u0003נאכל לשני ימים ולילה אחד.\u0004","","ושואלים לצד האחר: \u0003ורבנן\u0004 \u0005[וחכמים,\u0006 ר' ישמעאל ור' עקיבא ובן עזאי\u0005],\u0006 דין זה שהבכור \u0003נאכל לשני ימים ולילה אחד מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בדין הבכור \"ובשרם \u0003יהיה לך כחזה התנופה\u0004 וכשוק הימין יהיה לך\" (במדבר יח, יח), ומכפל הלשון \"יהיה לך\" למדנו שמשך אכילת הבכור יש בו יום נוסף (על פני אכילת תודה, הנאכלת ליום ולילה בלבד), והריהו נאכל לשני ימים ולילה.","","ה\u0003ולד\u0004 הנולד לקרבן \u0003חטאת, ו\u0004כן הבהמה שהיא \u0003תמורת חטאת, ו\u0004כן קרבן ה\u0003חטאת שמתו בעליה\u0004 קודם שקרב קרבנם — דינם של כל אלה ש\u0003ימותו,\u0004 על ידי שכונסים אותם במקום סגור, ומונעים מהם מזון. \u0003ו\u0004אילו החטאת \u0003שעיברה שנתה\u0004 (שעברה שנה משנולדה) שהיא פסולה, שכן אין החטאת באה אלא בתוך שנתה, \u0003ו\u0004כן החטאת \u0003שאבדה ונמצאת\u0004 לאחר מכן כשהיא \u0003בעלת מום, אם משכפרו\u0004 (התכפרו) \u0003הבעלים\u0004 בהקרבת בהמה אחרת תחת זו לאחר שאבדה — \u0003תמות, ו\u0004כן דינה ש\u0003אינה עושה תמורה,\u0004 כלומר, שאם המירו עליה בהמת חולין — אין זו תמורה."],["\u0003לא נהנין\u0004 לכתחילה ממנה, \u0003ו\u0004אולם אם עברו ונהנו ממנה לא נחשב הדבר ש\u0003מועלין\u0004 בה (לענין הבאת קרבן מעילה). \u0003ואם\u0004 נמצאה כשהיא בעלת מום או שעברה שנתה \u0003עד שלא כיפרו\u0004 \u0003הבעלים\u0004 באחרת — הרי דינה של זו שעברה שנתה ש\u0003תרעה עד שתסתאב\u0004 (שיפול בה מום הפוסל מהקרבה), \u0003ותמכר, ויביא בדמיה\u0004 בהמה \u0003אחרת\u0004 לחטאת, וזו שאבדה ונמצאה בעלת מום תימכר מיד (שהרי היא כבר מסואבת, בעלת מום), ויביא בדמיה אחרת. וכל עוד לא נמכרה הריהי קדושה, \u0003ו\u0004לכן דינה שהיא \u0003עושה תמורה\u0004 אם המירו בה בהמת חולין, \u0003ו\u0004הנהנים ממנה \u0003מועלין בה,\u0004 וחייבים בדיני המעילה.","המשנה דנה בתחילה בדינן של שלוש מכלל חמש החטאות המתות (ולד החטאת, תמורת החטאת, וחטאת שמתו בעליה) בנפרד, ואחר כך בדינן של השתיים האחרות (שעברה שנתה, ושמתו בעליה) בנפרד. ושואלים: \u0003מאי טעמא לא תני להו גבי הדדי\u0004 \u0005[מה טעם לא שנה אותם\u0006 התנא \u0005זה אצל זה\u0006 ביחד\u0005]?\u0006 ומשיבים: הפריד התנא, משום שב\u0003רישא\u0004 \u0005[\u0006ב\u0005תחילת]\u0006 המשנה, בדינן של השלוש הראשונות — \u0003פסיקא ליה\u0004 \u0005[פסוקה לו,\u0006 קבוע\u0005]\u0006 דינן, שבין שהתכפרו הבעלים, ובין אם לא — הריהן מתות. ואילו ב\u0003סיפא\u0004 \u0005[סוף,\u0006 המשך\u0005]\u0006 המשנה, בדינן של השתיים האחרות — \u0003לא פסיקא ליה\u0004 \u0005[אינה פסוקה לו]\u0006 דינן, שתלוי הדבר אם התכפרו הבעלים או לא.","ושואלים על דרך כתיבת המשנה: משנה זו, כלשונה, מופיעה אף במסכת מעילה, ו\u0003למה לי למיתנייה גבי\u0004 \u0005[לשנותה\u0006 גם \u0005אצל]\u0006 \u0003מעילה, למה לי למיתנייה גבי\u0004 \u0005[לשנותה\u0006 גם \u0005אצל]\u0006 \u0003תמורה?\u0004 ומשיבים: \u0003תנא הכא\u0004 \u0005[שנה כאן]\u0006 במסכת תמורה משנה זו משום דין ה\u0003תמורה\u0004 השנוי בה, \u0003ואיידי דתנא\u0004 \u0005[ואגב ששנה]\u0006 דין \u0003תמורה\u0004 — \u0003תנא נמי\u0004 \u0005[שנה גם כן],\u0006 הזכיר את דין ה\u0003מעילה\u0004 בעניינן (\"לא נהנין ולא מועלין\"). \u0003ואיידי דתנא גבי\u0004 \u0005[ואגב ששנה אצל]\u0006 מסכת \u0003מעילה\u0004 אותן הלכות בשל דיני \u0003מעילה\u0004 שבה — \u0003תנא נמי\u0004 \u0005[שנה גם כן],\u0006 הזכיר את דין ה\u0003תמורה\u0004 בעניינן (\"עושה תמורה\", \"אינה עושה תמורה\").","בענין חטאת שעברה שנתה \u0003אמר ריש לקיש: חטאת שעיברה\u0004 (עברה) \u0003שנתה\u0004 — \u0003רואין אותה\u0004 (דנים בה) \u0003כאילו\u0004 היא \u0003עומדת בבית הקברות\u0004 (מקום שאין הכהן יכול להגיע אליה כדי להקריבה שהרי אסור לו להיטמא). \u0003ו\u0004דינה שתהא \u0003רועה\u0004 עד שיפול בה מום, ותימכר, ובדמיה יקריבו בהמה אחרת לחטאת. ולכאורה מתוך דברי ריש לקיש עולה כי חטאת שעברה שנתה, אף אם נתכפרו הבעלים באחרת דינה לרעיה ואינה מתה (שהרי לא חילק בין התכפרו ללא התכפרו).","ועל כך קשה, \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו: \u0003שעיברה שנתה, ואבדה ונמצאת\u0004 לאחר מכן כשהיא \u0003בעלת מום, אם אחר שכיפרו בעלים\u0004 — \u0003מתה,\u0004 והרי שאין דינה לרעיה, והרי זו איפוא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת \u0003ריש לקיש!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך ריש לקיש:\u0004 \u0003כי קתני רישא\u0004 \u0005[כאשר נשנתה\u0006 ב\u0005תחילת\u0006 המשנה\u0005]\u0006 \u0003\"מתה\"\u0004 — הרי זה בענין \u0003אבדה ונמצאת בעלת מום,\u0004 ש\u0003אם\u0004 נמצאה \u0003אחר שכיפרו בעלים\u0004 — \u0003תמות,\u0004 ואכן לא נשנית בדינה של זו שעברה שנתה.","ושואלים על כך: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין מדובר בעברה שנתה, אלא רק באבדה ונמצאה כשהיא בעלת מום, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשך המשנה\u0005]:\u0006 ו\u0003אם עד שלא כיפרו הבעלים\u0004 — \u0003תרעה עד שתסתאב\u0004 (שיפול בה מום), \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באבדה ונמצאה \u0003בעלת מום\u0004 — מה מקום יש לומר שתרעה עד שיפול בה מום, \u0003הא מסאבא וקיימא\u0004 \u0005[הרי\u0006 כבר \u0005מסואבת\u0006 (בעלת מום) \u0005ועומדת]\u0006 היא!","\u0003אמר רבה\u0004 בהסבר הדברים לשיטת ריש לקיש: אכן מדובר באבדה ונמצאה כשהיא בעלת מום, ו\u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 זו כוונת\u0005]\u0006 ה\u0003תנא:\u0004 בהמת חטאת \u0003שאבדה ונמצאת\u0004 כשהיא \u0003בעלת מום עובר, אם\u0004 נידון בה ל\u0003אחר שכפרו\u0004 (שהתכפרו) ה\u0003בעלים\u0004 באחרת, ואף אם נמצאה קודם לכן — הרי זו \u0003מתה.\u0004 ואולם \u0003אם\u0004 דנים אנו בה \u0003קודם שכיפרו בעלים\u0004 — דינה הוא ש\u0003תרעה עד שתסתאב במום קבוע, ותימכר,\u0004 ויביא בדמיה אחרת.","\u0003אמר רבא\u0004 יש לדחות הסבר זה, שכן \u0003שתי תשובות\u0004 (דחיות) יש \u0003בדבר, חדא\u0004 \u0005[האחת]\u0006 — ש\u0003אם כן,\u0004 שמדובר שיש בה מום עובר, אין נוסח המשנה הולם, שהרי אין לומר \"תרעה עד שתסתאב (יפול בה מום)\" שהרי כבר יש בה מום, אלא \u0003\"ישמור\u0004 (ימתין), ויראה אם מום זה ייעשה מום קבוע\" \u0003מיבעי ליה למיתני\u0004 \u0005[צריך היה לו לשנות]!\u0006 \u0003ועוד,\u0004 אם הדיון בסוף המשנה רק בחטאת שאבדה ונמצאה כשהיא בעלת מום, ולא בחטאת שעברה שנתה, אם כן זו ששנינו במשנתנו \u0003\"שעיברה שנתה\" למאי הלכתא קתני\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה נשנתה]?\u0006","\u0003אלא אמר רבא\u0004 בתירוץ דברי ריש לקיש, ובאופן שלא יקשה עליו מדברי המשנה: \u0003הכי קתני\u0004 \u0005[כך שנויה\u0006 משנתנו\u0005],\u0006 \u0003עברה שנתה ואבדה, או אבדה ונמצאת בעלת מום.\u0004 שבשתי החטאות הללו (ואף בעברה שנתה) מדובר באופן שאבדה החטאת, ולאחר מכן נמצאה (במקרה של עברה שנתה — אף כשנמצאה בלא מום, או שאבדה ונמצאה בעלת מום), והרי איפוא ישנן שתי מגרעות (\"ריעותות\") בכל אחת מאלו (עברה שנתה ואבדה, או כשאבדה והריהי בעלת מום). ומשום כך דינן של אלו, שאם היה זה ל\u0003אחר שכיפרו הבעלים\u0004 באחרת — זו וזו \u0003מתה,\u0004 ואם \u0003קודם שכיפרו הבעלים\u0004 באחרת — זו וזו אינה קרבה, שהרי פסולות הן להקרבה, אלא \u0003תרעה עד שתסתאב, ותימכר.\u0004 ואילו ריש לקיש שאמר בחטאת שעברה שנתה שדינה לרעיה, ואפילו התכפרו הבעלים באחרת — דווקא בזו שיש בה מגרעת אחת בלבד אמר, שעברה שנתה, אך לא שגם אבדה.","\u0003וצריך\u0004 איפוא \u0003למיתני\u0004 \u0005[לשנות]\u0006 במשנתנו את האמור בה \u0003\"אם אבדה\"\u0004 הן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בעלת מום ו\u0004הן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עברה שנתה,\u0004 ובאופן זה: \"עברה שנתה ואבדה, ושאבדה ונמצאת בעלת מום\", וצריך שייאמר הדין בשתיהן, משום \u0003דאי תנא גבי\u0004 \u0005[שאם היה שונה\u0006 רק \u0005אצל]\u0006 \u0003שעיברה\u0004 (שעברה) \u0003שנתה\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דמהניא\u0004 \u0005[שמועילה]\u0006 \u0003לה אבדה\u0004 לענין זה שיהא דינה למיתה (אם התכפרו הבעלים באחרת) — \u0003משום דלא חזיא למילתה\u0004 \u0005[שאינה ראויה לדברה,\u0006 להקרבתה כחטאת\u0005],\u0006 שהרי עברה שנתה. \u0003אבל בעלת מום, דאי לא מומא\u0004 — \u0003חזיא\u0004 \u0005[שאלמלא המום\u0006 — \u0005היתה ראויה]\u0006 להקרבה לחטאת, \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003לא תהני ליה\u0004 \u0005[יועיל לו]\u0006 זה שהיא \u0003אבדה\u0004 לענין שתלך למיתה.","\u0003ו\u0004מן הצד האחר, \u0003אי תני גבי\u0004 \u0005[אם היה שונה\u0006 שאבדה, רק \u0005אצל]\u0006 \u0003בעלת מום,\u0004 הייתי אומר: דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דמהניא\u0004 \u0005[שמועילה]\u0006 \u0003לה אבדה\u0004 לענין זה שתמות (אם התכפרו הבעלים באחרת) — \u0003משום דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003ל\u0004כל \u0003הקרבה\u0004 שהיא, שהרי בעלת מום היא. \u0003אבל עיברה שנתה, דחזי\u0004 \u0005[שראויה]\u0006 היא \u0003להקרבה\u0004 בקרבנות אחרים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא תהני\u0004 \u0005[תועיל]\u0006 \u0003לה אבדה\u0004 לענין זה שתמות, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה שתיהן.","ושואלים על הסברו זה של רבא במשנתנו, שחטאת שעברה שנתה ואבדה — דינה למיתה, \u0003ומי\u0004 \u0005[והאם]\u0006 אכן \u0003אמר רבא הכי\u0004 \u0005[כך]\u0006 שכאשר עברה שנתה ואבדה לאחר מכן שאינה קרבה אלא מתה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: אבידה\u0004 של קרבן, וכגון חטאת, ב\u0003לילה\u0004 שאין הוא זמן הקרבה — \u0003לא שמה\u0004 (אינה נחשבת) \u0003אבידה,\u0004 ומשום כך, אם הפריש אחרת תחתיה, ונמצאה האבידה לפני הבוקר, אין היא מתה אלא רועה. וכך הדין אפילו לשיטת האומר (רבי) שאפילו נמצאה לפני הכפרה באחרת הריהי גם כן מתה. הרי שלשיטת רבא, הקרבן האבוד בזמן שאינו ראוי להקרבה אינו נחשב כאבידה, ואם כן אף החטאת שעברה שנתה ואבדה, כיון שאינה ראויה להקרבה אינה נחשבת כאבידה, ומדוע יהיה דינה למיתה?","ומשיבים: \u0003לא דמי\u0004 \u0005[אינו דומה]\u0006 דין האבוד בלילה לדין האבודה לאחר שעברה שנתה. שכן \u0003אבידה דליליא\u0004 \u0005[של לילה]\u0006 — בשעת אבידתה היא \u0003לא חזיא\u0004 \u0005[ראויה]\u0006 \u0003לא לגופה\u0004 (שיקריבוה) \u0003ולא לדמי\u0004 \u0005[לדמים]\u0006 שיפדוה ויקריבו את הקרבן הנקנה בדמיה בלילה. \u0003אבל הא\u0004 \u0005זו]\u0006 שאבדה לאחר שעברה שנתה — \u0003נהי\u0004 \u0005[אמנם]\u0006 \u0003לגופה\u0004 היא \u0003לא חזיא\u0004 \u0005[ראויה],\u0006 אבל \u0003לדמי\u0004 \u0005[לדמים]\u0006 שימכרוה, ובכסף שיתקבל יקריבו חטאת, הריהי \u0003חזיא\u0004 \u0005[ראויה].\u0006","ומקשים עוד על דברי רבא, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדינם של שני שעירי יום הכיפורים (השעיר לה' והשעיר לעזאזל), שאם לאחר שהוגרלו השעירים ונקבע מי מהם לה' ומי לעזאזל, מת השעיר לעזאזל — מביאים זוג אחר של שני שעירים, ומגרילים עליהם איזה מהם לה' ואיזה לעזאזל. והשעיר המיועד לעזאזל, נשלח לשם, ואילו מבין שני השעירים לה' (מהזוג הראשון ומהזוג השני) — אחד מהם יוקרב לעבודת היום במקדש, ו\u0003השני ירעה עד שיסתאב\u0004 (יפול בו מום), \u0003וימכר, ויפלו דמיו ל\u0004קרבן \u0003נדבה.\u0004 ומסבירה המשנה את טעמו של דין זה שאין השעיר השני מובל למיתה (כחטאות המתות): \u0003לפי ש\u0004הוא מחטאות הציבור, \u0003ואין חטאת הציבור מתה.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד, שבמקרה דומה, אם היתה זו חטאת של \u0003יחיד\u0004 — הריהי \u0003מתה. ו\u0004כיון שלא נאמר במפורש במשנה מי משני השעירים לה' הוא זה שהולך לרעיה, האם זה שנותר מההגרלה הראשונה, או זה הנותר מההגרלה השניה,","\u0003אמר ר' יוחנן:\u0004 הנותר מההגרלה השניה הוא שקרב, שכן כלל הוא ש\u0003בעלי חיים נדחין\u0004 (כלומר, בעל חיים שהוקדש למטרה מסויימת, ולא היה ראוי בשעתו לקרבן, הריהו נחשב כדחוי ופסול משום כך לעולם), ולכן אף במקרה זה: השעיר שבזוג הראשון, כיון שלא היה לו בן זוג בשעתו, נפסל לעולם מלהיקרב, \u0003ו\u0004מעתה \u0003כשהוא מתכפר\u0004 — \u0003ב\u0004שעיר ה\u0003שני שב\u0004זוג ה\u0003שני\u0004 הוא \u0003מתכפר. ו\u0004מעתה הריהי שאלה על שיטת רבא, שכן","\u0003אידך, קמא\u0004 \u0005[\u0006השעיר \u0005האחר, הראשון]\u0006 \u0003הוה ליה\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 חטאת ש\u0003עיברה שנתה,\u0004 שבשניהם אין פסול הקרבתם נובע ממום שנפל בהם, אלא מגורם חיצוני כלשהו, \u0003וטעמא\u0004 \u0005[והטעם]\u0006 שאין השעיר שבזוג הראשון הולך למיתה אלא דינו לרעיה, הריהו רק משום שהיא חטאת של \u0003ציבור,\u0004 ונסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה זו חטאת של \u0003יחיד\u0004 — \u0003מתה,\u0004 ומכאן שאף חטאת שעברה שנתה דינה למיתה, ואף בלא אבדה!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך\u0004 רבא כי הוא עצמו סבור שאם נדחה הקרבן (וכגון חטאת שעברה שנתה), והתכפרו הבעלים באחרת — דינו למיתה, ושלא כשיטת ריש לקיש, וכל שאמר שמשנתנו עוסקת בעברה שנתה ואבדה, לא היה זה אלא לשיטת ריש לקיש, וממשנה זו שבדין שני השעירים קשה לשיטת ריש לקיש. ואולם באשר לשאלה בדין החטאת שאבדה ונתכפרו הבעלים באחרת ונמצאה לאחר מכן כשהיא בעלת מום שדינה למיתה, מדוע נצרכים אנו שיהיה בה מום כדי לקיים בה דין מיתה, והלא בכך שאבדה — נדחתה, ודי בכך לקיים בה דין מיתה? — על כך יש להשיב: אינה דומה דינם של הדחויים (כגון השעיר לה' מהזוג הראשון) לאבודה (כגון חטאת זו), ו\u0003דחויין לחוד, ואבודין לחוד,\u0004 שבדחויים כשלעצמם — דינם למיתה, ואילו באבודים — אין בדבר זה כשלעצמו כדי להוציאם למיתה, אלא אם כן יש בהם מום. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל ביניהם? \u0003אבודין\u0004 — \u0003דעתיה עליהון דילמא משתכחין\u0004 \u0005[דעתו עליהם\u0006 כל הזמן \u0005שמא יימצאו],\u0006 ויהיו ראויים להקרבה, ואילו \u0003דחויין\u0004 — \u0003לא הדרי מתחזיין\u0004 \u0005[אינם חוזרים להיות נראים]\u0006 להקרבה."],["למעלה הובאו דברי רבא בדינה של החטאת שאבדה בלילה, ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לגופה,\u0006 כשלעצמה\u0005].\u0006 \u0003אמר רבא: אבודה\u0004 שאבדה ב\u0003לילה\u0004 ונמצאת בבוקר, שבזמן שהיתה אבודה אי אפשר היה להקריב אחרת תחתיה — \u0003לא שמה אבודה\u0004 שדינה למיתה. ומבררים: \u0003אליבא דמאן\u0004 \u0005[לשיטת מי]\u0006 אמר רבא את דבריו אלו? \u0003אילימא אליבא דרבנן\u0004 \u0005[אם תאמר\u0006 כי \u0005לשיטתם של חכמים]\u0006 אמר זאת — \u0003מאי איריא\u0004 \u0005[מה המכוון,\u0006 המיוחד\u0005]\u0006 במקרה של ה\u0003אבודה\u0004 ב\u0003לילה?\u0004 שהרי \u0003אפילו\u0004 \u0003אבודה\u0004 ב\u0003יום נמי\u0004 \u0005[גם כן]\u0006 אינה נחשבת בהכרח כאבודה, לענין זה שתמות, שהרי אם נמצאה קודם שהוקרבה אחרת תחתיה, אינה יוצאת לשיטתם למיתה! \u0003דאמרי רבנן\u0004 \u0005[ש\u0006כן \u0005אמרו חכמים]:\u0006 הבהמה שהיתה \u0003אבודה בשעת הפרשה\u0004 של בהמה אחרת תחתיה, ונמצאה לפני שקרבה האחרת — הריהי \u0003רועה,\u0004 ולא מתה.","\u0003ואלא\u0004 תאמר שדברי רבא הם \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבי\u0004 הסבור כי גם האבודה בשעת הפרשה של האחרת דינה למיתה, ובא רבא ללמדנו שאין בכלל זה הבהמה שהיתה אבודה בלילה — הרי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבי\u0004 את שיטתו זו שהיא מתה, \u0003אלא\u0004 ב\u0003אבידה\u0004 ב\u0003יום,\u0004 שהוא זמן הקרבה, \u0003אבל אבידה\u0004 ב\u0003לילה,\u0004 שאין זה זמן הקרבה — אפשר ש\u0003אפילו רבי מודה\u0004 במקרה זה שאין היא מתה, אלא \u0003לרעייה אזלא\u0004 \u0005[הולכת],\u0006 ומה אם כן חידש רבא?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003לעולם\u0004 אמר רבא את דבריו \u0003אליבא דרבנן\u0004 \u0005[לשיטתם של חכמים],\u0006 \u0003ו\u0004אשר לשאלה מדוע ציין רבא דווקא אבודה בלילה, והרי אף באבודה ביום במקרה מסויים כך הדין? \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004מקרה שבהמה זו ש\u0003אבדה\u0004 נמצאה \u0003ב\u0004זמן שלאחר \u0003שעת כפרה,\u0004 שכבר התכפרו הבעלים באחרת. ובכל זאת אינה הולכת למיתה, אלא לרעיה, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן\u0004 \u0005[אמרו חכמים]\u0006 שכש \u0003אבדה\u0004 אף \u0003בשעת כפרה\u0004 — דינה שהיא \u0003מתה, אלא היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005],\u0006 ש\u0003עיקר אבידתה ביום,\u0004 בזמן הראוי להקרבה, \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003עיקר אבידתה בלילה\u0004 — \u0003לא\u0004 אמרו חכמים.","ועוד בעניינה של החטאת האבודה, \u0003אמר אביי: נקטינן\u0004 \u0005[אוחזים אנו,\u0006 מקובל בידינו\u0005]\u0006 כלל זה: דווקא \u0003אבידה\u0004 מתה — \u0003ולא\u0004 החטאת ה\u0003גנובה. אבידה\u0004 — \u0003ולא\u0004 החטאת ה\u0003גזולה.\u0004 שאם נגנבה או נגזלה הבהמה, וחזרה לרשות בעליה לאחר שהתכפרו באחרת — אין דינה למיתה, אלא רועה עד שייפול בה מום, ותימכר, ויפלו דמיה להקדש.","ומבררים: \u0003היכי דמי\u0004 \u0005[איך זה בדיוק]?\u0006 באיזה אופן נחשב הדבר ל\u0003אבידה? אמר ר' אושעיא: אפילו\u0004 אם התערבה בהמת חטאת \u0003אחת\u0004 \u0003ב\u0004תוך \u0003עדרו,\u0004 ואף שהעדר עומד לפניו, ויש בו את מנין הבהמות שבעדר ועוד אחת, אך אינו מזהה את החטאת שבתוכן, \u0003ואפילו\u0004 התערבה בהמת חטאת \u0003אחת ב\u0004בהמת חולין \u0003אחת,\u0004 שאינו יודע מי משתיהן היא החטאת. \u0003ור' יוחנן אמר:\u0004 אבודה היא זו שנמצאת \u0003אחורי הדלת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים בהבנת דברי ר' יוחנן\u0005]:\u0006 \u0003היכי קאמר\u0004 \u0005[איך אמר]?\u0006 האם דווקא כשנמצאת הבהמה מ\u0003אחורי הדלת הוא\u0004 שנחשב הדבר כאבודה — וטעם הדבר: משום \u0003דליכא דקא חזי לה\u0004 \u0005[שאין\u0006 מי \u0005שהוא רואה אותה],\u0006 \u0003אבל\u0004 לשיטה זו, אילו נמצאת הבהמה \u0003אבראי\u0004 \u0005[בחוץ],\u0006 במקום בו רועות בהמות אחרות, והיא ביניהן, כיון \u0003דאיכא דחזי לה\u0004 \u0005[שיש\u0006 מי \u0005שרואה אותה]\u0006 — \u0003לא הויא\u0004 \u0005[אין היא]\u0006 נחשבת \u0003אבודה. או דילמא\u0004 \u0005[שמא]\u0006 כוונת דברי ר' יוחנן היא כך: אפילו נמצאת הבהמה \u0003אחורי הדלת,\u0004 והרי זה מצב \u0003דאי מהדר אפיה חזי לה\u0004 \u0005[שאם מחזיר פניו,\u0006 מסתובב לאחוריו, הריהו \u0005רואה אותה]\u0006 — בכל זאת \u0003הויא\u0004 \u0005[הריהי]\u0006 נחשבת \u0003אבודה, וכל שכן\u0004 כשנמצאת הבהמה \u0003אבראי\u0004 \u0005[בחוץ],\u0006 \u0003דלא קחזי לה\u0004 \u0005[שאין הוא רואה אותה]\u0006 נחשבת כאבודה. ומסכמים: לשאלה זו לא נמצא פתרון, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ועוד בענין החטאת האבודה. \u0003אמר רב פפא: גמרינן\u0004 \u0005[למודים אנו,\u0006 מקובל בידינו\u0005]\u0006 כי אם היתה החטאת \u0003אבודה ממנו\u0004 (מהבעלים) \u0003ולא מ\u0004ה\u0003רועה\u0004 אותה בעדר — \u0003לא הויא\u0004 \u0005[אין היא]\u0006 נחשבת \u0003אבודה, וכל שכן\u0004 שאין היא נחשבת אבודה בזמן שהיא \u0003אבודה מ\u0004ה\u0003רועה ולא אבודה ממנו\u0004 (מהבעלים). ואולם יש לשאול במקרה שהיא \u0003אבודה ממנו ומרועה, ו\u0004אולם ישנו אדם \u0003אחד\u0004 הנמצא אף \u0003בסוף העולם\u0004 (במקום מרוחק מאוד) שהוא \u0003מכיר בה,\u0004 וממנו אינה אבודה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? אף שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 ללא פתרון.","ועוד באותו ענין, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם היתה החטאת \u0003אבודה\u0004 בשעה שכבר נשחטה החטאת האחרת שהקדיש במקומה, והתקבל דמה והריהו עתה נתון \u0003בכוס\u0004 (מזרק) ועומד להיזרק על המזבח, ונמצאה האבודה, \u0003מהו\u0004 דינה? ומבררים: \u0003אליבא דמאן\u0004 \u0005[לשיטת מי]\u0006 שאל רב פפא את שאלתו זו? \u0003אילימא אליבא\u0004 \u0005[אם תאמר לשיטת]\u0006 \u0003רבי\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]\u0006 רבי כי אפילו זו שהיתה \u0003אבודה בשעת הפרשה\u0004 של האחרת — נחשבת כאבודה, ודינה שהיא \u0003מתה,\u0004 ובודאי זו שאבודה בשעה שהאחרת כבר נשחטה, ועומד הדם להיזרק ולהשלים בכך את כפרתם של הבעלים!","\u0003אלא\u0004 יש לומר: \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 לרב פפא הרי זה \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים],\u0006 ואלו צדדי הבעיה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו],\u0006 \u0003כי אמרי רבנן\u0004 \u0005[כאשר אמרו חכמים]\u0006 כי האבודה \u0003בשעת הפרשה\u0004 דינה שהיא \u0003רועה\u0004 ולא מתה, הרי זה דווקא \u0003קודם שיקבל דמה בכוס, אבל הכא\u0004 \u0005[כאן]\u0006 שכבר נשחטה והתקבל דמה בכוס — \u0003סבירא להו\u0004 \u0005[סבורים הם]\u0006 כי \u0003כל העומד ליזרק\u0004 — \u0003כזרוק דמי\u0004 \u0005[נחשב],\u0006 וכאילו כבר התכפרו הבעלים באחרת, ודינה למיתה כדין אבודה שהתכפרו בעליה באחרת.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר: כל \u0003כמה\u0004 (זמן) שעדיין \u0003לא אזדריק\u0004 \u0005[נזרק]\u0006 ה\u0003דם\u0004 — \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אבדה בשעת הפרשה דמיא\u0004 \u0005[נחשבת]\u0006 הבהמה, \u0003ו\u0004דינה איפוא שהיא \u0003רעיא\u0004 \u0005[רועה],\u0006 ולא מתה?","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 הסבר אחד בבעיית רב פפא: \u0003לעולם אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבי\u0004 שאל רב פפא, ו\u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 בעייתו זו — \u0003כגון\u0004 (באופן זה) שלא אבדה בהמת החטאת עצמה, אלא \u0003ש\u0004נשחטה כדינה, ו\u0003קיבל\u0004 הכהן את \u0003דמה בשתי כוסות\u0004 לזריקה על המזבח, \u0003ואבד\u0004 כוס \u0003אחד מהן,\u0004 וזרק מהדם שבכוס השני.","\u0003ואליבא דמאן דאמר\u0004 \u0005[ולשיטת מי שאומר]\u0006 כי \u0003כוס\u0004 שנדחה (כגון כוס זה שאבד) \u0003עושה\u0004 בכך אף את \u0003חבירו\u0004 (הכוס האחר, שביד הכהן) \u0003דחוי\u0004 (מדין הקדשים) — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שכן במקרה שכזה החטאת פסולה. ואולם \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטת מי שאומר]\u0006 כי אין הכוס האחד דוחה את הכוס האחר מן הקדשים, אלא \u0003כוס\u0004 זה \u0003עושה\u0004 את \u0003חבירו שיריים\u0004 (כדין שיירי הדם — הנשפכים אל יסוד המזבח), וכך תישאל השאלה: האם","\u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין הכוס דוחה את חבירו אמורים דווקא \u0003היכא דאיתנהו לתרוייהו, דכל היכא דבעי זריק\u0004 \u0005[היכן,\u0006 במקרה, \u0005ששניהם נמצאים, שכל היכן,\u0006 שאיזה כוס \u0005שרוצה\u0006 הריהו \u0005זורק],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שאבד כוס אחד — \u0003הא ליכא\u0004 \u0005[הרי אין]\u0006 עוד שני כוסות לפנינו, ונדחה הכוס השני. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]?\u0006 ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה, ללא פתרון.","ועוד בדין חטאת שהתכפרו בעליה באחרת. \u0003המפריש\u0004 בהמה ל\u0003חטאת\u0004 שהוא חייב בה, \u0003ואבדה, והפריש אחרת תחתיה,\u0004 והקריבה, \u0003ואחר כך נמצאת\u0004 החטאת \u0003הראשונה\u0004 — הרי זו חטאת שהתכפרו בעליה באחרת, ודינה ש\u0003תמות.\u0004","\u0003המפריש מעות\u0004 כדי לקנות בהמה \u0003לחטאתו, ואבדו\u0004 המעות, ועמד \u0003והפריש\u0004 בהמה ל\u0003חטאת תחתיהם,\u0004 והקריבה, \u0003ואחר כך נמצאו המעות\u0004 — הרי הן אסורות בהנאה, שהרי הן במקום החטאת שהיתה אמורה להיקנות בהן, שדינה שתמות, ו\u0003יוליכם לים המלח\u0004 ויזרקם שם שיילכו בו לאיבוד.","\u0003המפריש מעות ל\u0004צורך קניית \u0003חטאת, ואבדו\u0004 המעות, ועמד \u0003והפריש מעות אחרות תחתיהן, ולא הספיק ליקח\u0004 (לקנות) בהמה ל\u0003חטאת מהן עד שנמצאות\u0004 המעות \u0003הראשונות\u0004 — יערב את המעות הראשונות והשניות ו\u0003יביא מאלו ומאלו חטאת, והשאר,\u0004 העודף, \u0003יפלו ל\u0004קופה שבמקדש, שממנה מביאים עולות \u0003נדבה\u0004 של ציבור.","\u0003המפריש מעות לחטאתו ואבדו, והפריש חטאת תחתיהן,\u0004 ו\u0003לא הספיק להקריבה עד שנמצאו המעות, והרי\u0004 נעשתה בינתיים ה\u0003חטאת בעל מום\u0004 — \u0003תמכר\u0004 החטאת, \u0003ויביא\u0004 הבעלים \u0003מאלו\u0004 (המעות הראשונות שהפריש) \u0003ומאלו\u0004 (המעות שהתקבלו ממכירת החטאת בעלת המום), לאחר שיערבן אלו באלו, \u0003חטאת, והשאר יפלו לנדבה.\u0004","\u0003המפריש\u0004 בהמה ל\u0003חטאת ואבדה,\u0004 ועמד \u0003והפריש מעות תחתיה\u0004 כדי לקנות בהן בהמה לחטאת, \u0003ו\u0004אולם \u0003לא הספיק ליקח\u0004 (לקנות) \u0003מהן חטאת עד שנמצא חטאתו, והרי היא\u0004 נעשתה בינתיים \u0003בעלת מום\u0004 — \u0003תימכר,\u0004 ויערב את המעות שיתקבלו במכירתה ואת המעות הראשונות, \u0003ויביא מאלו ומאלו חטאת, והשאר יפלו לנדבה.\u0004","\u0003המפריש\u0004 בהמה ל\u0003חטאתו ואבדה, והפריש\u0004 בהמה \u0003אחרת תחתיה,\u0004 ו\u0003לא הספיק להקריבה\u0004 לשניה \u0003עד שנמצאת הראשונה,\u0004 ונפל בהן מום, מאחר \u0003והרי\u0004 \u0003שתיהן בעלת מום\u0004 — \u0003ימכרו\u0004 שתיהן, \u0003ויביא מאלו ומאלו\u0004 (מכספי מכירת זו ומכספי מכירת זו) \u0003חטאת, והשאר יפלו לנדבה.\u0004","\u0003המפריש\u0004 בהמה ל\u0003חטאת, ואבדה,\u0004 ועמד \u0003והפריש\u0004 בהמה \u0003אחרת תחתיה,\u0004 ו\u0003לא הספיק להקריבה עד שנמצאת הראשונה, והיו שתיהן תמימות\u0004 (שאין בהן מום), וכשרות שתיהן להקרבה — \u0003אחת מהן תיקרב חטאת, והשניה תמות,\u0004 אלו \u0003דברי רבי. וחכמים\u0004 חולקים ו\u0003אומרים: אין חטאת\u0004 שהתכפרו בעליה באחרת \u0003מתה אלא\u0004 באופן \u0003שנמצאת\u0004 רק \u0003מאחר\u0004 (לאחר) \u0003שכיפרו\u0004 (שהתכפרו) \u0003הבעלים\u0004 באחרת. \u0003ואין המעות הולכים לים המלח אלא\u0004 רק כ\u0003שנמצאו מאחר שכיפרו הבעלים.\u0004","\u0003המפריש\u0004 בהמה ל\u0003חטאת,\u0004 ונפל בה מום, \u0003והרי היא\u0004 עתה \u0003בעלת מום\u0004 הפסולה להקרבה — \u0003מוכרה, ויביא בדמיה אחרת. ר' אלעזר בר' שמעון אומר: אם קרבה\u0004 ה\u0003שניה עד שלא\u0004 (בטרם) \u0003נשחטה\u0004 הראשונה לאכילת חולין — \u0003תמות,\u0004 אף שכבר נמכרה ויצאה בכך לחולין, והריהי עתה ברשות הקונה אותה. וטעם הדבר: \u0003שכבר כיפרו\u0004 (התכפרו) \u0003הבעלים\u0004 באחרת, ואף שיצאה לחולין — אין היא כשאר חולין, אלא הריהי כחטאת שהתכפרו בעליה באחרת, ודינה שתמות.","שנינו בתחילת משנתנו בדינה של החטאת שאבדה ועמד בעליה והקריב אחרת במקומה, ואחר כך נמצאה החטאת הראשונה, שדינה למיתה. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 — משום שעמד ו\u0003הקריב\u0004 את ה\u0003אחרת תחתיה, הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם רק הפריש אחרת ואולם עדיין \u0003לא הקריב\u0004 את ה\u0003אחרת תחתיה\u0004 — דינה שהיא \u0003רועה.\u0004 ומעתה יש לברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]? —\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דאמרי\u0004 \u0005[שאומרים]\u0006 כי החטאת ה\u0003אבודה בשעת הפרשה\u0004 — אינה מתה, אלא \u0003רועה.\u0004","ואולם \u0003אימא\u0004 \u0005[אמור]\u0006 עתה את \u0003סיפא\u0004 \u0005[סוף\u0006 המשנה\u0005]\u0006 בדין \u0003המפריש מעות לחטאת, ואבדו, והפריש אחרים תחתיהם\u0004 — \u0003יביא\u0004 חטאת \u0003מאלו ומאלו, והשאר יפלו לנדבה.\u0004 ונדייק בדברים אלה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 — משום שרק הפריש מעות אחרות ואולם עדיין לא התכפר באף אחד מהם ויש עדיין מעות \u0003מאלו ומאלו, הא\u0004 \u0005[הרי]\u0006 שאם כבר \u0003הביא\u0004 קרבנו \u0003מאחד מהן\u0004 — דינו של \u0003השני\u0004 ש\u0003יוליכו לים המלח,\u0004 והרי \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003רבי\u0004 ש\u0003אמר\u0004 שאף ה\u0003אבודה בשעת הפרשה\u0004 בלבד — \u0003מתה.\u0004","ומעתה יש לתמוה: \u0003רישא רבנן, וסיפא\u0004 \u0005[תחילת\u0006 המשנה כשיטת \u0005חכמים, וסוף\u0006 המשנה\u0005]\u0006 כשיטת \u0003רבי?! הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב הונא,\u0004 שכן \u0003אמר רב הונא, אמר רב:\u0004"],["\u0003הכל\u0004 סבורים, ואף חכמים (הסבורים שאם היתה החטאת אבודה בשעת הפרשה, דינה שהיא רועה) \u0003מודים\u0004 לרבי \u0003שאם\u0004 עמד הבעלים בלא להימלך בבית דין ו\u0003משך\u0004 (לקח) \u0003אחת\u0004 מהן, ואפילו את האבודה, \u0003והקריבה\u0004 והתכפר בה — \u0003שהשניה מתה,\u0004 שכן גילה הבעלים את דעתו שאין זה משנה לו מה ייעשה בשניה. והרי \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 אופן שבו הולמים דברי סוף המשנה אף לשיטת חכמים, ו\u0003כגון ש\u0004מדעת עצמו \u0003משך אחת מהן והקריב, ו\u0004כ\u0003דברי הכל\u0004 היא הלכה זו, שהרי השניה מתה.","\u0003אלא ל\u0004שיטת \u0003ר' אבא אמר רב,\u0004 ש\u0003אמר\u0004 שאפילו אם עמד הבעלים ומשך מדעתו את החטאת האבודה והקריבה, סבורים חכמים שתרעה ולא תמות (שכן חטאת זו מעולם לא נדחתה מהקרבה). וכן \u0003הכל מודים במתכפר ב\u0004חטאת זו \u0003שאינה אבודה\u0004 — \u0003ש\u0004החטאת ה\u0003אבודה מתה. על מה\u0004 איפוא \u0003נחלקו\u0004 רבי וחכמים? — \u0003במתכפר באבודה,\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור]\u0006 שכל ה\u0003מפריש\u0004 קרבן חטאת \u0003לאיבוד\u0004 (במקום קרבן חטאת שאבד) — הרי קרבן זה \u0003כאיבוד\u0004 (כקרבן האבוד) \u0003דמי\u0004 \u0005[דומה,\u0006 נחשב\u0005],\u0006 ולכן, כשם שאם הקריב את החטאת שאינה אבודה — החטאת האבודה מתה, כך גם אם הקריב את החטאת האבודה שנמצאה — זו שאינה אבודה מתה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי הקרבן המופרש תחת הקרבן שאבד — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כאיבוד\u0004 (כקרבן האבוד) \u0003דמי\u0004 \u0005[דומה,\u0006 נחשב\u0005],\u0006 ולכן אם הקריב את האבודה, החטאת שאינה אבודה אינה מתה, אלא רועה.","ומעירים: נמצא איפוא ש\u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005],\u0006 האומרת שאם נמצאה החטאת שאבדה לאחר הקרבת החטאת שהופרשה תחתיה הריהי מתה, ומכאן שאם נמצאה לפני כן — הריהי רועה, והרי בכך \u0003סתם לן\u0004 \u0005[לנו]\u0006 התנא, \u0003כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף,\u0006 בהמשך דברי המשנה\u0005],\u0006 \u0003סתם לן\u0004 \u0005[לנו]\u0006 התנא \u0003כ\u0004שיטת \u0003רבי,\u0004 ושואלים:","\u0003ומאי קמשמע לן\u0004 \u0005[ומה הוא,\u0006 התנא \u0005משמיע לנו]\u0006 בכך — \u0003דפליגי\u0004 \u0005[שחלוקים]\u0006 \u0003רבי ורבנן\u0004 \u0005[וחכמים]\u0006 בדבר זה? והרי \u0003בהדיא קתני לה\u0004 \u0005[במפורש שנינו אותה]\u0006 \u0003מחלוקת\u0004 שבין \u0003רבי ורבנן בסיפא\u0004 \u0005[וחכמים בסוף\u0006 המשנה\u0005]:\u0006 \u0003המפריש חטאת ואבדה, והפריש אחרת תחתיה\u0004 ועדיין לא הקריבה, \u0003ואחר כך נמצאת הראשונה, והרי שתיהן עומדות\u0004 — \u0003אחת מהן תקרב, ושניה תמות.\u0004 אלו \u0003דברי רבי. וחכמים אומרים: אין חטאת מתה אלא\u0004 כ\u0003שנמצאת מאחר שכיפרו בעלים, ואין מעות הולכות לים המלח אלא\u0004 כ\u0003שנמצאו מאחר שכיפרו בעלים!\u0004","ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[זה משמיע לנו]\u0006 כי \u0003דבר זה\u0004 ששנינו קודם לכן כסתירה במשנה \u0003מחלוקת רבי ורבנן\u0004 \u0005[וחכמים]\u0006 הוא.","ומעתה דנים בהלכה זו \u0003גופא\u0004 \u0005[גופה,\u0006 כשלעצמה\u0005],\u0006 \u0003אמר רב הונא, אמר רב\u0004 בהסבר מחלוקת רבי וחכמים: \u0003הכל מודים שאם\u0004 עמד הבעלים על דעת עצמו ו\u0003משך אחת\u0004 מהן, ואפילו את זו שאבדה ונמצאה, \u0003והקריבה\u0004 — \u0003שהשניה מתה. לא נחלקו\u0004 חכמים ורבי \u0003אלא ב\u0004אדם ה\u0003בא לימלך\u0004 (ליטול עצה) מחכמים מה עליו לעשות. ש\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003לא עשו תקנה בקדשים,\u0004 שאין חכמים חוששים שמא מתוך דבריהם יבואו הקדשים למיתה. \u0003ו\u0004לכן \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 לו: \u0003לך התכפר ב\u0004זו \u0003שאינה אבודה,\u0004 שלא נדחתה מהקרבה, \u0003ו\u0004אף שבכך ה\u0003אבודה מתה. ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003עשו תקנה בקדשים,\u0004 שראוי לחכמים לדאוג שלא יבואו קדשים לכלל מיתה. \u0003ו\u0004משום כך \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 לו: \u0003לך התכפר\u0004 דווקא \u0003ב\u0004זו ה\u0003אבודה, ו\u0004על ידי כך זו \u0003שאינה אבודה\u0004 לא תמות, אלא \u0003תרעה.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב משרשיא: ו\u0004האם יש הסבור ש\u0003לא עשו תקנה בקדשים? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על האמור באכילת שיירי המנחות \"והנותרת ממנה יאכלו אהרן ובניו מצות תאכל במקום קדוש בחצר אהל מועד יאכלוה\" (ויקרא ו, ט). ודורשים מלה יתירה זו שבסוף הפסוק \"יאכלוה\": \u0003\"יאכלו\"\u0004 האמור במלה זו, \u0003מה תלמוד לומר\u0004 (מלמדנו)? — \u0003מלמד שאם היתה\u0004 בשיירי המנחה רק כדי \u0003אכילה מועטת,\u0004 שאין בה כשיעור שביעה — \u0003אוכלין עמה חולין ותרומה, כדי ש\u0004בכך \u0003תהא נאכלת על השבע\u0004 (כדי שביעה).","ואילו המלה השלימה, בתוספת ה\"א שבה \u0003\"יאכלוה\", מה תלמוד לומר?\u0004 — מלמד \u0003שאם היתה אכילה מרובה,\u0004 וכגון שיש להם שיירי מנחות רבים — \u0003אין אוכלין עמה חולין ותרומה, כדי שלא תהא\u0004 על ידי כך המנחה \u0003נאכלת על הגסה,\u0004 ועלולה היא, על ידי כך, שלא תיאכל כולה, ותבוא לכלל נותר.","ונסיק איפוא מכאן: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הלכה זו היא \u0003אפילו\u0004 כשיטת \u0003רבי?\u0004 והלא הלכה זו באה כדי לעשות תקנה לקדשים (שלא יבואו לידי נותר), משמע שרבי סבור שעושים תקנה לקדשים! ומשיבים: \u0003לא,\u0004 אין זה כשיטת רבי, אלא כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","\u0003ו\u0004אילו \u0003ר' אבא אמר\u0004 בשם \u0003רב\u0004 הסבר אחר למחלוקת חכמים ורבי: \u0003הכל מודים במתכפר ב\u0004חטאת \u0003שאינה אבודה\u0004 אחר שהפריש בהמה לחטאתו ואבדה והפריש אחרת תחתיה ונמצאה הראשונה — \u0003ש\u0004החטאת ה\u0003אבודה\u0004 \u0003מתה,\u0004 שהרי נדחתה. \u0003על מה נחלקו?\u0004 — כש\u0003מתכפר באבודה,\u0004 ובזאת נחלקו, ש\u0003רבי סבר\u0004 \u0005[סבור]\u0006 שה\u0003מפריש\u0004 חטאת \u0003לאיבוד\u0004 (במקום קרבן אבוד) — אף קרבן זה שלא אבד \u0003כאיבוד\u0004 (כקרבן האבוד) הוא \u0003דמי\u0004 \u0005[דומה,\u0006 נחשב\u0005],\u0006 ולכן גם הוא מומת. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שקרבן שהופרש במקום קרבן אבוד — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כאיבוד\u0004 הוא \u0003דמי\u0004 \u0005[דומה,\u0006 נחשב\u0005],\u0006 ולכן הוא הולך לרעיה.","ושואלים על הסברו זה של ר' אבא בשם רב: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדינם של שעירי יום הכיפורים, שאם לאחר שהוגרלו שני השעירים, מת השעיר שהוגרל לעזאזל, מביאים שני שעירים נוספים, ומגרילים עליהם שוב, והשעיר שהוגרל לעזאזל — יישלח לעזאזל, ואחד מבין שני השעירים שהוגרלו לה' קרב, ו\u0003השני ירעה עד שיסתאב\u0004 (שיפול בו מום), \u0003וימכר, ויפלו דמיו לנדבה.\u0004 וטעם הדבר: משום \u0003שאין חטאת ציבור מתה.\u0004 ומכאן נדייק: כך הוא הדין רק בשעירי יום הכיפורים משום שחטאת ציבור היא, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד שבאופן דומה בחטאת של \u0003יחיד\u0004 — הריהי \u0003מתה.\u0004","\u0003ואמר רב\u0004 על כך: \u0003בעלי חיים\u0004 (הקרבנות בהיותם בחיים) \u0003אינן נידחין,\u0004 ומשום כך, במקרה זה של שתי ההגרלות בשעירי יום הכיפורים, \u0003כשהוא מתכפר\u0004 — אף \u0003ב\u0004שעיר ה\u0003שני שבזוג\u0004 ה\u0003ראשון\u0004 יכול שיהיה \u0003מתכפר,\u0004 ואין אומרים שמאחר שבן זוגו מת הריהו נדחה. \u0003ו\u0004אילו \u0003אידך בתרא\u0004 \u0005[\u0006השעיר \u0005האחר,\u0006 שבזוג \u0005השני]\u0006 שעלה עליו הגורל לה' — \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 נחשב \u0003כמפריש לאיבוד\u0004 (במקום השעיר האבוד, שלא יכול היה להיות מוקרב). \u0003ו\u0004כאמור, \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 כך הוא הדין משום שהוא חטאת \u0003ציבור,\u0004 ואין חטאת ציבור מתה. ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן, כי באופן דומה, ובחטאת של \u0003יחיד\u0004 — הריהי \u0003מתה.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר שמשנה זו היא \u0003אפילו\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שאף הם סבורים כן, הרי שהמופרש תחת קרבן אבוד הריהו כאבוד, אף לדעת חכמים, ושלא כהסברו של ר' אבא בשם רב. ודוחים: \u0003לא,\u0004 אין לדייק כן, שכן משנה זו רק כשיטת \u0003רבי היא,\u0004 ואין להוכיח ממנה לשיטת חכמים. ודנים עוד בהסבריהם של רב הונא ור' אבא (בשם רב) במחלוקת חכמים ורבי.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המפריש חטאת ואבדה,\u0004 והפריש אחרת, \u0003והקריב\u0004 אותה \u0003אחרת תחתיה,\u0004 ולאחר מכן נמצאה החטאת שאבדה — הרי זו \u0003תמות.\u0004 שחטאת שהתכפרו בעליה באחרת, היא מכלל חמש החטאות המתות.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 שהיא מתה — משום \u0003דקריבה\u0004 \u0005[ש\u0006כבר \u0005קרבה]\u0006 החטאת האחרת לפני שנמצאה, \u0003הא\u0004 \u0005[הרי]\u0006 שאם נמצאה החטאת שאבדה כאשר עדיין \u0003לא הקריבה\u0004 את החטאת שהופרשה תחתיה — הדין הוא ש\u0003תרעה.\u0004 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם הוא \u0003מתכפר ב\u0004חטאת ה\u0003אבודה, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם הוא \u0003מתכפר ב\u0004חטאת \u0003שאינה אבודה, לא שנא\u0004 \u0005[אינו שונה]\u0006 הדין אם הוא עצמו \u0003משך\u0004 והקריב את זו, \u0003ולא שנא\u0004 \u0005[אינו שונה]\u0006 הדין אם \u0003לא\u0004 הוא עצמו \u0003משך\u0004 והקריב. בכל האופנים דינה של החטאת השניה שתרעה ולא תמות.","והרי זו איפוא \u0003תיובתא דתרוייהו\u0004 \u0005[קושיה חמורה על שניהם],\u0006 הן להסברו של רב הונא בשם רב המבחין בין עמד ומשך ובין הבא להימלך בבית דין, והן על הסברו של ר' אבא בשם רב המבחין בין אם כבר התכפר בשאינה אבודה לבין אם התכפר באבודה.","ומשיבים: אין לדייק כן מדברי המשנה, משום ש\u0003מילתא דפסיקא ליה\u0004 \u0005[דבר שפסוק,\u0006 ברור \u0005לו\u0006 לתנא\u0005]\u0006 שאין בו חילוקי דינים — \u0003קתני\u0004 \u0005[הוא שונה],\u0006 כהלכה זו שאם הקריב כבר את החטאת שהופרשה תחת החטאת שאבדה, ולאחר מכן נמצאה החטאת שאבדה, שדין החטאת האבודה למיתה. \u0003ו\u0004אילו \u0003מילתא דלא פסיקא ליה\u0004 \u0005[דבר שלא פסוק,\u0006 ברור \u0005לו],\u0006 כגון חילוקי הדינים היוצאים מדברי רב הונא (משך, או בא להמלך), ור' אבא (נתכפר באבודה, או בשאינה אבודה) — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","ושבים ומקשים מדיוק משנתנו: \u0003תנן\u0004 \u0005[שנינו\u0006 בה\u0005]:\u0006 \u0003המפריש מעות לחטאת, ואבדו, והפריש\u0004 מעות \u0003אחרים תחתיהם, ואחר כך,\u0004 לפני שלקח במעות האחרות חטאת, \u0003נמצאו המעות\u0004 הראשונות שאבדו — יערב את המעות הראשונות והשניות, ו\u0003יביא מאלו ומאלו חטאת, והשאר\u0004 (יתרת הכסף) \u0003יפלו\u0004 \u0003ל\u0004קרבן \u0003נדבה.\u0004","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 להלכה זו שהריהו יכול להיות \u0003מתכפר מאלו ומאלו\u0004 — משום שעדיין לא התכפר באחד מהמעות הללו. ונסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם כבר התכפר \u0003מאחד\u0004 מהם — \u0003יוליכם\u0004 את האחרות \u0003לים המלח.\u0004","\u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 דין זה אם הוא \u0003מתכפר ב\u0004מעות ה\u0003אבודה, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם הוא \u0003מתכפר ב\u0004מעות \u0003שאינה אבודה, לא שנא\u0004 \u0005[אינו שונה]\u0006 הדין אם הוא מדעתו עמד ו\u0003משך\u0004 והקריב את זו, \u0003ולא שנא\u0004 \u0005[אינו שונה]\u0006 הדין אם \u0003לא\u0004 עמד ו\u0003משך\u0004 והקריב. בכל האופנים הרי דינן של המעות האחרות להולכה לים המלח. והרי זה איפוא \u0003תיובתא דתרוייהו\u0004 \u0005[קושיה חמורה על שניהם],\u0006 הן להסברו של רב הונא והן על הסברו של ר' אבא! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נשיב באותו אופן שהשבנו על השאלה הקודמת: \u0003מילתא דפסיקא ליה\u0004 \u0005[דבר שפסוק,\u0006 שברור \u0005לו\u0006 לתנא\u0005]\u0006 שאין בו חילוקי דינים — \u0003קתני\u0004 \u0005[הוא שונה],\u0006 כהלכה זו במקרה שהקריב כבר חטאת באחת מקבוצות המעות, \u0003ו\u0004אילו \u0003מילתא דלא פסיקא ליה\u0004 \u0005[דבר שלא פסוק,\u0006 ברור \u0005לו],\u0006 כגון במקרה שעדיין לא הקריב — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","ועוד בענין המפריש מעות לחטאתו, \u0003אמר ר' אמי: המפריש שני ציבורי מעות ל\u0004צורך קרבן חטאתו ב\u0003אחריות,\u0004 שאם יאבד ציבור אחד של המעות, יביא את קרבנו מהשני — הריהו \u0003מתכפר ב\u0004מעות שב\u0003אחד מהן, ו\u0004המעות שב\u0003שני\u0004 \u0003יפלו ל\u0004קרבן \u0003נדבה.\u0004","ודנים בדבריו: \u0003אליבא דמאן\u0004 \u0005[לשיטת מי]\u0006 אמר ר' אמי הלכה זו, \u0003אילימא אליבא\u0004 \u0005[אם תאמר לשיטת]\u0006 \u0003רבי\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שלדעתו במקרה זה המעות \u0003יפלו לנדבה.\u0004 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבי\u0004 שהמעות האחרות הולכות לים המלח \u0003אלא במפריש\u0004 מעות \u0003לאיבוד\u0004 (במקום מעות ראשונות אבודות), \u0003אבל\u0004 במקרה שהפריש מראש מעות אחרות רק \u0003ל\u0004צורך \u0003אחריות\u0004 — \u0003מודה\u0004 רבי שאין הן הולכות לים המלח, אלא נופלות לקרבן נדבה.","\u0003ואלא\u0004 תאמר כי אמר זאת \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים]\u0006 — אף זה \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003יפלו לנדבה,\u0004 שהרי \u0003קל וחומר\u0004 הוא זה: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ב\u0003מפריש\u0004 מעות \u0003לאיבוד אמור רבנן לאו\u0004 \u0005[אמרו חכמים\u0006 כי המעות הללו \u0005לא]\u0006 \u0003כאיבוד\u0004 הוא \u0003דמי\u0004 \u0005[דומה,\u0006 נחשב\u0005],\u0006 ואין המעות הולכות לים המלח, המפריש מעות \u0003לאחריות מיבעיא\u0004 \u0005[נצרך]\u0006 לומר שאין המעות הולכות לים המלח?!","\u0003ואלא\u0004 יש לומר כי \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' שמעון איצטריכא ליה\u0004 \u0005[נצרך לו,\u0006 לר' אמי\u0005]\u0006 להשמיענו. שכן סבור ר' שמעון שחטאת שהתכפרו בעליה באחרת שדינה שהיא מתה בכל מקרה, אף אם חטאת זו הופרשה רק לצורך אחריות, כיון שהתכפרו הבעלים באחרת. שכן \u0003מהו דתימא לית ליה\u0004 \u0005[מהו,\u0006 היה מקום \u0005שתאמר\u0006 כי \u0005אין לו,\u0006 אינו סבור\u0005]\u0006 \u0003ר' שמעון\u0004 שכאשר הפריש מעות לאחריות והתכפר באחרות שהמעות שלא התכפר בהן יפלו ל\u0003נדבה,\u0004 אלא לדעתו אף אלה הולכות לים המלח, לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' אמי, \u0005משמיע לנו]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שסבור ר' שמעון\u0005]\u0006 שבמקרה זה הולכות הן ל\u0003נדבה.\u0004","ושואלים על הסבר זה: \u0003ומי מצית אמרת דלית ליה\u0004 \u0005[והאם יכול אתה לומר,\u0006 להעלות זאת כאפשרות, \u0005שאין לו],\u0006 הלכה זו של נפילה ל\u0003נדבה ל\u0004שיטת \u0003ר' שמעון? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא (משנה)\u0005]\u0006 במסכת שקלים: \u0003שלשה עשר שופרות\u0004 (קופות צדקה שצורתן כשופר) \u0003היו ב\u0004עזרה שבבית ה\u0003מקדש, והיה כתוב עליהן,\u0004 על כל אחת מהן, לצורך מה הכסף הניתן בו. על האחד היה כתוב \u0003\"תיקלין חדתין\"\u0004 \u0005[שקלים חדשים],\u0006 שבהם היו נותנים את השקלים (מחצית השקל) שהביאו בשנה זו; \u0003ו\u0004על אחר היה כתוב שנועד ל\"תקלין \u0003עתיקין\"\u0004 \u0005[\u0006שקלים \u0005עתיקים,\u0006 ישנים\u0005],\u0006 של השנה שעברה, שלא הגיעו לתעודתם בזמנם. ועל אחר היה כתוב \u0003\"קינין\",\u0004 ונועד לקרבנות חובה של זוג תורים או בני יונה (לזב, זבה, יולדת ומצורע); \u0003ו\u0004על אחד היה כתוב: \u0003\"גוזלי עולה\",\u0004 עבור נדבת עולת העוף; ועל האחר היה כתוב \u0003\"עצים\",\u0004 למנדב עצים למערכה על המזבח; \u0003ו\u0004על האחר היה כתוב \u0003\"לבונה\",\u0004 למנדב לבונה הבאה עם המנחה; \u0003ו\u0004על האחר היה כתוב \u0003\"זהב לכפרת\",\u0004 למי שנדב זהב למקדש. \u0003ו\u0004עוד \u0003ששה\u0004 שופרות, ששימשו \u0003ל\u0004קניית בהמות לעולות \u0003נדבה.\u0004","\u0003ותני עלה\u0004 \u0005[ושנינו עליה\u0006 ברייתא\u0005]\u0006 המרחיבה את דברי המשנה הללו: \u0003ששה\u0004 שופרות אלה שהכסף שניתן בהם נועד \u0003ל\u0004עולות \u0003נדבה\u0004 — הכוונה היא \u0003לעולה הבאה מן המותרות,\u0004 שנשאר מהכסף שהופרש לצורך קניית חטאת או אשם, ובכסף זה מביאים עולה ל\"קיץ המזבח\", שמקריבים עליו בזמן שאין עליו קרבנות אחרים, על מנת שלא יהיה פנוי מהקרבה, ודינה \u0003שאין עורה\u0004 ניתן \u0003לכהנים,\u0004 כשאר עולות, אלא חוזרים ומוכרים אותו, ודמיו נופלים לנדבה, ל\"קיץ המזבח\". אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' נחמיה, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים\u0006 כי היה זה\u0005]\u0006 \u0003ר' שמעון: אם כן, בטלה מדרשו של יהוידע הכהן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 במשנה שם\u0005],\u0006 \u0003זה\u0004 ה\u0003מדרש דרש יהוידע הכהן\u0004 הגדול (בימי יהואש המלך) על הכתוב בפרשת הקרבנות בקרבן האשם: \u0003\"אשם הוא\u0004 אשם אשם לה'\" (ויקרא ה, יט). ונמצא בכתוב זה כעין סתירה, שהרי הלשון בתחילת הפסוק \"אשם הוא\" מורה שהוא אשם, ואשמות נאכלים לכהנים. ואילו הלשון שבסוף הפסוק \"אשם לה'\" מורה ש\u0003כולו\u0004 לה', כקרבן עולה! אלא יש בכתוב זה \u0003להביא\u0004 (לרבות) \u0003כל דבר הבא ממותר\u0004 דמי קרבנות \u0003חטאות ו\u0004כן ממותר דמי קרבנות \u0003אשמות\u0004 שיש \u0003ליקח\u0004 (לקנות) \u0003בדמיו עולות,\u0004 ודינם של עולות אלה ש\u0003הבשר\u0004 — כולו \u0003לשם\u0004 על המזבח, \u0003ו\u0004אילו ה\u0003עורות\u0004 — ניתנים \u0003לכהנים,\u0004 כדין כל העולות.","\u0003אלמא\u0004 \u0005[הרי נסיק]\u0006 כי \u0003אית ליה\u0004 \u0005[יש לו]\u0006 דין זה שמותר חטאת הריהו הולך לעולת \u0003נדבה לר' שמעון,\u0004 ואין איפוא צורך להשמיענו כי אף ר' שמעון סבור כן, כדרך שאמר ר' אמי בדין המפריש שתי קבוצות מעות לאחריות חטאתו! ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 ר' אמי להשמיענו כן, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך]\u0006 לומר: \u0003כי אית ליה\u0004 \u0005[כאשר יש לו]\u0006 דין זה של מותר חטאת שהולך לעולת \u0003נדבה לר' שמעון\u0004 — הרי זה דווקא \u0003בחד סידרא\u0004 \u0005[בסדרה אחת]\u0006 של מעות, וכגון זה המפריש קבוצת מעות אחת לצורך קרבן חטאתו, ולאחר מכן הוזלו הקרבנות, ונותרו בידו מעות — הרי מותר זה מופנה לעולת נדבה, ודינו כשאר העולה,"],["\u0003אבל בתרי סדרי\u0004 \u0005[בשני סדרים,\u0006 בשתי קבוצות של מעות\u0005], —\u0006 \u0003לא,\u0004 לכן בא ר' אמי ו\u0003קא משמע לן\u0004 \u0005[\u0006ו\u0005הוא משמיע לנו]\u0006 שאף באופן זה של שני ציבורי מעות סבור ר' שמעון שהמותר ניתן לעולת נדבה.","\u0003אמר ר' הושעיא: המפריש שתי חטאות\u0004 לחובתו, שהשניה תהא \u0003לאחריות,\u0004 שאם תאבד האחת, תוקרב השניה תחתיה — הריהו מביא קרבן ו\u0003מתכפר באחת מהן, וחבירתה\u0004 אינה מתה, אלא \u0003רועה\u0004 עד שיפול בה מום, ותימכר, ויפלו דמיה לעולת נדבה.","ודנים בדברי ר' הושעיא: \u0003אליבא דמאן\u0004 \u0005[לשיטת מי]\u0006 אמר זאת ר' הושעיא? \u0003אילימא אליבא דרבנן\u0004 \u0005[אם תאמר\u0006 ש\u0005לשיטת חכמים]\u0006 — \u0003השתא\u0004 \u0005[עכשיו]\u0006 אפילו במקרה של \u0003המפריש\u0004 חטאת \u0003לאיבוד\u0004 (תחת חטאת שאבדה) \u0003אמרי רבנן לאו\u0004 \u0005[אמרו חכמים\u0006 ש\u0005לא]\u0006 \u0003כאיבוד\u0004 (כחטאת האבודה) \u0003דמי\u0004 \u0005[דומה,\u0006 נחשבת\u0005]\u0006 החטאת שהופרשה תחתיה, ולכן אינה מתה אלא רועה. זה המפריש מלכתחילה חטאת נוספת \u0003ל\u0004צורך \u0003אחריות מיבעיא\u0004 \u0005[נצרך]\u0006 לומר לדעת חכמים שאינה מתה?!","\u0003אלא\u0004 תאמר כי \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' שמעון\u0004 אמר זאת ר' הושעיא — והרי ר' שמעון אינו סבור כן, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0005ר' שמעון: חמש חטאות\u0006 \u0003מתות,\u0004 ובכללן החטאת שהתכפרו בעליה באחרת, ואף זו שהופרשה לאחריות והתכפרו בעליה בחבירתה! \u0003אלא\u0004 יש לומר כי \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבי\u0004 אמר זאת ר' הושעיא. שכן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר רבי\u0004 שהחטאת שהופרשה תחת החטאת האבודה הריהי מתה — הרי זה דווקא בחטאת המופרשת \u0003באיבוד\u0004 (במקום חטאת אבודה), \u0003אבל\u0004 במקרה זה של המפריש חטאת נוספת לצורך \u0003אחריות\u0004 — \u0003לא\u0004 אמר רבי שהשניה מתה.","","ומקשים על הסבר זה: \u0003תנן\u0004 \u0005[שנינו\u0006 בסוף משנתנו\u0005]:\u0006 \u0003המפריש\u0004 בהמה ל\u0003חטאת, והרי היא\u0004 עתה \u0003בעלת מום,\u0004 שלאחר שהפרישה נפל בה מום, ופסולה להקרבה — הרי זה \u0003מוכרה,\u0004 ויוצאת לחולין, \u0003ומביא\u0004 בדמיה בהמה \u0003אחרת תחתיה. ר' אלעזר בר' שמעון אומר: אם קרבה\u0004 הבהמה ה\u0003שניה\u0004 לחטאתו, \u0003קודם שנשחטה\u0004 הבהמה ה\u0003ראשונה\u0004 ועדיין היא קיימת — הרי הראשונה, אף שיצאה לחולין במכירתה, והיא עתה ברשות הקונה — \u0003תמות.\u0004 וטעם הדבר: מפני \u0003שכבר כיפרו בעליה,\u0004 והריהי איפוא כחטאת שהתכפרו בעליה באחרת, שדינה למיתה. ונדון בשיטתו זו של ר' אלעזר בר' שמעון: \u0003קא סלקא דעתך\u0004 \u0005[היה עולה על דעתך]\u0006 לומר כי \u0003ר' אלעזר בר' שמעון כרבי\u0004 האומר שהקרבתה של החטאת האחת, גורמת דין מיתה לחטאת האחרת, בכל מקרה \u0003סבירא ליה\u0004 \u0005[הריהו סבור].\u0006 ואף זו, אף שיצאה לחולין, כיון שהחטאת האחרת קרבה — הריהי מתה. \u0003ו\u0004מכאן נאמר ש\u0003אפילו ב\u0004אופן זה, במפריש מלכתחילה לצורך \u0003אחריות נמי\u0004 \u0005[גם כן]\u0006 יש לומר שכיון שקרבה האחת — השניה מתה. נמצא שר' הושעיא לא אמר דבריו לשיטת רבי!","","ומשיבים: \u0003לא,\u0004 אין הכרח לומר שר' אלעזר בר' שמעון סבור כשיטת רבי, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' אלעזר בר' שמעון כאבוה סבירא ליה\u0004 \u0005[כאביו סבור הוא],\u0006 ש\u0003אמר\u0004 ר' שמעון: \u0003חמש חטאות מתות\u0004 ולא חילק בדבריו, משמע שאף במקרה שנמכרה הבהמה ויצאה לחולין, כיון שנתכפר באחרת הריהי מתה לשיטת ר' שמעון.","ומקשים עוד על דברי ר' הושעיא: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדינם של שני שעירי יום הכיפורים, שאם מת השעיר לעזאזל — מביאים זוג אחר של שעירים, ומגרילים עליהם. והשעיר שעלה עליו הגורל לעזאזל, נשלח לשם, ואילו מבין שני השעירים לה' (מהזוג הראשון ומהזוג השני) — אחד מהם יוקרב לעבודת היום במקדש, והשני ירעה עד שיפול בו מום, וימכר, ויפלו דמיו לנדבה. ומסבירה המשנה: אין השעיר השני הולך למיתה (כחטאות המתות), \u0003לפי שאין חטאת צבור מתה.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד, שבמקרה דומה, אם היתה זו חטאת של \u0003יחיד\u0004 — הריהי \u0003מתה.\u0004 וכיון שלא נאמר במשנה מי משני השעירים לה' הולך לרעיה, האם זה שנותר מההגרלה הראשונה, או זה מההגרלה השניה, נחלקו בכך אמוראים.","\u0003אמר רב: בעלי חיין אינן נידחין,\u0004 שבעל חיים שהוקדש ולא יכלו להקריבו בזמנו, אינו נחשב כדחוי לעולם ופסול, אלא ישתמשו בו בזמן שיהא שוב ראוי. ולכן \u0003כשהוא מתכפר\u0004 — \u0003ב\u0004שעיר ה\u0003שני שבזוג ראשון\u0004 שעלה עליו הגורל לה' הריהו \u0003מתכפר.\u0004 ונדון בדבר: השעיר לה' שבזוג הראשון הוא הקרב, \u0003ו\u0004אילו \u0003אידך\u0004 \u0005[האחר,\u0006 השעיר לה' שבזוג השני\u0005],\u0006 \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 כזה המופרש ל\u0003אחריות,\u0004 שהרי אינו כמפריש תחת שעיר אבוד (שהרי השעיר לה' שבזוג הראשון לא אבד), \u0003וקתני\u0004 \u0005[ושנינו]\u0006 בדינו של שעיר זה, שאם היתה זו חטאת ה\u0003יחיד\u0004 — הריהי \u0003מתה.\u0004 ושלא כדברי ר' הושעיא שהמפריש שתים לאחריות — אין השניה מתה!","ומשיבים: אין להקשות מדברי רב אלו, משום ש\u0003רב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: מצוה\u0004 להקריב \u0003ב\u0004קרבן ה\u0003ראשון\u0004 שהופרש. ונמצא שכאשר הפריש את השעיר לה' השני, מלכתחילה היה זה על מנת שילך לאיבוד. ואין זה כמפריש שתי בהמות לאחריות, שהרי אז יכול להקריב לכתחילה איזה מהן שירצה. ומשום כך, אף כשקרבה האחת — אין השניה מתה, אלא רועה.","ועוד בענין מחלוקת רבי וחכמים, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שימי בר\u0004 \u0005[בן]\u0006 \u0003זירי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא\u0004 ברייתא זו: כאשר החטאת הראשונה \u0003אבדה\u0004 כבר \u0003בשעת הפרשה\u0004 של החטאת השניה, ולפני שנתכפר בשניה נמצאה הראשונה, נחלקו בכך רבי וחכמים, \u0003ל\u0004דעת \u0003רבי\u0004 — השניה \u0003מתה,\u0004 ו\u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — השניה \u0003תרעה.\u0004 ואולם אם \u0003אבדה\u0004 (היתה אבודה) החטאת אף \u0003בשעת כפרה,\u0004 ורק לאחר מכן נמצאה הראשונה — \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — השניה \u0003מתה,\u0004 ואילו \u0003ל\u0004דעת \u0003רבי\u0004 — השניה \u0003רועה.\u0004","אמר לו רב פפא לרב שימי בר זירי: אין זה כדבריך, שהרי \u0003קל וחומר\u0004 הוא: \u0003ומה\u0004 במקרה שהיתה החטאת \u0003אבודה\u0004 רק \u0003בשעת הפרשה דאמרי רבנן\u0004 \u0005[שאמרו חכמים]\u0006 שהשניה \u0003רועה,\u0004 ועל כך חלק ו\u0003אמר רבי\u0004 שהיא \u0003מתה.\u0004 במקרה שהיתה \u0003אבודה בשעת כפרה, דלרבנן\u0004 \u0005[ש\u0006אף \u0005ל\u0006שיטת \u0005חכמים]\u0006 הריהי \u0003מתה, ל\u0004שיטת \u0003רבי לא כל שכן\u0004 שהיא מתה!","\u0003אלא תני הכי\u0004 \u0005[שנה כך]\u0006 את הברייתא שלפניך: היתה \u0003אבודה בשעת הפרשה,\u0004 ואחר כך נמצאה, \u0003ל\u0004דעת \u0003רבי\u0004 — הריהי \u0003מתה, ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — הריהי \u0003רועה.\u0004 ואולם אם היתה אבודה \u0003בשעת כפרה\u0004 — ל\u0003דברי הכל\u0004 הריהי \u0003מתה.\u0004 שנינו במשנתנו בדין המפריש חטאת ולאחר מכן נפל בה מום, ועמד ומכרה, והביא בדמיה חטאת אחרת וקרבה החטאת האחרת, שחכמים אומרים שאין בכך כלום, והבהמה הראשונה הריהי חולין, ואילו \u0003ר' אלעזר בר' שמעון אומר\u0004 שאם קרבה השניה לפני שנשחטה הראשונה לאכילת חולין, למרות שיצאה לחולין הריהי מתה, שהיא כחטאת שהתכפרו בעליה באחרת.","","ומביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אף ששוחטים ביום טוב ומפשיטים את עור הבהמה — \u0003אין מרגילין ביום טוב,\u0004 כלומר, אין מפשיטים את עור הבהמה דרך הרגליים, כדי שיישאר שלם, על מנת להשתמש בו כחמת. \u0003כיוצא בו: אין מרגילין\u0004 כלל, ואף לא ביום חול, \u0003בבכור,\u0004 ואפילו הוא בעל מום, \u0003ו\u0004כן \u0003לא\u0004 מרגילים \u0003בפסולי המוקדשין\u0004 שנפדו ונשחטו לחולין, מפני שיש בכך בזיון לבהמת קדשים.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 הלכה זו ש\u0003ביום טוב\u0004 אין מרגילים — וטעם הדבר: משום \u0003דקא טרח טירחא דלא חזי ליה\u0004 \u0005[שהוא טורח טירחה שאינה ראויה לו,\u0006 ליום טוב עצמו\u0005],\u0006 והרי הלכה זו הריהי כדעת הכל. \u0003אלא\u0004 הלכה זו שאין מרגילים ב\u0003בכור\u0004 — \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן?","\u0003אמר רב חסדא:\u0004 שיטת \u0003בית שמאי היא,\u0004 ש\u0003אומר:\u0004 ה\u0003בכור,\u0004 גם אם נפל בו מום — \u0003בקדושתיה קאי\u0004 \u0005[בקדושתו\u0006 הוא \u0005עומד],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת בכורות\u0005],\u0006 \u0003בית שמאי אומר: לא ימנה\u0004 (יטול מנה, ישתתף) \u0003ישראל עם הכהן על\u0004 אכילת בשר \u0003הבכור\u0004 בעל המום. ובית הלל מתירים לישראל לאכול מבשר הבכור הזה, ואפילו מתירים הם להאכילו לגוי. הרי שסבורים בית שמאי כי עדיין קדושת בכור עליו, אף שנפל בו מום, ולכן לדעתם אף אסור להרגילו.","ומוסיפים ומבררים: ב\u0003פסולי המוקדשין, מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסבור כך? \u0003אמר רב חסדא:\u0004 כשיטת ר' אלעזר בר' שמעון היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היו לפניו שתי חטאות,\u0004 כאשר אחת מהן לאחריות, שאם תמות או תאבד האחת יתכפר בשניה. והיתה \u0003אחת\u0004 מהן \u0003תמימה\u0004 (ללא מום) \u0003ואחת\u0004 נפל בה מום לאחר שהקדישה, והריהי עתה \u0003בעלת מום.\u0004 מה יעשה בהן? ה\u0003תמימה\u0004 — \u0003תקרב\u0004 לחטאתו, והשניה שהיא \u0003בעלת מום\u0004 — \u0003תפדה.\u0004","\u0003נשחטה בעלת\u0004 ה\u0003מום\u0004 לאחר פדיונה, אם נשחטה \u0003עד שלא\u0004 (בטרם) \u0003נזרק דמה של\u0004 ה\u0003תמימה\u0004 על המזבח לכפרה — הרי היא \u0003מותרת\u0004 בהנאה. ואולם אם נשחטה \u0003משנזרק דמה של תמימה\u0004 על המזבח — הריהי \u0003אסורה\u0004 בהנאה, כדין חטאת שהתכפרו בעליה באחרת. \u0003ר' אלעזר בר' שמעון אמר: אפילו\u0004 נשחטה בעלת המום, וכבר \u0003בשר בעלת\u0004 ה\u0003מום\u0004 מונח \u0003בקדירה, ו\u0004רק אחר כך \u0003נזרק דמה של תמימה\u0004 על המזבח — בשר בעלת המום אסור, והריהו \u0003יוצא ל\u0004הישרף ב\u0003בית השריפה,\u0004 כדין הקדשים שנפסלו. מפני שעדיין שם \"חטאת\" עליה. הרי שהוא סבור שפסולי המוקדשים נשארה בהם קדושה ראשונה, אפילו לאחר שחיטה, ומשום כך הריהו גם אוסר להרגיל אותם. \u0003ו\u0004שואלים: מדוע \u0003רב חסדא\u0004 העמיד את ההלכה שאין מרגילים את הבכור כשיטת בית שמאי, ואת ההלכה שאין מרגילים בפסולי המוקדשים כשיטת ר' אלעזר בר' שמעון, \u0003לוקמה אידי ואידי\u0004 \u0005[שיעמיד\u0006 את \u0005זה ו\u0006את \u0005זה]\u0006 \u0003כ\u0004שיטת \u0003בית שמאי,\u0004 וכדין בכור בעל מום, כן דין פסולי המוקדשים!","","","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לחלק ולומר: \u0003כי אמרי\u0004 \u0005[כאשר אמרו]\u0006 \u0003בית שמאי\u0004 את דינם בבעל מום, שאין קדושתו פוקעת ממנו ואסור לנהוג בו כבחולין — הרי זה דווקא \u0003בבכור,\u0004 משום \u0003דקדושתיה\u0004 \u0005[שקדושתו]\u0006 היא \u0003מרחם\u0004 אמו (משעה שנולד), \u0003אבל\u0004 ב\u0003פסולי המוקדשין\u0004 האחרים שאין קדושתם מרחם — \u0003לא\u0004 אמרו כן בית שמאי. וסבורים הם שמשעה שהותרו בשחיטה — שוב אין בהם קדושה, ומותר להרגילם.","ושואלים לצד האחר: \u0003ולוקמא אידי ואידי\u0004 \u0005[ושיעמיד\u0006 רב חסדא את \u0005זה ו\u0006את \u0005זה,\u0006 בכור ופסולי המוקדשין\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר בר' שמעון\u0004, וכדין פסולי המקודשין דין הבכור!","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לומר כך: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' אלעזר בר' שמעון\u0004 את דינו שהריהם עומדים בקדושתם, ואפילו אחרי שנפדו ונשחטו והונחו בקדירה — הרי זה דווקא \u0003ב\u0004שאר \u0003פסולי\u0004 ה\u0003מוקדשין,\u0004 ורק באלה אכן גם נוהג הדין שאין להרגילם. וטעם הדבר? משום \u0003דאלימי למיתפס\u0004 \u0005[ש\u0006הם \u0005תקיפים\u0006 בקדושתם עד כדי \u0005לתפוס]\u0006 את \u0003פדיונן\u0004 בקדושה. \u0003אבל בבכור\u0004 בעל מום, שלא ניתן לפדותו — \u0003לא\u0004 אמר כן ר' אלעזר בר' שמעון, ומותר להרגיל בו. ושואלים: \u0003ו\u0004כי \u0003ר' אלעזר בר' שמעון, לית ליה הא דתנן\u0004 \u0005[אין לו,\u0006 אינו מקבל דין \u0005זה ששנינו]\u0006 במשנה במסכת בכורות באין חולק ש\u0003כל פסולי המוקדשין\u0004 הריהם \u0003נשחטין באיטליז\u0004 (במקום השוק), \u0003ונמכרין באיטליז,\u0004 שם מרובים הקונים, ומחירם גבוה, \u0003ונשקלין בליטרא\u0004 (משקל), כדרך ששוקלים בשר רגיל, ואין אומרים שיש בכל זה משום זלזול בקדשים. \u0003אלמא\u0004 \u0005[הרי]\u0006 ש\u0003כיון דשרית ליה\u0004 \u0005[שהתרת לו]\u0006 לעשות כן, הריהו בכך \u0003טפי וזבין\u0004 \u0005[\u0006יכול \u0005להרבות\u0006 במחיר \u0005ולמכור]\u0006 ונמצא על ידי כך ההקדש מרויח. והרי איפוא שמותר לנהוג מנהג חולין בפסולי המוקדשים. ומדוע לא יתיר להרגיל בהם לאחר פדיונם? והרי על ידי כך ירויח ההקדש, שיפדו אנשים את הפסולים במחיר גבוה יותר!","","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 לא הותר הדבר, משום ש\u0003מה שמשביח בעור\u0004 על ידי שמפשיט אותו בשלימות — הריהו \u0003פוגם בבשר.\u0004 שכן בכך מקצת הבשר הולך לאיבוד, וההיתר אם כן להרגיל אינו מעלה בכך את ערך הבהמה כולה.","\u0003אמרי במערבא משמיה\u0004 \u0005[אמרו בארץ ישראל בשמו]\u0006 של \u0003ר' אבין\u0004 טעם אחר לאיסור להרגיל בפסולי המוקדשים: \u0003מפני שנראה כעובד עבודה בקדשים,\u0004 והרי אסור לעבוד בפסולי המוקדשים. \u0003ר' יוסי בר אבין אמר\u0004 הסבר אחר: \u0003גזירה שמא\u0004 ימתין לשוחטם עד שימצא מי שיצטרך לעור זה, ובתוך כך \u0003יגדל מהם עדרים עדרים,\u0004","",""],["\u0003כיצד\u0004 (באיזה אופן) הבעלים \u0003מערימין\u0004 (רשאים להתחכם) \u0003על הבכור,\u0004 להפקיעו מהחובה להינתן לכהן, ובמקום זה להשתמש בו לצורך קרבן אחר שהם חייבים בו? — הבהמה ה\u0003מבכרת\u0004 (שטרם ילדה עד כה, והולד הראשון שיוולד לה הריהו איפוא בכור), בעת \u0003שהיתה\u0004 עדיין \u0003מעוברת, אומר\u0004 הבעלים: \u0003\"מה שבמעיה של זו, אם\u0004 הוא \u0003זכר\u0004 — הריהו מוקדש לקרבן \u0003עולה\".\u0004 ואם אכן \u0003ילדה\u0004 הבהמה \u0003זכר\u0004 — אין הוא קדוש בקדושת בכור, אלא בקדושת עולה, ו\u0003יקרב\u0004 כקרבן \u0003עולה. ואם\u0004 אמר הבעלים על הבהמה המעוברת: \"מה שבמעיה של הבהמה זו אם הוא \u0003נקבה\u0004 — הריהו מוקדש ל\u0003זבחי שלמים\",\u0004 אם \u0003ילדה\u0004 הבהמה \u0003נקבה\u0004 — הרי זו \u0003תקרב\u0004 כקרבן \u0003שלמים.\u0004","ואם אמר הבעלים על הבהמה המעוברת: \u0003\"אם\u0004 העובר שבמעיה \u0003זכר\u0004 — הריהו מוקדש ל\u0003עולה, ואם\u0004 הוא \u0003נקבה\u0004 — הריהו מוקדש ל\u0003זבחי שלמים\",\u0004 אם \u0003ילדה\u0004 הבהמה \u0003זכר ונקבה, הזכר\u0004 — \u0003יקרב עולה, והנקבה\u0004 — \u0003תקרב שלמים.\u0004 ואם \u0003ילדה שני זכרים\u0004 — חלה קדושת עולה על שניהם, ואולם מאחר שלא נדר אלא קרבן עולה אחד, \u0003אחד מהם\u0004 — אכן \u0003יקרב עולה\u0004 כנדרו, \u0003ו\u0004אילו \u0003השני\u0004 — \u0003ימכר ל\u0004אחרים שהם \u0003חייבי עולה,\u0004 ויקרב כעולה לחובתם, \u0003ודמיו\u0004 הריהם \u0003חולין.\u0004","ואם \u0003ילדה שתי נקבות\u0004 — \u0003אחת מהם תקרב\u0004 כקרבן \u0003שלמים, ו\u0004אילו \u0003השניה תימכר ל\u0004מי שהם \u0003חייבי\u0004 קרבן \u0003שלמים, ודמיה\u0004 הריהם \u0003חולין.\u0004 ואם \u0003ילדה טומטום\u0004 (זה שאין מינו נודע) \u0003ואנדרוגינוס\u0004 (שיש בו סימני הזכר והנקיבה), והרי שני אלה פסולים לקרבן — \u0003רבן שמעון בן גמליאל אומר: אין קדושה חלה עליהן.\u0004","שנינו במשנה בדין הבכור קודם שיצא ממעי אמו, ובענין זה \u0003אמר רב יהודה: מותר להטיל מום בבכור קודם שיצא לאויר העולם,\u0004 שהרי טרם התקדש בקדושת הבכור. ומקשים עליו: \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, כי \u0003אומר אדם\u0004 (הבעלים) על הבהמה המבכרת: \u0003\"מה שבמעיה של\u0004 בהמה \u0003זו\u0004 יהיה לקרבן \u0003עולה\".\u0004 ונדייק מכאן: רק כאשר הוא מקדיש את הולד בקדושת \u0003עולה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר להפקיעו מקדושת בכור, מפני שקדושת עולה חמורה מקדושת בכור, אבל להקדישו בקדושה קלה וכגון בקדושת \u0003שלמים\u0004 — \u0003לא\u0004 מותר הדבר. \u0003ו\u0004אילו \u0003את\u0004 \u0005[אתה]\u0006 \u0003אמרת דמצית מפקעת ליה\u0004 \u0005[אומר אתה שיכול\u0006 הבעלים \u0005להפקיע אותו]\u0006 \u0003מקדושתה\u0004 מכל וכל, במום שיטיל בו קודם שיצא לאויר העולם?","\u0003אמר\u0004 \u0005[יכול לומר,\u0006 להשיב\u0005]\u0006 \u0003לך רב יהודה\u0004 על שאלה זו כך: \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שאין רשאים להקדיש את עוברה של המבכרת אלא בקדושה חמורה כקדושת עולה, אמורים דווקא \u0003בזמן שבית המקדש\u0004 היה \u0003קיים,\u0004 והיו הקדשים קרבים על המזבח. ואילו \u0003כי קאמינא אנא\u0004 \u0005[כאשר אמרתי אני]\u0006 שמותר להטיל בו מום ולהפקיעו מן הקדושה — הרי זה דווקא \u0003בזמן הזה, דלא חזי\u0004 \u0005[שאינו ראוי]\u0006 \u0003להקרבה,\u0004 וממילא עתיד הוא להיאכל כחולין לכשיפול בו מום.","ומקשים על תירוץ זה: \u0003אי\u0004 \u0005[אם]\u0006 אמר רב יהודה את שיטתו זו רק \u0003בזמן הזה\u0004 — \u0003מאי למימרא\u0004 \u0005[מה,\u0006 מקום יש \u0005לומר\u0006 זאת\u0005]?\u0006 והרי פשוט הדבר! ומשיבים: ראוי לומר זאת, שכן \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]:\u0006 \u0003נגזר\u0004 \u0005[נגזור,\u0006 נאסור\u0005]\u0006 להטיל מום בבכור אף קודם שיצא לאויר העולם, משום החשש \u0003דלמא נפיק\u0004 \u0005[שמא\u0006 כבר \u0005יצא]\u0006 לאויר העולם \u0003רוב ראשו\u0004 של העובר, ובכך נחשב כבר לנולד, וכבר התקדש הבכור בכך, \u0003וקשדי ביה מומא\u0004 \u0005[ויטיל בו מום],\u0006 והרי זה כמטיל מום בקדשים,","\u0003ואימא\u0004 \u0005[ויאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך,\u0006 אף באופן זה, \u0005גם כן]\u0006 אסור הדבר. משום כך, השמיענו רב יהודה כי \u0003אפילו הכי\u0004 \u0005[כך]\u0006 — \u0003הא\u0004 \u0005[\u0006היתר \u0005זה]\u0006 להטיל מום בבכור לפני שיצא לאויר העולם כדי שיוכלו לשוחטו מיד כחולין \u0003עדיפא יתירא\u0004 \u0005[עדיף יותר]\u0006 מהחשש שמא יצא כבר רוב ראשו והרי זה כמטיל מום בקדשים, \u0003מדאתי ביה\u0004 \u0005[משום\u0006 שאפשר לחשוש \u0005שיבוא בו]\u0006 הכהן אם נאסור עליו לעשות כן, \u0003לידי\u0004 איסור \u0003גיזה ועבודה\u0004 בו.","עוד שנינו במשנה מה הדין אם אמר הבעלים על עובר הבהמה המבכרת \u0003\"אם נקבה\u0004 תקדש ל\u0003זבחי שלמים\".\u0004 ותוהים על כך: מדוע בבהמה המבכרת צריך להקדישה לשלמים, כדי לפטור בכך את הולד מקדושת הבכור, וכי \u0003נקבה מי קא קדשה\u0004 \u0005[האם היא מתקדשת]\u0006 \u0003בבכורה\u0004 שיש צורך להפקיע קדושה זו? והלא אין בכור אלא זכר! ומשיבים: \u0003סיפא אתיא\u0004 \u0005[\u0006ב\u0005סוף\u0006 חלק זה של המשנה \u0005בא,\u0006 עבר\u0005]\u0006 \u0003ל\u0004ענין אחר, שהוא עוסק ב\u0003בהמה\u0004 של \u0003הקדש,\u0004 שרוצה להפקיע את הולד שבמעיה מקדושת אמו. וכגון שהאם קדושה בקדושת חטאת, ולכשיוולד העובר יהא דינו למיתה כדין \"ולד חטאת\", ובדרך זו של הערמה הריהו מבקש להביאו לקדושה אחרת.","מאחר שהעמדנו את המשך דברי המשנה בבהמת הקדש, מבררים את המשך הדברים, שאם \u0003ילדה שני זכרים\u0004 — אחד מהם יקרב כקרבן עולה לנדר הבעלים, והשני ימכר לחייבים בהבאת עולה, ודמיו חולין. וכן אם ילדה שתי נקיבות — אחת מהן תקרב לשלמים, והשניה תימכר לחייבי שלמים ודמיה חולין. ו\u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003אי\u0004 \u0005[אם]\u0006 מדובר ב\u0003בהמה\u0004 מעוברת של \u0003הקדש,\u0004 אם כן \u0003היאך דאקדיש\u0004 \u0005[\u0006עובר זכר \u0005זה שהקדיש]\u0006 אותו ל\u0003עולה\u0004 — אכן \u0003ליהדר\u0004 \u0005[יחזור,\u0006 יבוא לכלל\u0005]\u0006 קדושת \u0003עולה,\u0004 ואולם \u0003אידך\u0004 \u0005[\u0006הזכר \u0005האחר]\u0006 שילדה — \u0003נהוי בקדושתיה דאימיה\u0004 \u0005[שיהיה בקדושתה של אמו],\u0006 ודמיו יהיו של הקודש! ומשיבים: \u0003סיפא אתאן\u0004 \u0005[סוף\u0006 המשך זה של דברי המשנה \u0005בא]\u0006 \u0003ל\u0004ענין \u0003בהמת חולין\u0004 המבכרת.","שנינו בסוף המשנה את שיטת רבן שמעון בן גמליאל שאם \u0003ילדה טומטום ואנדרוגינוס\u0004 — אין קדושה חלה עליהם."],["ומכלל לשונו זו של רבן שמעון בן גמליאל עולה שאין הוולדות הטומטום והאנדרוגינוס קדושים כלל בכל אופן שהוא, ואף אם נולדו לבהמת הקדש, ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין קדושה חלה עליהן\u0004 מכח קדושת אמם? ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003רבן שמעון בן גמליאל\u0004 כי \u0003ולדות קדשים\u0004 — רק \u0003בהוייתן\u0004 (בהיותם, בהיוולדם) \u0003הן קדושין\u0004 (מתקדשים). וראיה לדבר, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר כי כבר \u0003ממעי אמן הן קדושין, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין קדושה חלה עליהן? הא תפסתינהו\u0004 \u0005[הרי\u0006 כבר \u0005תפסתן,\u0006 חלה עליהם\u0005]\u0006 ה\u0003קדושה דאימייהו\u0004 \u0005[של אמם]!\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ולדי קדשים\u0004 רק \u0003בהוייתן הן קדושים. ו\u0004אילו","\u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 (החולק על רבן שמעון בן גמליאל) \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003ולדי קדשים\u0004 — \u0003ממעי אמן הן קדושים. דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים\u0006 בברייתא\u0005]\u0006 על האמור בדין הבכור \"אך בכור אשר יבוכר לה' בבהמה לא יקדיש איש אותו\" (ויקרא כז, כו): \u0003אילו לא נאמר\u0004 פסוק זה בשלמותו אלא חלק ממנו: \"אך \u0003בכור\u0004 אשר יבוכר לה' \u0003לא יקדיש\", הייתי אומר\u0004 שהכתוב מתייחס לאדם המקדיש, וללמדנו ש\u0003בכור\u0004 אדם \u0003לא יקדיש\u0004 כל \u0003הקדישות,\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) במלים \u0003\"איש אתו\"\u0004 — שהכתוב מדבר בהקדש שמקדיש בכור אדם (\"איש\") את בכור הבהמה (\"אותו\"), וללמדנו כי דווקא \u0003אותו\u0004 את בכור בהמה \u0003אי\u0004 (אין) \u0003אתה\u0004 הקדוש בבכור אדם \u0003מקדיש\u0004 לקדושה אחרת, \u0003אבל מקדיש אדם בכור\u0004 שאר \u0003הקדישות.\u0004","\u0003ועדיין אני אומר:\u0004 דווקא \u0003הוא\u0004 בכור אדם — הוא ש\u0003לא יקדיש\u0004 את בכור הבהמה לקדושה אחרת, \u0003אבל יקדישוהו אחרים\u0004 שאינם בכורים. לכך \u0003תלמוד לומר\u0004 הכתוב הנוסף \u0003\"בבהמה\"\u0004 — רק \u0003ב\u0004בכור \u0003בהמה עסקתי\u0004 בכתוב זה ולא דובר בו כלל בבכור אדם, וללמדנו שלכל אדם אסור להקדיש בכור בהמה להקדש אחר.","ועדיין יש לברר ולשאול: \u0003יכול\u0004 שהדין הוא ש\u0003לא יקדישנו\u0004 את בכור הבהמה לקדושה אחרת אף כשהוא עדיין ולד \u0003בבטן\u0004 אמו? לכך \u0003תלמוד לומר\u0004 במלים \u0003\"אשר יבכר לה'\"\u0004— רק \u0003מ\u0004זמן \u0003שיבוכר לה',\u0004 שיצא מבטן אמו והתקדש, \u0003אי\u0004 (אין) \u0003אתה מקדיש\u0004 אותו לקדושה אחרת, \u0003אבל אתה מקדיש\u0004 אותו לקדושה אחרת בהיותו עדיין \u0003בבטן\u0004 אמו.","\u0003יכול\u0004 שיהא דין זה \u0003אף\u0004 ב\u0003ולדי כל הקדשים כן,\u0004 שיהא מותר להקדישם לקדושה אחרת בהיותם במעי אמם? — לכך \u0003תלמוד לומר\u0004 במלה \u0003\"אך\"\u0004 — כי \u0003חלק\u0004 (הבדיל) הכתוב בין דין הבכור, שמותר להקדיש אותו בהיותו במעי אמו לקדושה אחרת, ואין הוא נוהג בשאר הקדשים. ונסכם: \u0003אלמא סבירא ליה\u0004 \u0005[מכאן\u0006 נלמד כי \u0005סבור הוא,\u0006 תנא זה\u0005]\u0006 ש\u0003ולדי קדשים ממעי אמן הן קדושין.\u0004","שנינו במשנה כי יכול אדם להערים על הבכור, באופן שיקדישנו לעולה עוד בהיותו במעי אמו, שכיון שעדיין לא יצא מבטן אמו, עדיין לא התקדש בקדושת הבכור. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עמרם לרב ששת\u0004 בעיה זו: אם הבעלים \u0003אמר על\u0004 העובר \u0003הבכור:\u0004 \u0003\"עם יציאת רובו\u0004 מבטן אמו (שהוא זמן שבו חלה קדושת בכור) יקדש זה ל\u0003עולה\",\u0004 מה דין הולד? האם \u0003עולה הוי\u0004 \u0005[הינו]\u0006 \u0003או בכור הוי\u0004 \u0005[הינו]?\u0006","וצדדי השאלה: האם \u0003עולה הוי\u0004 \u0005[הינו]\u0006 — משום שהיא חמורה יותר ולכן \u0003כל פורתא ופורתא דקא נפיק\u0004 \u0005[קצת וקצת\u0006 ממנו \u0005שהוא יוצא]\u0006 מבטן אמו \u0003הוא\u0004 חלק מקרבן עולה שהוא \u0003כליל\u0004 (כולו) לה' ומן הדין שקדושה זו היא שתתפוס. \u0003או\u0004 שמא \u0003בכור הוי\u0004 \u0005[הינו],\u0006 משום שבדרך כלל קדושת הבכורות חלה בעצם לידתם ואם כן \u0003כל פורתא ופורתא דקא נפיק\u0004 \u0005[קצת וקצת שהוא יוצא],\u0006 \u0003במילתיה\u0004 \u0005[בדברו,\u0006 בעניינו\u0005]\u0006 בקדושת בכור \u0003הוא?\u0004","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בהצגת צדדי בעיה זו: האם עולה הוא, \u0003שכן קדושה\u0004 חמורה זו של עולה \u0003חיילא עליה\u0004 \u0005[חלה עליו].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בכור הוי\u0004 \u0005[הינו]\u0006 — \u0003שכן קדושתו\u0004 חלה עליו בידי שמים, בעצם היציאה \u0003מרחם\u0004 האם.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי תיבעי\u0004 \u0005[מה תישאל]\u0006 \u0003לך\u0004 שאלה זו, והרי \u0003היינו דבעי\u0004 \u0005[זהו,\u0006 שאלה כגון זו, \u0005ששאל]\u0006 החכם \u0003אילפא: אמר\u0004 בעליו של השדה הנקצר \u0003על הלקט\u0004 (השבלים הנופלות מהמגל, שהן בכלל מתנות עניים, ואין העשירים רשאים לקחתן): \u0003\"עם נשירת רובו\u0004 מן המגל (שאז חל דין לקט עליו) \u0003יהא הפקר\u0004 לכל (אף לעשירים)\", מה דינן של השבלים? האם \u0003לקט הוי\u0004 \u0005[הינו],\u0006 \u0003או הפקר הוי\u0004 \u0005[הינו]?\u0006","וצדדי השאלה: האם \u0003לקט הוי\u0004 \u0005[הינו]\u0006 — \u0003שכן קדושתו בידי שמים\u0004 (שהרי הוא מתקדש בלא שיקדישנו אדם, אלא בעצם נפילתן מהמגל ובציווי הקדוש ברוך הוא), \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הפקר הוי\u0004 \u0005[הינו],\u0006 שהרי יפה כוחו, \u0003שכן\u0004 בדרך זו \u0003זוכין בו עניים ועשירים?\u0004","\u0003ואמר אביי\u0004 על בעייתו זו של אילפא: \u0003מאי תיבעי ליה\u0004 \u0005[מה נשאלה לו],\u0006 שהרי אין מקום לבעיה זו, שכן כלל הוא כי \u0003דברי הרב\u0004 (הקדוש ברוך הוא) בתורה, שלקט הוא, \u0003ודברי תלמיד\u0004 (האדם) שהפקירו אף לעשירים, \u0003דברי מי שומעים? הכי נמי\u0004 \u0005[כך גם כן]\u0006 בבעייתו של רב עמרם יש לומר: דברי הרב ודברי התלמיד, \u0003דברי מי שומעים?\u0004 ואף עובר זה, הריהו קדוש בקדושת בכור, ולא בקדושת עולה.","אדם \u0003האומר\u0004 על בהמת החולין המעוברת שלו: \u0003\"ולדה של\u0004 בהמה \u0003זו\u0004 יקרב ל\u0003עולה, והיא\u0004 עצמה תיקרב ל\u0003שלמים\"\u0004 — \u0003דבריו קיימים,\u0004 ויקרב הולד לעולה. שהרי הקדים בדבריו את קדושת הולד לקדושת האם. ואם אמר \u0003\"היא\u0004 תקרב ל\u0003שלמים, וולדה\u0004 יקרב ל\u0003עולה\",\u0004 שהקדים את קדושת האם לקדושת הולד — \u0003הרי\u0004 דינו של ולד \u0003זה\u0004 כדין \u0003ולד זבחי שלמים,\u0004 שכיון שהקדים את קדושת האם, וחלה עליה קדושת שלמים, הריהי חלה אף על כל מה שבקרבה ובכלל זה גם על הולד. אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר ר' יוסי: אם לכן\u0004 (לכך) \u0003נתכוין\u0004 מ\u0003תחלה,\u0004 שכאשר אמר על האם שתהא לשלמים חשב שמיד לאחר מכן יאמר על הולד שיהא לעולה, \u0003הואיל ואי אפשר לקרות שני שמות כאחת\u0004 (בבת אחת) — כל \u0003דבריו קיימין,\u0004 שהאם שלמים והולד עולה. \u0003ואם\u0004 לא כך היתה כוונתו, אלא \u0003משאמר\u0004 (לאחר שאמר) \u0003\"הרי זו שלמים\" נמלך ואמר \"ולדה עולה\"\u0004 — \u0003הרי זו ולדה\u0004 גם הוא \u0003שלמים,\u0004 שטרם שנמלך כבר חלה על הולד קדושת אמו.","\u0003אמר ר' יוחנן: הפריש\u0004 בהמה לצורך קרבן \u0003חטאת,\u0004 והיתה אותה בהמה \u0003מעוברת וילדה\u0004 נקבה — הרי שתיהן קדושות בקדושת חטאת, אם \u0003רצה\u0004 — \u0003בה\u0004 עצמה הוא \u0003מתכפר,\u0004 ואם \u0003רצה\u0004 — \u0003בולדה\u0004 הוא \u0003מתכפר,\u0004 שכיון שהקדישה כשהיתה כבר מעוברת, הרי זה כאילו הקדיש גם את העובר בפני עצמו.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להלכה זו? \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוחנן\u0004 שהמקדיש בהמה מעוברת לחטאת, \u0003אם שיירו\u0004 (השאירו) את העובר שיהיה חולין, וכגון שאמר \"העובר חולין, והיא לחטאת\" — הרי זה אכן \u0003משוייר,\u0004 והריהו חולין, אף שאמו הריהי חטאת.","שסבור ר' יוחנן ש\u0003עובר לאו\u0004 \u0005[לא]\u0006 כ\u0003ירך\u0004 (חלק מגוף) \u0003אמו הוא.\u0004 ולכן, כשם שיכול הוא לשייר את העובר שלא תחול עליו קדושת אמו, כן יכול הוא להקדיש את העובר לקדושה שונה מקדושת אמו. \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003כמפריש שתי\u0004 בהמות לקרבנות \u0003חטאות לאחריות\u0004 (לחובתו) — ויקריב איזו מהן שירצה, שאם \u0003רצה\u0004 — \u0003מתכפר בה\u0004 באחת מהן, ואם \u0003רצה\u0004 — \u0003מתכפר בחבירתה.\u0004","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אלעזר\u0004 על שיטתו זו של ר' יוחנן ממה ששנינו במשנתנו: אם אמר \u0003\"היא שלמים וולדה עולה\"\u0004 — \u0003הרי זה ולד שלמים, ו\u0004מעתה יש לשאול: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שכאשר \u0003שיירו\u0004 הריהו \u0003משוייר,\u0004 שהולד המשוייר עומד לעצמו, כיישות נפרדת, אם כן מדוע נאמר על הולד \u0003\"הרי זה ולד שלמים\",\u0004 שחלה קדושת אמו עליו, \u0003\"הרי זו שלמים\"\u0004 בפני עצמו \u0003בעי מיתנא\u0004 \u0005[צריך לשנות],\u0006 שהרי הוא יישות נפרדת. ועל כרחך מזה ששנה \"הרי זה ולד שלמים\", משמע שאינו ישות בפני עצמו, ותחול עליו קדושת אמו בכל מקרה!","\u0003אמר רב טבלא: בר מינה דההיא\u0004 \u0005[חוץ ממנה,\u0006 הוצא \u0005אותה\u0006 משנה\u0005]\u0006 שכן היא משובשת. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב לתנא\u0004 \u0005[לשונה המשניות]\u0006 שלפניו, ששנה את משנתנו: אל תשנה בנוסח \"הרי זה ולד שלמים\", אלא כך \u0003תני\u0004 \u0005[שנה]\u0006 אותה \u0003\"הרי זו שלמים\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי ר' יוחנן אלה ממה ששנינו בברייתא: \u0003האומר לשפחתו\u0004 הכנענית \u0003\"הרי את\u0004 \u0003שפחה\u0004 כשהיית, \u0003ו\u0004אולם \u0003ולדך\u0004 הריהו \u0003בן חורין\",\u0004 שכתב לה כך בשטר שחרור ונתנו בידה, \u0003אם היתה עוברה\u0004 (מעוברת) — \u0003זכתה לו\u0004 (עבורו), לבנה, והריהו יוצא לחירות.","ומעתה יש לדון בדבר: \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אומר אתה]\u0006 ש\u0003אם שיירו\u0004 — \u0003אינו משוייר,\u0004 וכן ש\u0003עובר\u0004 — \u0003ירך אמו, משום הכי\u0004 \u0005[כך]\u0006 \u0003זכתה לו, והוי ליה\u0004 \u0005[והרי זה]\u0006 \u0003כ\u0004אדם ה\u0003משחרר חצי עבדו,\u0004 שיצא בכך העבד לחירות, \u0003ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא. כדתניא\u0004 \u0005[כמו ששנינו\u0006 בברייתא\u0005]:\u0006"],["האדון \u0003המשחרר\u0004 רק את \u0003חצי עבדו\u0004 — \u0003יצא\u0004 בכך חציו של העבד \u0003לחירות,\u0004 והריהו חצי עבד וחצי בן חורין. ואף שאין לעבד \"יד\" לזכות בדבר, מכל מקום הריהו זוכה בעצמו משום ש\u0003גיטו\u0004 (שטר שחרורו) \u0003וידו\u0004 (רשותו, יכולתו לזכות בדברים) \u0003באין כאחת. ו\u0004אולם","\u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי כאשר \u0003שיירו\u0004 — הריהו \u0003משוייר,\u0004 ו\u0003עובר לאו\u0004 \u0005[לא]\u0006 \u0003ירך אמו הוא,\u0004 והרי העובר והאם שתי ישויות נפרדות, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם שחרר רק את הולד, ושייר את האם \u0003זכתה לו\u0004 האם לעובר את שחרורו? והלא היא כאדם אחר ביחס אליו, ושניהם הריהם עבדים של אותו אדון, \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נראין\u0004 הדברים \u0003שהעבד\u0004 האחד \u0003זוכה לקבל\u0004 (יכול לשמש כשליח קבלה) של \u0003גט\u0004 (שטר) \u0003שחרור של חברו\u0004 (עבד אחר) \u0003מיד רבו\u0004 (אדונו) של חבירו, ובלבד \u0003שאינו\u0004 האדון \u0003שלו\u0004 (של העבד המקבל), \u0003ו\u0004אולם כאשר שני העבדים הינם של אדון אחד, \u0003לא\u0004 יכול עבד זה לקבל שטר שחרור של העבד האחר \u0003מיד רבו שלו.\u0004 ואף כאן, כיצד האם מקבלת שטר שחרור עבור ולדה מיד האדון המשותף לשניהם? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003אם שיירו\u0004 — \u0003אינו משוייר, ו\u0004הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן.\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 כי שאלה זו \u0003אם שיירו\u0004 — \u0003משוייר\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא? דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 האדון \u0003האומר לשפחתו\u0004 הכנענית שהיתה מעוברת: \u0003\"הרי את\u0004 משוחררת, והינך איפוא \u0003בת חורין, ו\u0004אולם \u0003ולדך\u0004 הריהו \u0003עבד\"\u0004 — \u0003ולדה כמוה,\u0004 שכאשר היא משתחררת — אף הולד משתחרר. אלו \u0003דברי ר' יוסי הגלילי. ו\u0004אילו \u0003חכמים אומרים: דבריו קיימין,\u0004 והולד לכשיוולד, יהיה עבד. וטעמם של חכמים: \u0003משום שנאמר \"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד).","ותוהים: \u0003קרא\u0004 \u0005[מקרא]\u0006 זה, \u0003מאי תלמודא לרבנן\u0004 \u0005[מה,\u0006 כיצד הוא \u0005מלמד ל\u0006שיטת \u0005חכמים],\u0006 שולד שפחה משוחררת יכול להיות עבד? \u0003אמר רבא:\u0004 שונה ברייתא זו \u0003אמר קרא\u0004 \u0005[מקרא]\u0006 זה לא כמקור לשיטת חכמים, אלא כמקור \u0003ל\u0004שיטתו של \u0003ר' יוסי הגלילי\u0004 הסבור ככלל שהולדות הולכים אחר האם, ולכן אם האם משוחררת — גם ולדותיה משוחררים. ומנין שכך סבור הוא? — \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בשיטת ר' יוסי הגלילי ש\u0003ולדה כמוה, שנאמר: \"האשה וילדיה תהיה לאדניה\",\u0004 וללמד: \u0003בזמן שהאשה לאדוניה\u0004 — אף \u0003ולדה לאדוניה,\u0004 ובזמן שאין האשה ברשות אדוניה, שהרי נשתחררה — אף ולדותיה משוחררים.","ומעתה דנים בדבריהם: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בכך נחלקו],\u0006 ש\u0003ר' יוסי\u0004 הגלילי \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003שיירו\u0004 — \u0003אינו משוייר,\u0004 שאין אלה שתי ישויות, ודין האם כדין הולדות, \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 שיירו — \u0003משוייר,\u0004 ונמצא איפוא ששיטת ר' יוחנן ששיירו משוייר, אינה כשיטת ר' יוסי הגלילי?","ודוחים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ר' יוחנן: דכולי עלמא\u0004 \u0005[\u0006לשיטת \u0005הכל]\u0006 \u0003שיירו\u0004 — \u0003משוייר, והכא היינו טעמא\u0004 \u0005[וכאן,\u0006 בדין המשחרר את שפחתו ומשייר את ולדה, \u0005זהו הטעם]\u0006 של ר' יוסי הגלילי, שאף הולד משוחרר, שכן ר' יוסי עצמו מסביר בטעם הדבר שהוא משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במפורש \u0003\"האשה וילדיה תהיה לאדניה\",\u0004 ומכאן שהולדות הולכים אחר האם לענין כגון זה, ולא משום ש\"ולד ירך אמו\".","\u0003אלא\u0004 מציעים עוד: \u0003ודאי לימא כי הני תנאי\u0004 \u0005[אמור\u0006 שדין שיירו משוייר הריהו \u0005כמו אותם תנאים\u0006 שנחלקו ביניהם בכך\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט את החטאת\u0004 (ואנו מניחים שהקדישה כשהיתה מעוברת), להקריבה על המזבח, \u0003ומצא בה\u0004 עובר \u0003בן ארבעה\u0004 חודשים \u0003חי,\u0004 נחלקו תנאים בדינו של זה: \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 הועילה לו לולד זה שחיטת אמו, ומעשהו כמעשה החטאת לכל הלכותיה: \u0003אין\u0004 היא \u0003נאכלת אלא לזכרי כהונה\u0004 בלבד, \u0003ואינה נאכלת אלא ליום אחד\u0004 בלבד, \u0003ואינה נאכלת אלא לפנים מן הקלעים\u0004 (במקדש בלבד).","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 שאמנם הועילה לולד זה שחיטת האם, להתירו באכילה, ואולם הריהו חולין לכל דבר, ומשום כך \u0003נאכלת לכל אדם, ונאכלת בכל מקום, ונאכלת לעולם\u0004 (ללא הגבלת זמן).","ומציעים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 היא, שכן \u0003תנא קמא סבר\u0004 \u0005[התנא,\u0006 הברייתא, \u0005הראשון סבור]:\u0006 \u0003שיירו\u0004 — \u0003אינו משוייר,\u0004 והאם והולד כישות אחת, ומשום כך חלים על הולד כל דיני האם. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה\u0006 שבברייתא השניה \u0005סבור]:\u0006 \u0003שיירו\u0004 — \u0003משוייר,\u0004 ודין הולד הריהו לעצמו, כחולין. ונמצא איפוא ששיטת ר' יוחנן במחלוקת תנאים היא מצויה.","ודוחים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך ר' יוחנן: דכולי עלמא\u0004 \u0005[\u0006לשיטת \u0005הכל]\u0006 \u0003אם שיירו\u0004 — \u0003משוייר,\u0004 ויכול אדם להקדיש בהמה מעוברת ולשייר את עוברה כחולין, \u0003ו\u0004אילו \u0003הני תנאי בהא קמיפלגי\u0004 \u0005[אלו התנאים ב\u0006דבר \u0005זה הם חולקים],\u0006 בבהמה שהוקדשה לחטאת ואחר כך התעברה, שכאשר הוקדשה לא הוקדש ולדה, ולא בזו שכבר היתה מעוברת בשעה שהקדישה, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 בברייתא השניה \u0005סבור]:\u0006 \u0003ולדי קדשים\u0004 — רק \u0003ב\u0004שעת \u0003הוייתן\u0004 (לידתם) \u0003הן קדושים\u0004 (מתקדשים), ועובר זה שלא נולד (שהרי הוציאוהו חי מתוך אמו) — לא התקדש, ודינו כחולין. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה\u0006 שבברייתא הראשונה \u0005סבור]\u0006 כי \u0003ולדי קדשים\u0004 — כבר \u0003במעי אמן הן קדושים,\u0004 וולד זה, אף שעדיין לא נולד — מתקדש משעה שנוצר בבטן אמו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למחלוקת ברייתות אלה, ובאופן זה: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 על שיטת ר' יוחנן והכל סבורים ששיירו משוייר, ואף הכל סבורים שולדות הקדשים מתקדשים עם לידתם, ושתי הברייתות עוסקות במצבים שונים. ש\u0003כאן\u0004 בברייתא השניה — מדובר \u0003ב\u0004מקרה שבזמן \u0003שהקדישה\u0004 עדיין לא היה במעיה עובר, \u0003ו\u0004רק \u0003לבסוף נתעברה,\u0004 ומשום כך, דינו של הולד כחולין לכל דבר, שהרי לא התקדש בשעה שהתקדשה אמו, וכן לא התקדש עם לידתו (שהרי לא נולד).","ואילו \u0003כאן\u0004 בברייתא הראשונה — מדובר \u0003ב\u0004מקרה \u0003שנתעברה ולבסוף הקדישה,\u0004 והתקדש איפוא אף הולד כשהקדיש את הבהמה (שהרי לא שייר את העובר), ודינו כחטאת לכל דבריו.","כהמשך לדיון הקודם בדברי ר' יוחנן \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא: ממאי דטעמא\u0004 \u0005[ממה,\u0006 מנין לנו\u0005, שהטעם]\u0006 של \u0003ר' יוחנן\u0004 הוא ש\u0003אם שיירו משוייר, דלמא היינו טעמא\u0004 \u0005[שמא זהו הטעם]\u0006 של \u0003ר' יוחנן\u0004 משום ש\u0003אדם מתכפר בשבח הקדש,\u0004 ואף ולד זה הריהו שבח הקדש, ואין דבריו שייכים לדין שיירו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא\u0004 לרבא: והרי \u0003ר' אלעזר תלמידיה\u0004 \u0005[תלמידו]\u0006 של \u0003ר' יוחנן\u0004 היה, \u0003ויתיב לקמיה\u0004 \u0005[ויושב היה\u0006 ושונה \u0005לפני]\u0006 \u0003ר' יוחנן,\u0004 והקשה ר' אלעזר לר' יוחנן עצמו (כמובא בעמוד הקודם) ממשנתנו, על סמך ההנחה שר' יוחנן סבור שאם שיירו משוייר, \u0003ולא אהדר ליה האי שינויא\u0004 \u0005[ולא השיב לו\u0006 ר' יוחנן \u0005תירוץ זה]\u0006 שטעמו הוא משום שאדם מתכפר בשבח הקדש — \u0003ואת אמרת טעמא\u0004 \u0005[ואתה אומר\u0006 כי \u0005הטעם]\u0006 של \u0003ר' יוחנן\u0004 הוא \u0003משום\u0004 ש\u0003אדם מתכפר בשבח הקדש?!\u0004","שנינו במשנה בדברי ר' יוסי: \u0003אם מש\u0004 כבר \u0003אמר \"הרי זו שלמים\" נמלך\u0004 בדעתו, והוסיף ואמר \"ולדה עולה\" — הרי זה ולד שלמים. ושואלים: מה השמיענו בכך ר' יוסי, והלא \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא הדין, ש\u0003ולדן שלמים, אלא\u0004 וכי יש לומר ש\u0003כל אימת דבעי, מימלך\u0004 \u0005[כל זמן שירצה, יתחרט]?\u0006","\u0003אמר רב פפא: לא נצרכה\u0004 הלכה זו להיאמר \u0003אלא\u0004 בזמן \u0003ש\u0004נמלך ו\u0003אמר ב\u0004פרק זמן קצר זה שהוא \u0003תוך כדי דיבור\u0004 \"ולדה עולה\". וחידוש יש בדבר: שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003תוך כדי דיבור\u0004 הריהו נחשב \u0003כדיבור\u0004 אחד אף ששהה מעט ויהיה הולד עולה כדבריו, \u0003והאי\u0004 \u0005[וזה]\u0006 שלא אמר כן מייד, אפשר לחשוב כי \u0003עייוני\u0004 \u0005[לעיין]\u0006 \u0003הוא דקמעיין\u0004 \u0005[שמעיין,\u0006 מתבונן באותו דבר\u0005]\u0006 ואינו כמתחרט — לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שהוא נמלך, ואין זה נחשב כדיבור אחד.","אדם שהיו עומדות לפניו שתי בהמות, אחת עולה והשניה שלמים, ואמר על בהמת חולין שלו: \u0003\"הרי זו תמורת עולה תמורת שלמים\"\u0004 — \u0003הרי זו תמורת עולה,\u0004 שכיון שכבר אמר בתחילת דבריו שהיא תמורת עולה, חלה עליה קדושת עולה, ושוב אין חלה עליה קדושת שלמים, שרק דבריו הראשונים חלים. אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר ר' יוסי:\u0004 יש לבודקו, ולברר \u0003אם לכן נתכוין\u0004 מ\u0003תחלה,\u0004 שתכנן מראש לומר כן, \u0003הואיל ואי אפשר\u0004 לאדם \u0003לקרות שני שמות\u0004 (שתי אמירות) \u0003כאחת\u0004 — הרי כל \u0003דבריו קיימים,\u0004 וחציה של בהמה זו הריהו תמורת עולה, וחציה הריהו תמורת שלמים. \u0003ו\u0004אולם \u0003אם\u0004 לא תכנן מראש לומר כן, אלא רק \u0003מש\u0004 כבר \u0003אמר \"תמורת עולה\", נמלך\u0004 בדעתו והוסיף \u0003ואמר \"תמורת שלמים\"\u0004 — \u0003הרי זו\u0004 כולה \u0003תמורת עולה.\u0004"]]};
